/* 平成29年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h29.committeeSessions.push(...[{"id":"h29-20170925-7","meetingId":"h29-cm09","date":"2017年9月25日","dateIso":"2017-09-25","committee":"厚生委員会","time":"午前１０時００分～午後 １時５８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を75件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の２、議案審査、第５９号議案 平成２９年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"の２、議案審査、第５９号議案 平成２９年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"津久井やまゆり園の事件の後の抑止力ということでの防犯対策、東京都障害者施策推進区市町村包括補助事業補助金という名前の補助金ということなのですけれども、半額が東京都から出て半額が一般財源ということでいいのかという確認を一つと、それからこの補助金というのは、こういう防犯対策にということでの補助金なのか。","respondent":"中山障害者福祉課長","answer":"区が実際に事業者に支払う金額の２分の１を東京都が補助するというものになりますので、自治体によってやる区やらない区ありますし、実施するにしても補助率の問題というのはそれぞれの区によって違っているようなところです。","voiceIndex":8,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、プレス発表のほうでは防犯カメラのところで１６施設で非常通報装置のところで３２施設、センサーライトのところが１７施設というふうなことで書かれているのですけれども、この施設の違いというのがどうしてこの１６、３２、１７という違いになっているのかということと、それから防犯カメラというのは１台幾らぐらいするのかということと。","respondent":"中山障害者福祉課長","answer":"その違いがこの件数の違いに表れているようなところです。それから、防犯カメラを幾らで金額を設定しているかですが、工事も入れて単価２５万掛ける２カ所ということで、一応設定しています。","voiceIndex":10,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"虐待というところではなくて、外部からの進入だというところですと、防犯カメラというのは内部には、例えば瑞宝会の場合は多分公共の、共有されているところにも防犯カメラがついていて、そういう事件が起こったところを検証しようと思ったら画像が消されていたという報道もされていたのですけれども、そういう虐待とは関係のない今回の防犯ということですと。","respondent":"中山障害者福祉課長","answer":"津久井やまゆり園の件については元職員ということで、施設の中も知り尽くした職員による犯行ではあったわけなのですけれども、やはりまずは外部に対して、難しいところですね。","voiceIndex":12,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私も防犯カメラをどんなに施設の中につけたからといって、それでその職員の虐待抑止ということにはならないのではないかなと思うのです。それと同時に、実際そういう外部からの侵入者を防ぐというところでの対策でこういう形でつけられるというところは、そうはいってもそういうふうな事件がいろいろあるわけですから、そういうふうな対策は必要だろうなという思いがしております。","respondent":"中山障害者福祉課長","answer":"ご様子、中にはご自身で上手に発言できない方もいらっしゃるので、そういう方につきましては行動観察等をさせていただき、不安なく今のところお過ごしいただいているということをまず確認したところです。区としては、今現在そういう対応をしたところです。","voiceIndex":14,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"本当に虐待というのがかなり件数としても増えているということで、その中でも施設での虐待が増えているという報道がされているところですので、ぜひ今後ともきちんとした虐待の対応というところでお願いしたいと思います。それから、一番最後に、この非常通報装置というのは、去年この委員会に補正で出された１１０番通報システムの設置と同じものということで考えていいのか、確認だけお願いします。","respondent":"中山障害者福祉課長","answer":"委員ご指摘のとおりで、昨年度の補正予算で取りました１１０番通報のことです。","voiceIndex":16,"id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問","question":"外部からの進入の抑止ということで非常にいいなという思いなのですが、ちょっと先の話になるかもしれませんけれども、防犯カメラ１台２５万円というお話があったのですが、これは区として同じ機種を考えているのか、それとも各施設ごとでばらばらに選んでいくのか。その辺はどうなっているのでしょうか。","respondent":"中山障害者福祉課長","answer":"実際に設置するのはそれぞれの施設の運営事業者になりますので、設置についてはお任せをし、特に同じ機種ということでは考えておりません。","voiceIndex":18,"id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"意見","question":"その辺はわかりました。ちょっとほかとの絡みもあるのですけれども、これ、どのぐらいの耐用年数を考えていくのか。今回は一遍にやるから１件１件区が助成していきますけれども、ある程度年数が経ったときに各施設に取り替えをお願いするのか、それともその時期にもう一度区として何か考えていくのか、その辺どういうふうに今捉えているか。","respondent":"中山障害者福祉課長","answer":"防犯カメラ自体は、１０年ぐらいはもつのではないかと思っているのですけれども、防犯カメラを一度今回の補助事業で設置してその後壊れたときに、また区がもう一度設置するかどうかというところまで、申しわけないですが今の段階ではまだ考えていないところです。","voiceIndex":20,"id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"意見","question":"わかりました。ちょっと絡んでいたのが、所管は違うのですけれども、各町会に防犯カメラをつけたときの耐用年数の問題も既に出てきているという話もあるので、その辺が気になったので。今後またその辺を調査しておいてください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"これ、虐待の防止ということではないということなので、相模原のやまゆり園のところからということなのですけれども、あのやまゆり園の問題についての認識というか、本当に障害者は役に立たないから排除してもいいのだという考え方のもとでああいう事件が起こされたというのがあると思うのですけれども、そういう考え方に対しての、そうではないのだよという。","respondent":"中山障害者福祉課長","answer":"そのほか、各法人におきましては法人の取り組みという中で、当然虐待防止研修、人権研修というのを実施しています。","voiceIndex":23,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうことで、津久井のやまゆり園の問題からこれが出ているということなので、この事件がそもそも何だったのかというふうなところに立ち返って考えるというふうなことが必要なのではないかというところでの質問をしました。その障害者権利条約について、職員が学ぶ場というのがあるのかだけちょっと教えてください。","respondent":"中山障害者福祉課長","answer":"各法人で、例えば障害者権利条約についての研修をやっているかどうかまでは把握はしておりませんが、ただこの条約自体はすごく取り上げられてもいますし、当然福祉を学ぶ者としては、条約の中身あるいはその基本的な考え方。","voiceIndex":26,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は障害者権利条約というのは本当に障害者福祉をこれから充実させていく大もとの基本になるものではないかと考えていますので、区としても障害者権利条約を職員が学ぶ機会というのをぜひつくっていただきたいということで要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-011"},{"speaker":"若林委員","kind":"質問・要望","question":"先ほどの質疑の中で、区によって補助率が違うというお話があったので、ちょっとそこを詳しくお聞きしたいと思います。それから、センサーライト、防犯灯、人感センサー等とありますので、この「等」の内容も確認をしておいたほうがいいかなと思いますので、お聞かせいただきたいと思います。","respondent":"中山障害者福祉課長","answer":"今回、品川区は１０分の１０の補助率ということで実施します。これは品川区以外にはあと１区だけです。ほかの区では４分の３の補助率であったり、２分の１の補助率であったり、あるいは実施しないという区もあるような状況です。","voiceIndex":29,"id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"もう一つ、最後に、よくある話かもしれませんけれども、いわゆる設置をして実際に使ってみたら、ちょっとできればこれも追加したいよねというような話って何かよくある話なのかなと思いますので、１０月申請受付で１１月に交付決定がされるというスケジュールなのですが、そういう対応を希望される施設が出てきたら、何か手立てがあるのか、そういう準備があるのか。","respondent":"中山障害者福祉課長","answer":"一度つけた上でもう少しこういうところがみたいな声というのはもしかしたら出てくるのかもしれませんが、一応これでやってみてということで、そのためにアンケートもさせていただき、一度施設の中を点検していただきましたので。","voiceIndex":31,"id":"exchange-013"},{"speaker":"大倉委員","kind":"質問・要望","question":"１カ所、工事を伴う防犯カメラというところで、工事を伴うというのはどういう意味なのかというところを教えていただきたいと思います。もう既に設置されていて、またそれこそ耐用年数のお話もありましたが、交換しようといったときにこういったものが出てきて、それをまた新たにかえるときにこういうのが使えるというところなのかなと思ったのですが、そこについて教えてください。","respondent":"中山障害者福祉課長","answer":"工事を伴うというのは、今簡易型ですぐ取り付けて対応ができる防犯カメラが２万円ぐらいからあると聞いております。それについては今回は補助の対象からは外させていただいたです。","voiceIndex":33,"id":"exchange-014"},{"speaker":"大倉委員","kind":"質問・要望","question":"補助の対象になった理由というか、なぜ２万円の簡易型のものでは防犯というところの抑止力を高めるところには至らないというところなのかどうかを教えていただきたいのと、あともう一つ、教えていただきたいのですが、もう既に設置しているものが古くなったので新しく取り替えるときには今回の補助が使えるのか教えていただければと思います。","respondent":"中山障害者福祉課長","answer":"それで、今後のところについては、先ほどご答弁申し上げましたとおり、いましばらくこれを使ってみてのことで、その後については今後の課題というふうに考えています。","voiceIndex":35,"id":"exchange-015"},{"speaker":"大倉委員","kind":"質問","question":"新規だけということですが、今ついているのより抑止力を高めるために、もうちょっと新しいもののほうがいいなという施設があれば、それはこの補助金を使ってかえられるのかどうか。それともそれはもう既に設置しているものなので、各法人でやってくださいということなのか、その辺だけ教えてください。","respondent":"中山障害者福祉課長","answer":"今回は新規に設置ということで、既に防犯対策を行っている事業所も確かにあります。そういうところは逆に防犯カメラはもう既に設置しているので１１０番通報を入れてほしいというような形でご要望いただいています。","voiceIndex":37,"id":"exchange-016"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"今回区内の民間通所施設およびグループホームに関して補助金を交付して設置するということなのですけれども、この区内、民間の通所とグループホームというのが全部でどれぐらいあるのかということと、希望をとって設置ということだったのですけれども、これ３つ全部を希望するということもできるのですよね。そうなると、３つ全部を希望した施設というのはどれくらいあるのかということを聞かせてください。","respondent":"中山障害者福祉課長","answer":"民間施設が、この統計をとったときは４０カ所あったのですが、今１カ所事業所中止のところがあるので現在３９カ所あります。そのうち全体で３３カ所が今回手を挙げてくださったということになります。それで、３つ全部を希望されたところですが、全部で１９カ所になります。","voiceIndex":39,"id":"exchange-017"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"この３つ全部を希望したところというのは、先ほどほかの委員からもありましたけれども、ついているけれどもさらに充実をさせたいというところなのか、全くつけていなくて今回こういう機会があるからつけようということになっているのかを伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"新規ということでお願いをしているので、今まで防犯対策のそこができていなかったという事業所になります。","voiceIndex":41,"id":"exchange-018"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"この間、人の目で抑止していくというのも大事だと思うのですけれども、職員の配置、人材確保がすごく大変だというのもお聞きするのですけれども、そういったところの対策だったり、あとは少し増員したというところがあったのかどうか伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"こういった障害あるいは児童福祉の支援については人員配置基準というのがありまして、その配置基準を満たしていないとそもそも運営ができないということになっているので、そこの基準は当然各事業所とも満たしているところになります。","voiceIndex":43,"id":"exchange-019"}]},{"id":"topic-02","title":"平成２９年請願第１１号 品川区障害児・者福祉計画の策定時における当事者の参画機会の確保に関する請願","agenda":"平成２９年請願第１１号 品川区障害児・者福祉計画の策定時における当事者の参画機会の確保に関する請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ私は委員会の審査の前にお話を伺って、そして審査に入るというほうがより障害当事者の、また家族の方の声を直接お聞きして、そしてこの審査ももっと深い形での審査にすることができると思いますので、ぜひ意見陳述は冒頭にしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-020"},{"speaker":"若林委員","kind":"意見","question":"これまでの慣例に従って、委員長からご案内のあったとおり、後ほどということでお願いしたいと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この請願そのものが本当に障害者、多くの当事者の意見を聞いてまた意見交換の場を設けてほしいというような項目もありますし、ぜひ、冒頭に聞くということをぜひここら辺でやっていきましょうと私は言いたいのです。もし冒頭ではなくて、後のほうがいいというのであれば、後のほうがいいという理由もちょっと教えていただけないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この請願の一つは全障害児・者を対象としたニーズ把握調査を実施してほしいということなのですけれども、今の説明でも４年前に基礎調査をやったので、それをもとにというご説明で、この請願の中にも４年前に実施したからとの回答でしたと書いてあるのですが、ここにもありますように、かなり社会環境が大きく変化しているという状況はあると思うのです。","respondent":"中山障害者福祉課長","answer":"そうした課題にどう対応していくかというところは、今、相談支援というものが入っておりますので、やはりその中でそれぞれのご家族の状況ですとか、当事者の方のお話、状況なども勘案しながら、実際にサービスというものを組み立てているところです。","voiceIndex":63,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、これからも３年間に一度計画を組み直していくということになると思うのですけれども、そういう点では毎回本当に社会情勢、特に今激動ですから、その中でやはり多様なニーズをしっかりと全障害者の皆さんから受けとめて計画に反映をしていくというところで、私はぜひ全障害者対象のニーズ調査という点ではこれからも取り組んでいただきたいということで。","respondent":"飛田障害者施策推進担当課長、中山障害者福祉課長","answer":"アンケートをとる時期も少し早目にというふうに検討していきたいと考えています。ただ、これで一回障害児の調査の中身というのも見えてきましたので、次回以降は策定の前の年にとるように十分準備はできるかと考えています。","voiceIndex":65,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"次回にはぜひ生かしていただきたいと思います。それで、こういう形で障害児のアンケートのほうも遅くなってしまったわけですけれども、特に品川区は自立支援協議会でこれを策定するということになっていますが、自立支援協議会が３回しかないではないですか。それで、６月にあって、その後は１１月にあって、その次の年の２月でしたか。それで、１１月にはもう骨子案が出てくるわけです。","respondent":"中山障害者福祉課長","answer":"１回目の自立支援協議会のときに、３回しかない会議の中で今回この福祉計画と児の福祉計画の策定ということを念頭に置いておきましたので、初回のときに今までの現在ある計画の中での実際の目標値と達成状況、そうしたもののご説明もさせていただきながら。","voiceIndex":68,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"アンケートに対して本来であればこういうアンケート結果でしたと。そこら辺のところというのは、私もこれは公開されていなかったのでこういうのがあるのも知らなかったのですけれども、６月の段階でこの実績のまとめができていたのに、７月の委員会の中で私はそういうまとめというのはないのですかと聞いたときに、ないと答えられたのは何でだったのかということもちょっと聞かせていただきたい。","respondent":"中山障害者福祉課長","answer":"そういう意味で、実績ということでまとめたものを自立支援協議会の中でお示しし、これが一つの指標になって次の計画に、やはり一つの土台になっていくと思いますので、前回の自立支援協議会ではこうしたお話をさせていただきながら、この間また事情の変わったこと。","voiceIndex":70,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ＰＤＣＡサイクルになっているので、例えば介護保険なんかでは介護保険の運営状況という形で毎年どういうふうな状況になっているのかということが実績というか、状況が報告をされるので、そういうのがこの障害福祉計画ではないのですかと私聞いたのですよ。そうしたら、これが出てきたのでそこのところはどうなのですかと聞いたので、ちょっと答えていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"今回、まずこちら２年間分とっているのは、次の期の福祉計画に向けてということとになっています。実際にはこれに平成２９年度も既に８月実績分までは見えてきておりますので、そうしたものも見合わせながら計画値には反映をさせていく予定です。","voiceIndex":72,"id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はそういうふうなところで、多分何回か、ないのですかと、２回ぐらい議会で聞いたと思うのです。それで、これは、今回ホームページに公開されたのですけれども、そういうことであれば、実績ということでまとめたものというのは、今回「公開」ということにならなかったら、例えば情報公開等でとっても出るものでないというところなのですか。そんなことはないはずです。","respondent":"飛田障害者施策推進担当課長","answer":"今回、障害児のほうでアンケート調査させていただきました。それに伴いまして実績、それからアンケートについてもまたこちらで報告をしたいと思いますので、よろしくお願いいたします。","voiceIndex":74,"id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、やはり本当に障害者の方を抜きに決めないでというのが、障害者運動の大きなベースになっているわけですから、あらゆる場面で障害者の声を聞いて、障害者の皆さんと一緒に、家族の皆さんと一緒に計画をつくるという姿勢をぜひ貫いていただきたいなと思うのです。障害者団体は希望すればどの団体でも団体ごとに意見を聞く場というのをつくるという考えなのか。","respondent":"中山障害者福祉課長","answer":"団体に入ってない方については、今回アンケート調査を実施していないというところではあるのですが、個別のニーズのところについては地域の相談支援を通じて声が上がってきているところもありますので。","voiceIndex":76,"id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"それ以外のところでも７団体以外の団体の方々からも会員の皆さんが集まりますので、ぜひこの計画に対して意見を言いたいという場を、意見を聞く場をつくってくださいというふうなことで申し入れをすれば、その意見を聞く場をつくっていただけるということで確認させていただいていいでしょうか。そしてまたそれが具体的にいつぐらいになるのかということもお聞かせください。","respondent":"中山障害者福祉課長","answer":"いつぐらいというところなのですが、まず７団体の会長会は１０月の中旬までにはという形で日程調整を今しています。","voiceIndex":78,"id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、あと先ほども申し上げた、団体に所属していない障害者、家族の方の意見を聞く場、それはとりあえずは区としては今やる考えはないということなのかということと、あと、障害者や家族の方の意見だけでなく、私は全区民を対象にした説明会、この計画が、素案とか骨子案という形でできた段階でパブリックコメントをとる前に区民説明会をぜひ開いていただきたいと思うのですけれども。","respondent":"中山障害者福祉課長","answer":"パブコメ前の計画に対する区民全体への説明会ということですけれども、一応パブリックコメントを実施する中で広く当事者の方、家族の方、区民の方からご意見をいただければと考えております。","voiceIndex":80,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこでたくさん意見も出るし、また目黒区は障害者の方の全てを集めた要望を受けて、それに答えるみたいな場面もつくっているということなので、障害者の方々から意見を聞いたり、また意見交換をする場というのがかなり保証されていると聞きました。何で品川だけがやらないのかなといつも思っているのですけれども、やらない理由というのは何なのでしょうか。","respondent":"中山障害者福祉課長","answer":"できるだけ当事者の方のご意見とかニーズを把握した上でこの計画は策定されるべきものであると当然思ってはいるところではありますが、個別の説明会というところでは、現状のところ考えてはおりません。","voiceIndex":82,"id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"理解を深め合っていくという取り組みの機会にもぜひしていただきたいと思うのです。区の行政自身も、家族・関係者、区民から広く意見を聞いて受けとめるという場をぜひつくっていただきたい。そのためにも、区民への説明会をぜひやっていただきたいと思うのですけれども、そういう観点からはいかがでしょうか。","respondent":"中山障害者福祉課長","answer":"ただ、その計画に際して、パブリックコメントでまずはご意見を聞きながら計画を策定していくということで区民、一般の皆様に向けての説明会については現在予定をしていないです。","voiceIndex":84,"id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"説明会をやらない理由というのは何なのでしょうか。ほかの区はみんなやっているのに、品川区だけやらないというその理由は何なのか、お聞かせください。","respondent":"中山障害者福祉課長","answer":"ただ、計画の策定のスケジュールのことですとかプロセスのところもありますので、なかなかできたものをパブリックコメントの前に説明して、そこでまたご意見を反映するというのも時間的なものもありますし、今後はちょっとスケジュールを長めにとって。","voiceIndex":86,"id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう中で、ほかの近隣区全部が説明会をやっているわけですから、そういう点ではやはりこの区民に対して理解を広げる、関心をさらに広げる、そして区民からの意見も反映をさせて充実をさせていく、そういう視点を持って説明会をやっていただくということをぜひ、ご検討いただきたいということで要望をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-035"},{"speaker":"鈴木（真）委員","kind":"質問","question":"自民党・子ども未来としてもこの請願に対して請願者の方から何人かお話もお聞きし、もちろん会派の中でいろいろ勉強した上で質問が多岐にあったのですが、今大分出ていましたので、重ならない部分でお聞きしていきたいと思います。先ほど、予算面だけでなく指針が出てないということもあったということ、その辺はご理解はいただいているのでしょうか。","respondent":"中山障害者福祉課長","answer":"対応した者に確認したところ、そこまでの話はさせていただいていないとのことでした。","voiceIndex":89,"id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"質問","question":"改めてそこら辺はきちんと説明していくべきだと思いますし、その時点ではなくその後の時点で説明はなさったのかどうか。その辺はまだ理解されていないのかどうか、教えてください。","respondent":"中山障害者福祉課長","answer":"この請願をいただいて、この間ちょっとこちらの団体ともお話をする機会がなかったので、改めて団体とお話をする場を設けさせていただければと思います。","voiceIndex":91,"id":"exchange-037"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"委員会でこういう話もあったし、その辺はよくこれからご説明をしておいていただきたいので、これはお願いします。それから、自立支援協議会に当事者の参加という話なのですが、メンバーとしてどういうメンバーかもう一回確認をさせてください。","respondent":"中山障害者福祉課長","answer":"自立支援協議会のメンバーですが、委員長に学識経験者を置くほか、区内のサービス事業者、法人ですね、それからあと特別支援学校の校長、医療関係者、法律関係者、それから７団体の代表、それと区の各障害施策に関係する部長級職員で構成されるものです。","voiceIndex":93,"id":"exchange-038"},{"speaker":"鈴木（真）委員","kind":"質問","question":"私も請願者のお話をちょっと聞いたときに、７団体の中の当事者という扱いがどういうふうにとられるかということが課題かなと思ったのですが、当然、そのメンバーをあまり個別に言ってしまうといけないかもしれないですが、ご家族としての当事者というケースと、ご本人自体が当事者というケース、ご本人が当事者という方がこのメンバーに入っていらっしゃるのでしょうか。","respondent":"中山障害者福祉課長","answer":"今の自立支援協議会のメンバーの中に当事者の方はいらっしゃいます。立場としては、当事者という立場ではなく事業者という立場と、あと医師という立場で入っていただいているのですが、実際に車椅子の方がお二人委員でいらっしゃいます。","voiceIndex":95,"id":"exchange-039"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"わかりました。先ほどお話もありましたように、ご本人たち、この３年間の間にいろいろな立場も変わって、例えば就労の問題とかいろいろあるということもお聞きしていますので、その辺をもう一度意識を持った上で今後の方向性についてはもう一回ちょっとご確認をお願いします。","respondent":"中山障害者福祉課長","answer":"今回この請願をいただいたということは、やはりこの間、障害者福祉課でプロセスがよく見えてこなかった、当事者の方の意見が十分反映されていないではないかという思いがこの請願にあらわれていると考えていますので、そこは反省をし。","voiceIndex":97,"id":"exchange-040"},{"speaker":"若林委員","kind":"質問・要望","question":"この障害児福祉計画のお話が７月の厚生委員会にご報告があったときに、そのときに障害福祉計画については確かにこの委員会に対していわゆるニーズ調査、アンケート、これは用いませんよということで私どももその審議の中で了としたという経緯の中で、今回いわゆる当事者の方から請願が出されたというふうな流れを一つ確認をしながら、やはり最大のご心配は今の質疑の中でもありましたけれども。","respondent":"中山障害者福祉課長","answer":"第４期の福祉計画の策定に当たりまして、ニーズ調査あるいは日ごろの相談の中からの声を反映したところで、第４期は特にやはりグループホームの設置ですとか、社会参加への声、移動支援とか同行援護ですね、それから日常生活の支援。","voiceIndex":99,"id":"exchange-041"},{"speaker":"若林委員","kind":"確認","question":"そこら辺については、本当にこの先の話ですけれども、今回はもう障害福祉計画についてはとりませんということで、スキル的にはもう了とするしかないのですけれども、３年後、またその次の３年後、毎回の３年ごとにしっかりとアンケートという形で声をお聞きするということをどのように今お考えか、これはちょっと確認させてください。","respondent":"飛田障害者施策推進担当課長","answer":"今、委員がおっしゃったとおり、障害福祉計画、障害児福祉計画ですか、次回、また３年ごとこれから続きます。ですので、そのときは前もって障害者・児、両方アンケートを実施していきたいと考えております。","voiceIndex":101,"id":"exchange-042"},{"speaker":"若林委員","kind":"確認","question":"さっきの答弁で、スケジュールによってはそういう説明会も行えるというニュアンスもあるのかなと、今回は非常にタイトなのでと。ただ、そうすると一方でスケジュールに少し余裕を持たせれば、そういう場も設けることはやぶさかではないという理解でいいのかどうか、ちょっと確認をしたいと思います。","respondent":"中山障害者福祉課長","answer":"当事者の方のご意見を聞きながら計画を立てていくということはすごく重要なことですし、その中で区民の方の意見をお聞きするというのも大切なことだとは思ってはおりますが、説明会までは考えていないところです。","voiceIndex":103,"id":"exchange-043"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"その第１期から第３期のところではニーズ調査をしなかった期というのはあるのですか。第１期、第２期、第３期と来て、第４期で調査をしました。第５期は調査しませんでしたということなので、第１期、第２期、第３期のところではニーズ調査は毎回やられてきたのか、伺いたいと思います。","respondent":"中山障害者福祉課長","answer":"それで、第１期、第２期、第３期にニーズ調査をしたかですが、これについてはニーズ調査はしておりません。第４期の福祉計画を立てるときに初めて区としてニーズ把握をするために調査をやったというような状況です。","voiceIndex":105,"id":"exchange-044"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"それでやはり中身をざっと見ても聞いておいたほうが、聞かないより聞くほうがというのがよりいいのではないかなという中身も多々ありますし、先ほどほかの委員からもありましたけれども、この４年間というのはやはり大きな変動がある、情勢変化がある中での状況なので、ニーズ調査、次回はやるということだったのですけれども、これからは全てというか第５期、第６期、第７期、第８期。","respondent":"中山障害者福祉課長","answer":"今後につきましては、障害児・者もニーズ調査というのはこの節目ごとにやっていきたいと考えております。","voiceIndex":107,"id":"exchange-045"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"それと、先ほど団体に所属していない障害者や家族の意見を広く聞く場はないのか、つくるべきではないかという質問もあったと思うのですけれども、今回は難しいということだったのですが、では次回はそういう団体に属していない方々にも広く聞く場を持つということなのか伺いたいのと、あとやはり区民への説明会も、私もいろいろ要望の聞き取りなんかを障害者団体の皆さんからさせていただいて。","respondent":"中山障害者福祉課長","answer":"今回については、全体スケジュールの中でできるだけ多くの声を聞くためにどういう聞き方、どういう手段があるかもう一回検討し直しかなと思っています。","voiceIndex":109,"id":"exchange-046"},{"speaker":"鈴木（真）委員","kind":"確認","question":"自民党・子ども未来としては、請願者の方から先にお話を伺いまして各種資料もいただきました。先ほどの発言の中でも言った、私どもの会派でもいろいろ研究してどのような課題があるかということを確認をとった上で、この委員会で今そのほとんどが網羅されて質疑されたと私は感じております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-047"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私はぜひ当事者の方の意見をお聞きしたいと思います。この場に参加されるに当たってぜひ訴えたいという思いで意見陳述の準備をしてきてくださっているわけですよ。だから、本当に私たちはそこのところをしっかりと議員として受けとめることが必要だと思うのです。そういう点では、私たち自身がより理解を深めるという意味からも、ぜひとも意見陳述を受けていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-048"},{"speaker":"大倉委員","kind":"意見","question":"私たちもご説明を受けて資料もいただきまして、会派の中でもさまざま議論させていただきました。そうした中で、この委員会でもいろいろなご意見が網羅的に発言をされておりますので、このまま意見陳述をしないで進めていっていただいて構わないのかなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":115,"id":"exchange-049"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今日結論を出すということでお願いをいたします。自民党・子ども未来の態度としては、今、この委員会での質疑が相当されました。その上で、一部説明会という問題がちょっとあったのですが、そこら辺のところで趣旨採択、私どもとしても当事者意識というものはものすごく理解をしておりますので、全体としては理解した上で趣旨採択ということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":118,"id":"exchange-050"},{"speaker":"若林委員","kind":"質問・要望","question":"公明党といたしましては、項目は２つございまして、このニーズ把握調査については一定の区の前向きな実施に向けた答弁ということで、次回以降のお話がありましたので、これはそのとおりということで結構だと。ただ、いわゆるスケジュール感としては予算立てのご指摘がこの文面の中にもあります。これは強く要請をしておきたいと思います。２番の区民説明会ということで今質問もさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、共産党としては採択を主張したいと思います。ニーズ調査も当然すべきというところで、次回以降には区としてもやるという方向になってこれはよかったと思いますけれども、ぜひこれを生かして今後につなげていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":120,"id":"exchange-052"},{"speaker":"大倉委員","kind":"質問・要望","question":"１番の項目については、まさに多様化するニーズの中で多くの障害をお持ちの皆様の声がしっかりと反映されるようにしていっていただきたい、スケジュール面では難しかったというお話もありましたが、今もさまざまな団体からのヒアリング等も行うし、要望があればしていくということで、この辺のネットワークもしっかりとつくりながらニーズ把握をぜひやっていただきたいと思うところであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-053"}]},{"id":"topic-03","title":"平成２９年陳情第１０号 品川区障害児福祉計画策定において、厚生労働省の定める「障害児等のニーズも勘案した見込み量設定」の徹底を求める陳情","agenda":"平成２９年陳情第１０号 品川区障害児福祉計画策定において、厚生労働省の定める「障害児等のニーズも勘案した見込み量設定」の徹底を求める陳情","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"意見","question":"先ほども審議の後にということで、結局は意見陳述を受けないままに採決ということになりました。やはり意見陳述をしたいという方の区民の願いは私たちしっかりと議員として受けとめることが必要だと思うのです。ぜひ、先に受けていきたいということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":130,"id":"exchange-054"},{"speaker":"若林委員","kind":"提案","question":"委員長のご提案のとおり、先ほどと同じ形式で進めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":132,"id":"exchange-055"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"これをつくるに当たっての基本指針というのが出ていると思うのですけれども、その中では障害児のニーズに的確に応える観点からということで、障害児支援のニーズを把握して、必要量の見込みについて計画に記載していくということで書かれているわけなのですが、ここのところではアンケートがいつごろまとまって、どこの部門でそのアンケートのニーズ、実態・意向調査。","respondent":"飛田障害者施策推進担当課長","answer":"今回のアンケートですが、現在集計中でございまして、今のところアンケートのデータを１０月中旬までにいただくとなっております。現在、障害者福祉課の福祉改革担当で取りまとめているところです。","voiceIndex":138,"id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"福祉改革担当というのは、障害者福祉課の中にあるものですか。自立支援協議会の資料の中にあった１つの部門のところで、専門部会、そこのところで入れるということなのですか。このニーズ調査をどういう形で誰がどう判断をして計画の中に入れていくのかということを教えてください。","respondent":"飛田障害者施策推進担当課長","answer":"福祉改革担当は、障害者福祉課にあるものです。今後、まとめたものをもって、障害者福祉課の中でまず詰めて、また、先ほども言いましたけれども、各団体と各相談センターや相談員、そういうところのご意見を反映しながらまた考えていくというふうになります。","voiceIndex":140,"id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"ということは、障害者福祉課の職員がこのアンケートをもとにして計画に反映をさせていくという仕組みで、それをもとに骨子案として自立支援協議会に提案をするという仕組みだということなのでしょうか。","respondent":"中山障害者福祉課長","answer":"そういうところでもご意見をいただきながら取りまとめを福祉改革担当がやるという説明になります。","voiceIndex":142,"id":"exchange-058"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"せっかくこれだけのアンケートをやるわけですから、それは本当にきちんとした形での議論を踏まえて計画に反映させていくという形をぜひとっていただきたいと思うのですけれども、そこら辺のところがどう担保されるのかということをお聞かせをいただきたいと思います。","respondent":"中山障害者福祉課長","answer":"ただ、そのときから、基準としては１０日というのは持っておりましたし、実際に１０日を超えて必要のあるお子さんについては放課後等デイサービスの受給者証を発行しておりました。","voiceIndex":144,"id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それで、今お聞きしたのは、今までは上限１０日だったのが上限が外れて基本１０日ということになりました。今度アンケート調査をやります。そうすると、今度新しい計画の中では、そのニーズを踏まえて、１人当たり平均５日というのではなくて、もっと多い形で、それを勘案した形で組まれていくのかという考え方を教えてください。","respondent":"中山障害者福祉課長","answer":"今現在、区内に放課後等デイサービスの事業所は１２あります。おおむね多分１所の定員は１０人で組んでいると思うので、１２０人だと考えています。ただ、区内に限らず実際には近隣の目黒、港、大田、そうしたところの放課後等デイサービスを利用されている方もいらっしゃいます。","voiceIndex":146,"id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"厚生労働省のほうとしても、そのニーズを踏まえて、そのニーズを勘案した形で今度の計画の見込みは立てなさいよと求めていると思うのです。その考え方についても、後でお聞かせいただきたいと思います。そういう形で今度の計画の中にも見込み量を決定していくということが必要なのではないかと思うのですけれども、いかがでしょうか。","respondent":"中山障害者福祉課長","answer":"なので、２３日がありきということではなく、やはりそういったことを全体的に見る必要があるのかなというふうには思っています。放課後等デイサービスの役割と、あと学校教育との役割、こことの連携ですとか、今できているかというとなかなか難しいところではあります。","voiceIndex":148,"id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"基本１０日という根拠がわからないのです。このガイドラインの中にも、それから支給決定の留意事項の中にもそういう１０日とかいう考え方は全くどこを探しても出てこないので、多分品川区独自のものではないかと思うのですけれども、この１０日の根拠を教えていただきたいというのが一つです。","respondent":"中山障害者福祉課長","answer":"ただ、そこになると恐らく療育が必要という観点より、やはりご家庭の状況から、ご家庭にいるよりも外のサービスを使われたほうがいい、そういうような状況のときにはやはり必要に応じてサービスを出しているケースがあると考えているところです。","voiceIndex":150,"id":"exchange-062"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"その学校以外のところで週２日という、その２日の根拠がわからないということでお聞きしていますので、その週２日の根拠を教えていただきたいと思うのです。そういうところでは、この１０日に制限するというのがどう考えても根拠が見当たらない。もともと大田なんかはこういう要綱そのものがないということで言われていましたので、改めて２日の根拠も教えていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"放課後等デイサービスが放課後児童健全クラブのバックアップ支援体制もやるというような形で留意事項の中では書かれておりますが、実際には放課後等デイサービスはお子さんにそこに来ていただいて、そのお子さんに対する療育をその場で行っているというところですので。","voiceIndex":152,"id":"exchange-063"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２日の根拠というのはなかなか示せないということですし、放課後等デイサービスの基本的役割の第１が「子どもの最善の利益の保障」ということで、就学している障害児に授業の終了後、または休日に生活能力の向上のために必要な訓練、社会との交流促進その他の便宜を共有することとされているということで、最善の利益の保障、そして健全な育成。","respondent":"中山障害者福祉課長","answer":"質の向上というところでは、福祉カレッジというのをやっておりまして、昨年度も児童の放課後等デイサービス、あるいは児童発達支援の事業者向けの研修なども行ったところです。","voiceIndex":154,"id":"exchange-064"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこの中で結構すごい、これからどんどんこれを発展させていかなければならないというようなことが書かれていて、「保育所等訪問支援は、インクルージョンを推進する『１丁目１番地』の重要な事業であり、全国的に普及させていく必要がある」と、こういうことで書かれているのですけれども、第４期では希望者が１７.２％いたのにもかかわらず利用者はゼロというふうなことになっていましたが。","respondent":"中山障害者福祉課長","answer":"児童学園の中ではそれはすごく大事なサービスと当然考えておりましたので、提供するということで職員の体制も組んだところではあります。実際にはまず区内の保育園、幼稚園に説明会を行い、その上でモデル的なケースから１ケース始めました。","voiceIndex":156,"id":"exchange-065"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"現在でも児童学園の中で体制としてはとられているということなのですね。その体制というのは、どういう資格の方が何人ぐらいという体制になっているのかちょっと教えていただきたいのと、それからこのサービスというのは、保護者からの依頼に基づくという事業です。","respondent":"中山障害者福祉課長","answer":"現在、要綱のほうは変更の準備を進めているところですので、今委員がご指摘したような年齢というよりは提供場所というような形での変更を予定しています。","voiceIndex":158,"id":"exchange-066"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"パンフレットを見て、これが自分の子どもに合っているかどうかというふうなところでこのサービスを使おうというのはなかなか難しいのかなと思うのです。こういうふうなのがありますよと勧めることで保護者がこのサービスを申請するというふうにはならないのかなという思いがするのですけれども、その点いかがでしょう。","respondent":"中山障害者福祉課長","answer":"品川の保育園では、既に巡回相談みたいなものも工夫してやっていますので、発達に特性のあるお子さん、そうしたお子さんに対する受け手側の支援というのもあわせて、障害福祉政策だけではなくやっているところです。","voiceIndex":160,"id":"exchange-067"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この基本指針の中でも全てそういう一つ一つのサービスのところにそのニーズを勘案した見込み量を立てるようにということが書かれておりますので、最後の確認なのですけれども、アンケートの中から出されたニーズを勘案した形での、それだけではないですが、それを勘案した形で見込み量は設定をされていくということで確認をさせていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"冒頭説明させていただいたようなほかのことも含めて、今回アンケートをとらせていただいたニーズも含めて数値に載せていきたいと考えております。それですみません、１点だけ答弁の修正をさせてください。","voiceIndex":163,"id":"exchange-068"},{"speaker":"鈴木（真）委員","kind":"確認","question":"今、いろいろお聞きした中で、今十分サービス量は対応しているということでよろしいのですか。そこが１点と、それからアンケートの状況と現在判断するサービス量、それをどう捉えていくのか。当然アンケートの数字というのは希望は多くなる。そこと実態の数字というのはどう捉えているのかというのを確認させてください。","respondent":"中山障害者福祉課長","answer":"次の計画に向けての最後の量の算定というところでは、やはり現在既にサービスを受けていらっしゃる方、これからサービスを受けるであろう方、今までは受けてないけれどもこれから増えるであろう人数、今現在の平均の数、それから他制度での利用者の数。","voiceIndex":165,"id":"exchange-069"},{"speaker":"鈴木（真）委員","kind":"確認","question":"今アンケートをとっている最中、集計は終わっていないでしょうけれども、仮で、今現状の段階でアンケート量と実態の数字にどの程度の乖離があるのか、その辺を確認させてもらいたい。","respondent":"中山障害者福祉課長","answer":"アンケートについては、まだ集計が出ておりませんのでちょっと今この場ではご説明できないような状況です。","voiceIndex":167,"id":"exchange-070"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"冒頭にも申し上げましたけれども、やはり区民の方の声を聞くというのは議会として本当に基本中の基本だと思うのです。せっかく意見陳述ということで文章もつくって用意をしてきてくれているわけです。それで、私たち議会改革ということでも区民参加をきちんと保証するということで話し合いを進めてきていると思うのです。ぜひ私は意見陳述を聞いていきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":172,"id":"exchange-071"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今日結論を出すということで、お願いをいたします。会派の中でもいろいろ検討を先にさせていただきました。その中で、最後にちょっとお聞きしたところで、アンケート調査と実態の乖離、そこに十分対応されているというところから判断して、今回は不採択ということで判断をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":176,"id":"exchange-072"},{"speaker":"若林委員","kind":"意見","question":"そういう中で、アンケートではたくさんのご希望があったけれども、実態の利用者数としてはということとか、この３年間で右肩上がりに当初の調査よりも、どんどん実態の量が増えてきたという大変難しいところなので、いずれにしてもニーズをいろいろなプロセスの中で的確に計画に反映をさせるという区の姿勢は十分に認めた上で、先ほどの午前中の請願審査にもありましたけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":177,"id":"exchange-073"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は採択を主張したいと思います。この厚労省から出されている基本指針の中にもさまざま勘案事項というのはあるのですけれども、その勘案事項の中には障害児等のニーズというのが必ず入っているのです。それと実態とが乖離があるということであれば、それはそれとしてそのニーズに応えられるという方向をどうつくっていくかというふうなところが、やはり施策としても求められていると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":178,"id":"exchange-074"},{"speaker":"大倉委員","kind":"意見","question":"本日結論を出すということでお願いします。でも、一方でニーズがあるがしかし実態に即していないというところ、さまざまなデータを複合的に判断をしながらサービスの提供を今品川区で行っているというところで、この趣旨はよくわかるのですが、なかなか実態との乖離がある中、非常に難しい中で行っているのかなということが十分わかりましたので、この件に関しては不採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":179,"id":"exchange-075"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3486#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":49801,"voices":185}},{"id":"h29-20170925-8","meetingId":"h29-cm09","date":"2017年9月25日","dateIso":"2017-09-25","committee":"建設委員会","time":"午前１０時００分～午後 ２時５５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を90件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第６０号議案 品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","agenda":"第６０号議案 品川区自転車等の放置防止および自転車等駐車場の整備に関する条例の一部を改正する条例","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"先ほど、説明の中で平置きということでお話がありましたけれども、近年、自転車の使用車種というか、使用する自転車の形が変わってまいりまして、以前にも大森の時も議論があったかと思いますけれども、そこら辺はここの駐輪場においては、どのように意識をされ、どのような形の駐輪ラックを設置されるのか教えていただきたい。","respondent":"桑波田交通安全担当課長","answer":"新設する６３台につきましては、こういった大型車にも既に対応できるように、間隔の広い、設置幅の広いラックを設置して対応できるようにやっていくものです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"大沢委員","kind":"質問","question":"今のイメージする自転車、前のハンドルのところと、後ろの荷台のところ、昔は私たちはつけましたけれども、今は標準装備になって、それなりの頑丈なつくりになって、なおかつ、電動アシスト付自転車ということで非常にかさが大きくなっているのですけれども、そこの部分で、この測量の後に設計はしたと思われるのですけれども、今後、仮にここの部分で、通行上。","respondent":"桑波田交通安全担当課長","answer":"今回、２カ所の歩道上に設置をしますけれども、まず、駅前ロータリーにつきましては幅４ｍということで場所を確保しております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"大沢委員","kind":"質問・要望","question":"昔の自転車と違って、何かあった場合のけがの度合いが以前よりは多分ひどくなるのではないかということが予想されますので、そこらあたりに十分配慮しながら計画を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"慢性的に不足していると書いてありますけれども、６３台の設置で足りるのか、利用者の実態、現在、足りていなくてとめられないという方は、どういう方なのか、把握していらっしゃるのか伺います。もう１つは、大森駅前住宅の歩道の駐輪場設置でもめた経緯があると思うのですけれども、その教訓はどのように生かしていくのか、また整備計画に反映させたのか伺いたいと思います。","respondent":"桑波田交通安全担当課長","answer":"施設が古くて入らない、大きいものに対応できないものも多数ありますので、そういった方、改修工事と増設をする６３台を合わせまして、キャンセル待ちの方は使用できるようになると考えております。","voiceIndex":10,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"わかりました。当日利用だけというのは、ちょっと見直したほうがいいのではないかという気もするのですが、そこら辺についてはいかがでしょうか。","respondent":"桑波田交通安全担当課長","answer":"今回、当日利用ということで外のほうに増設するのですけれども、あわせて既設の駐輪場も当日利用がありまして、そういったところを既設の駐輪場の中の当日利用も一部定期のほうに変えてやるということで。","voiceIndex":12,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"わかりました。そこら辺の工夫をしていただきたいと思います。大事なことだと思います。短時間、買い物とか、メイプルセンターの講座に行くとか、２時間枠とか、無料枠とかを設けるべきだと思うのですけれども、そこら辺は設ける考えはおありでしょうか。設けていただきたいと思うのですけれども、設けないというのであれば、なぜなのか、その理由も伺います。","respondent":"桑波田交通安全担当課長","answer":"民間もそういったものがあるのですけれども、こちらは無造作に短時間としますと、本当に真に使いたい、通勤・通学で時間で使いたいという方があぶれてしまって使えなくなるという状況もありますので、無料ということは現在考えているところではございません。","voiceIndex":14,"id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"６３台増えるということで、少しここら辺が緩和されるのかなと思います。そこの１点確認。歩道に駅前も公園の横も設置をされますが、自転車をとめるとき、歩行者との事故が防げるような、とめるときには自転車は歩いてとめましょうとか、何か少し歩行者と自転車をとめる方との事故がないような看板ですとか注意を促すようなことを少ししていただきたいと思いますが、いかがでしょうか。","respondent":"桑波田交通安全担当課長","answer":"既設の駐輪場の中にも当日と定期がありまして、こういったものを改修することによって、キャンセル待ちは解消されると読んでおります。それと、注意喚起ですけれども、こちらについては、看板等を設置しながら注意喚起は図っていきたいと考えております。","voiceIndex":16,"id":"exchange-007"},{"speaker":"横山委員","kind":"質問・要望","question":"この地域はファミリー層もわりと多い地域で、大型のチャイルドシート付電動アシスト式自転車などの自転車に対応したラックを使ったりですとか、スペースを用いていくというご説明を今いただいたのですけれども、今後、ほかの地域ですとかいろいろ地域性やご利用の方のニーズにもよってくるかとは思うのですけれども、区としての大きな方向性といいますか、新しく開設したり、改修していく際に。","respondent":"桑波田交通安全担当課長","answer":"鉄道事業者とも、いろいろ各種キャンペーンや広報活動を通じながら連携を図っておりますので、撤去活動とあわせて、その辺は連携を図っていきたいと考えております。","voiceIndex":18,"id":"exchange-008"},{"speaker":"横山委員","kind":"質問・要望","question":"引き続き、鉄道事業者とは、放置自転車が多少解消された後も、キャンペーンですとか告知等で、引き続き、連携をお願いしたいと思います。これからまたニーズもさまざま変わってくるかと思うのですけれども、その地域のご利用のデータをしっかりとっていただきまして、適正な当日利用、定期利用、その辺のフレキシブルに対応していただきますように、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"お聞きしたいのは、この増設、６３台とありますが、通勤の方々を対象としたものとして考えているのでしょうか。そこをお聞きしたいと思います。","respondent":"桑波田交通安全担当課長","answer":"こちらは当日ということでやらせていただきますけれども、通勤・通学の方もご利用いただけますし、短時間、定期に入らない、本当に毎日ではなくても週に何回かぐらいしかお使いいただかないという方もいらっしゃいますので。","voiceIndex":21,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"ここは通勤者・通学者が非常に多いのですけれども、そのほかに平日の利用としては、困っていることに、西大井駅の周辺は商店が多いのです。結局そこの対策がされていないから流れてきてしまうということがあるわけではないですか。それから、全体の状況の責任をどういうふうに考えて、放置自転車への対策を考えているのかということをお聞きします。","respondent":"桑波田交通安全担当課長","answer":"こちらもそういったところがありますので、放置禁止区域に入っていますので、こちらも撤去活動をするとともに、また、既設の駐輪場の改修等もやっていきますので、そういった中で当日利用で使える方も台数を増やすことによってでてきますので、その辺で解消したいということと。","voiceIndex":23,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問","question":"当然、認識を高めてもらいたいという思いがあります。そうなったときに、なぜあそこを締め出すのですかという話です。自分たちの店に来ているお客さんに対して、自転車対策をなぜとらないのでしょうか。そうしたら、あそこのコア・スターレの前のところも広場があるわけですから、そこもある程度の利用者に対する対策を考えていただいてはいかがですか。そこはどういう話をされていますか。","respondent":"桑波田交通安全担当課長","answer":"そういったところで、今回、２カ所を設置しますので、地元とは引き続きそういった対策について、いろいろ話し合いをしながら考えていきたいと考えております。","voiceIndex":25,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問・要望","question":"この件はちょっとしつこく質問します。あそこは３階でしたか、屋上まで入れると３階、あれはもっと高くする、あそこはＪＲの新幹線があるので無理だとは思うのですけれども、それ自体をもうちょっと大きくするとかということは可能なのでしょうか。６３台でオーケーとなるのか、もっと将来的には、あと２００台、３００台という対応をしていかなければならない現状なのか、そこを教えてください。","respondent":"桑波田交通安全担当課長","answer":"今後、人口等も増加するというような、新しいマンションの建設等があれば増えてまいりますので、その辺も総合的に、来年度以降、いろいろな区内の駐輪場の需要等も考慮しながら検討していきたいと考えております。","voiceIndex":27,"id":"exchange-013"},{"speaker":"いながわ副委員長","kind":"質問","question":"何点かお伺いしたいのですけれども、駐輪場、とめるはとめるのですけれども、多くは利用しないのですけれども、これ、料金の徴収方法といいますか、スクエア荏原みたいに、ガチャンとやって、有人ではなくて無人のそういった感じのものがここにできるというイメージでいいのかどうなのかということが１点。","respondent":"桑波田交通安全担当課長","answer":"今回つくるものは、当日利用ということで、前輪を入れて電磁ロックでロックがかかる。それで自転車がロックされる状況になりますので、精算するときに精算機にお金を入れていただいて解除されて引き抜くというようなものを入れる予定です。","voiceIndex":29,"id":"exchange-014"},{"speaker":"いながわ副委員長","kind":"質問","question":"今、そういう無人のものだと、その無人の精算機というのは、基本的にどこに設置するのか。場所的には、西大井公園の入口の公園歩道と駅前があるのだけれども、駅前はそんな多くの台数、２０台か、どんなふうにしていくのか、どこに機械を置くのかということが１点。ご答弁を。","respondent":"桑波田交通安全担当課長","answer":"駐輪ラックの関係なのですけれども、あわせてどうしても使い勝手の悪いものもありますし、前輪が深く入るものもありますけれども、そういったものも含めまして、今後また新しく増設ですとか改修をする際に、そういったものに対応できるように改修していきたいと考えております。","voiceIndex":31,"id":"exchange-015"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"公園前の歩道で２カ所端のほうに精算機をつくるというのですけれども、その辺は、おそらく駅を利用する方々なので、精算機を設置する場所は、利便性に富んだ、端は端でいいのですけれども、これは１００ｍぐらいあるのですか。僕はわからないですが、そんなにないですか。うまく設置をしていただきたいと思います。区民の皆様の利便性をしっかり考えていただきたいと思いますので、よろしくお願いします。","respondent":"桑波田交通安全担当課長","answer":"公園前歩道につきましては、２つ合わせますと全長で６６ｍほどございまして、その手前側のほうの１個と、奥のほうは、この中間点あたりにつけるように計画しております。","voiceIndex":33,"id":"exchange-016"},{"speaker":"西本委員","kind":"確認","question":"この地図の中で確認だけです。西大井保育園はここですか。これ、西大井保育園と書いてある。これは場所が違いませんか。","respondent":"桑波田交通安全担当課長","answer":"地図が間違っておりまして、申し訳ありません。地図でいきますと、現在は、「森前」と書いてありますこちらのほうに移転しています。","voiceIndex":36,"id":"exchange-017"},{"speaker":"西本委員","kind":"質問","question":"賛成です。先ほど、質問で述べさせていただきました。地域ぐるみでという意味での放置自転車対策を心がけて、ぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-018"}]},{"id":"topic-02","title":"第６１号議案 品川区道路標識の寸法に関する条例の一部を改正する条例","agenda":"第６１号議案 品川区道路標識の寸法に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今後も新たな標識が増えたり、道路が新設されたら、こういった条例改正が必要になるということなのか伺います。これからも頻繁にありそうなことなのかどうか伺います。","respondent":"多並道路課長","answer":"ただ、全体の標識の中で寸法が示されているものは本当に限られたものでありまして、全部で７０ほど標識がありまして、その中で寸法に関するものということですので、影響としては大きくはないかと思っているところです。","voiceIndex":50,"id":"exchange-019"},{"speaker":"西本委員","kind":"質問","question":"変更があった場合に、標識はつくり直すのですか。つくり直す場合に、どこの予算で、誰がつくり直すのですかということ。それから、基本的なことですみません、地域主権一括法ということなのですが、この目的はどういうものをもっての目的があって、品川区にとってどういうメリット、デメリットがあるのか教えてください。","respondent":"多並道路課長","answer":"ご説明がちょっとわかりづらくてすみません。標識自体は標識令で国が全体の中で決めておりまして、道路管理者と交通管理者、警察が設置する標識があります。","voiceIndex":52,"id":"exchange-020"},{"speaker":"いながわ副委員長","kind":"質問","question":"あまりピンとこないのですけれども、要するに、区民生活にどうこうというものではなく、要は、変わったから、標識が増えたから、その上で標識の番号といいますか、標識番号を新たに付与するというか、ずらしただけという認識で、先ほどちらっと話が出たのですけれども、ここにサイズが書いてあるではないですか。既存のものでもいい。それを教えてください。","respondent":"多並道路課長","answer":"今おっしゃった形でやるとしますと、条例改正ということで、寸法を変える形で……。","voiceIndex":56,"id":"exchange-021"}]},{"id":"topic-03","title":"第５９号議案 平成２９年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第５９号議案 平成２９年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"細街路拡幅整備事業ということなので、戸建て住宅の建替えがほとんどかと思うのですけれども、今回の追加にあらわれる今の実態として、狭隘な道路に面した戸建て住宅の建替えが進んだ結果ということでよろしいのでしょうか。伺いたいと思います。","respondent":"鈴木建築課長","answer":"ご質問の狭隘な道路に関する拡幅が進んだかですが、道路自体が狭隘道路、二項道路でございまして、今回、事業的には品川区全域が対象となっておりますが、傾向を見ますと、そのうち整備地域、いわゆる木密地域と言われているところの件数が、今現在のところですけれども。","voiceIndex":72,"id":"exchange-022"},{"speaker":"筒井委員","kind":"意見","question":"当初の見込みと比べて６,７００万円増えたということなのですけれども、一見すると、かなり大きな差額に思えるのですけれども、なぜこのような差額というか、予想より差が出たのかということを具体的にお知らせください。","respondent":"鈴木建築課長","answer":"今年度もそうした過去の実績を受けて、予算立てをして、今、事業を進めているところですが、これまでの第一四半期、あるいは、今、実際に設計を行っている内容を見ますと、やはり１件当たりの整備延長と、あるいは整備の後退面積が大きい現場が多いということと、それからあと。","voiceIndex":75,"id":"exchange-023"},{"speaker":"筒井委員","kind":"意見","question":"そういったことが過去３年間のデータを見ると、予想はできなかったということでよろしいのかということと、やはり今後の工事にあたり、１件８０万円ではなく１件１００万円ぐらいだという見積もりで今後事業を行っていくのか、この２点をお知らせください。","respondent":"鈴木建築課長","answer":"Ｌ型の移設が多い年度、あるいは１件当たりの整備の規模、これはなかなかその年その年で予想できないところがありますけれども、予算化にあたっては、過去の３年間あるいは４年間の平均をとってやっているのですけれども、今年に限っては。","voiceIndex":77,"id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"補助２８号線、補助２９号線も含めると、年間を見通しても大体これぐらいになるのではないかという予測は立てられるのではないかと思うのですが、その上でのこの補正予算の成り立ちになっているのでしょうか。その上で今回の金額で今のところはやれるのかというところの見通しはいかがなのでしょうか。","respondent":"鈴木建築課長","answer":"残り１、２、３月分について、これまでの件数等の推移を見て要求させていただいているもので、この予算で、今年度しっかりやっていきたいというものです。","voiceIndex":79,"id":"exchange-025"},{"speaker":"西本委員","kind":"質問","question":"わかりました。今年度という意味では、それを見通しながらの金額の補正ですということでわかりました。ただ、長期にわたって考えたときに、この事業に対する将来的な見込みが出てくると思うのです。ここはいずれ整備しますと決まっているものがあるではないですか。それも１年ではなくて数年にわたっての計画が出てくるのではないかと思うのですが、そういう見方はいかがなのでしょうか。","respondent":"鈴木建築課長","answer":"木密地域内で正確に１軒１軒の建替えの意向を把握していくというやり方はなかなか難しいのかというところはありますが、事業的には昭和６３年度から行っていて、それからあと、年間の協議件数、建替え件数は、おおむね２３０から３００前後というところは。","voiceIndex":81,"id":"exchange-026"},{"speaker":"西本委員","kind":"確認","question":"それと最後に確認は、お金の流れを、歳入のところは所管ではないということなのですが、この必要ですというお金が補正がかけられました。今回、国と都からの歳入が入っているのですけれども、それはこういうふうにお金がかかります、それで、では、歳入という形での都の補助金、国の補助金ということで申請をするということと、決まってくると入ってくるという、そういう流れでよろしいのでしょうか。","respondent":"鈴木建築課長","answer":"委員ご指摘のとおり、歳出分、増えた分について、都と国から歳入分が入ってくるというものです。","voiceIndex":83,"id":"exchange-027"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"賛成します。こういった補正は、いろいろ補正のあり方はあるのかもしれないですけれども、やはり区民の方々が間に入っているわけですから、区民を待たせることなく、こうやって即座に補正を組むということはすばらしいと僕は思っていますので、今後もその場に応じてしっかりやっていただきたいと思いますので、よろしくお願いいたします。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-028"}]},{"id":"topic-04","title":"(5)大崎駅西口Ｆ南地区（大崎三丁目地区）再開発計画に関する都市計画案","agenda":"(5)大崎駅西口Ｆ南地区（大崎三丁目地区）再開発計画に関する都市計画案","exchanges":[{"speaker":"新妻委員","kind":"質問","question":"ご説明ありがとうございました。Ａ３の書類のほうの２番の説明会のことで、もう少しお話ししたいと思います。出席者は７７名で、地区内の関係権利者とありまして、ここには区民というふうには入っていないのですけれども、どのような方にどういう形でこの説明会を案内をされての７７名だったのかということをお伺いしたいと思います。","respondent":"稲田都市開発課長","answer":"こちらですが、地区内の権利者ということでございまして、土地所有者、それから借地人の方々に対しまして、ご案内の通知を差し上げまして説明会を開催したです。","voiceIndex":98,"id":"exchange-029"},{"speaker":"新妻委員","kind":"質問","question":"ここの地区内の全員の方にご案内をしてということでよろしいのでしょうか。それはポスティングか何か、また、書面か何かでご案内をされたということでしょうか。","respondent":"稲田都市開発課長","answer":"この地区内の権利者の方、それから借地人の方に郵送でお知らせをしております。","voiceIndex":100,"id":"exchange-030"},{"speaker":"新妻委員","kind":"質問","question":"ご案内はされていなかったけれども、周辺の方も参加されたということでよろしいのですか。","respondent":"稲田都市開発課長","answer":"そのとおりです。","voiceIndex":106,"id":"exchange-031"},{"speaker":"大沢委員","kind":"意見","question":"なぜこういうふうな話が出てきたのか、どのように分析をされているのか、聞かせていただける部分があればいいですし、なければ答えなくて結構です。","respondent":"稲田都市開発課長","answer":"特に分析をしたというわけではございませんで、私の考えですが、説明等はこのようにやってきているところですけれども、さらに、風とか、建物の高さとか、日照とか、ご意見をお聞きしますと、そういうことへの不安等があるですので。","voiceIndex":109,"id":"exchange-032"},{"speaker":"大沢委員","kind":"確認","question":"それは別に、さっき、「個々に」か、「個別」という単語が出ていて、この別にも「個々に」あるいは「個別に」ということは説明をされてきたのでしょうか。もう１回、確認をお願いします。","respondent":"稲田都市開発課長","answer":"事業者におきましても、個別に説明をしたり、また、区におきましても、原案説明会を開催前後ですが、いろいろとご心配等が来ておりまして、区や都におきましても説明はしています。","voiceIndex":111,"id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"それと、８月７日と８日に行われた説明会は、都市計画法第１６条第２項に基づいたということでしたが、これは第１６条第１項ではない理由をお伺いしたいのと、それと、今度、１０月１０日に行われる予定の説明会は、都市計画法何条に基づくものなのか教えてください。","respondent":"稲田都市開発課長","answer":"都市計画原案の説明を行いましたときに、意見書等で出てきたものの数字ですけれども、全部で３４通の意見が出ております。その中で地区内は１２通、それから地区外が２２通です。","voiceIndex":113,"id":"exchange-034"},{"speaker":"安藤委員","kind":"質問・要望","question":"それは非常に大事で当たり前なことだと思うのですけれども、これを見ると、なぜ今回、原案の説明会のところでは、対象者をわざわざ第１６条第２項として、地区内の関係権利者に限定したのかということがちょっとわからなかったので、先ほども伺ったのですけれども、なぜ第１６条第１項でやらなかったのかということをお伺いします。","respondent":"稲田都市開発課長","answer":"第１６条第２項のときの説明会におきましては、先ほども申しましたけれども、高さの関係、それから風の関係等々が出ているです。","voiceIndex":115,"id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"でも、事業者の説明会は行われましたけれども、法律の手続になると、都市計画原案、つまり、案をつくる前の段階で区が対象にしている方々は、地区内の関係権利者だけになっているというのは、私はこれは不十分ではないかと思うのですけれども、先ほども何回もお伺いしているのですけれども、今の説明では、なぜ都市計画原案の説明会、７日、８日のときに。","respondent":"中村都市計画課長、稲田都市開発課長","answer":"周辺の方々への説明も、これもきちんとなされていればいいわけですけれども、ただ、この説明が一度もなされないまま進められるということは、区としては認められませんので。そういうところで、この地区を共同化しながら広場を設けたり、道路を拡幅したりというところを行っていくということです。","voiceIndex":117,"id":"exchange-036"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺ったのが、そちらの開発の理由はるる述べられましたけれども、その理由自体が私はちょっとどうなのかと、もっと有効な手立てがあるのではないかとは思う点があります。どんな影響を受けると区は考えているのですか。さらに１１月には都市計画審議会と書いていますが、ここについては２点お伺いします。区民、利害関係者の方も入れるべきではないですかということを伺ったので、お答えください。","respondent":"稲田都市開発課長","answer":"区でやる説明会が、今回、１０月が初めてではないかですけれども、先ほどもご説明してきましたが、事業者による近隣への説明、そして当事者、権利者等とやってきました。というところで、この開発をする上では、十分に地域の皆様には話をしてきている。","voiceIndex":120,"id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"その影響を受ける人のことは全く考えないで、メリットのほうばかりを押すということなのですか。ただ、私が伺ったのは、品川区がこれだけかなりかかわって、まちづくり、都市計画ということで進めていくにもかかわらず、近隣住民に区が責任をもって説明をするというのは１０月１０日が初めてなのではないですか。それで間違いないのですかということを伺ったので、それはお伺いしたいというのが２点目です。","respondent":"稲田都市開発課長","answer":"これが再開発事業、都市計画決定されて進めていった、完成していくというところに、その後ですが、完成した暁には、また現状の風等をはかりながら、予測との違い等で対応をしていくというふうな形でやっておりますので、このようなことを含めまして。","voiceIndex":122,"id":"exchange-038"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、私は、説明をすればいいのかというと、それが説明というか、一方通行になってしまっていて、全く住民の意見が反映されないというところに大問題があると考えていますので、ぜひこうした形で一方的に進んでいくというのは、やはり私はまちづくりのあり方としても間違っていると思いますので、改めてこの１０月１０日の前に、品川区が案の段階で周りの方も含めた説明会。","respondent":"稲田都市開発課長","answer":"１０月１０日、説明会を行いまして、また公告・縦覧をして、意見を十分に皆さんから聞いていくという体制です。このような形で今後も進めていきたいです。","voiceIndex":124,"id":"exchange-039"},{"speaker":"安藤委員","kind":"質問・要望","question":"１１月に都市計画審議会を開催すると、あくまでこれは予定と書いていますから、予定なので、こういった状況もあるので、これは一旦白紙にしていただきたいと思うのですが、いかがでしょうかというのが１点。具体的に出した意見書は、案にどのように反映されるのか、そこは伺いたいと思います。","respondent":"稲田都市開発課長","answer":"４番、今後の予定ですが、１１月に区の都計審、それから１２月に都の都計審を予定しています。これはあくまでも予定ではありますが、この予定に沿いながら進めていけたらいいというふうに考えております。","voiceIndex":127,"id":"exchange-040"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、スケジュールの件も、区としてはこれで進めていきたいという表明もありましたが、あくまで予定ですということもありましたので、ぜひこれは今後のまちづくり、長い期にわたるまちづくり、大崎のまちにかかわってくる大問題ですので、ぜひスケジュールありきで進めていただかないよう要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-041"},{"speaker":"筒井委員","kind":"質問","question":"先ほど、地区内の関係権利者、すなわち土地所有者、借地人の方が２７名いらっしゃるということなのですけれども、今回の再開発に賛成の方は何人いらっしゃるのか、それで、その賛成された方が準備組合を結成されたのかということをお伺いいたします。","respondent":"稲田都市開発課長","answer":"権利者におきまして、２７名のうち２５名が準備組合に加入しているという状況です。現在、仮の同意率というところでいきますと、２７名のうち２４人が同意をしているというような状況があります。まだ仮という状態です。","voiceIndex":130,"id":"exchange-042"},{"speaker":"筒井委員","kind":"質問・要望","question":"区としましては、その準備組合も１０年前から設立されているということもありますし、説明を個別的にもされているということなのですけれども、それで、今までそうした説明を行っているから公聴会は開く必要がないというお考えだろうかと思いますけれども、当然、周辺の区民の方から、日照や風の問題や著しく高い建物が建ちますから、かなり景観上も大きな影響が起きると思いますので。","respondent":"稲田都市開発課長","answer":"権利者への説明会もやってきた。それから、今後、第１７条に基づいて１０月１０日にも説明会をしてご意見を聞いていくというところにおきまして、基本的には、このような形で説明会としてはこれをやっていくものです。","voiceIndex":132,"id":"exchange-043"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひこの再開発が多くのこの地域の区民の方にとってプラスになるようなものとなっていただきたいので、ぜひとも周辺区民の納得が得られるようなご説明を引き続き何とぞよろしくお願い申し上げます。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":134,"id":"exchange-044"},{"speaker":"西本委員","kind":"質問","question":"特に気になるのが、この図の中にある青い点線のところです。今回は赤い線内に関しての陳情と報告になっていますが、やはり青い地域を考えての中の１つだと思っているので、そういう将来にわたるビジョンについてはどのような考え方をして進められているのでしょうか。お聞きします。","respondent":"稲田都市開発課長","answer":"Ｆ東地区におきましては、駅前というところがありますので、今回はその辺、まだ具体的には、今、準備組合で検討している段階ではありますが、駅前副都心にふさわしい駅前地区の形でまちづくりが進んでいくという方向性だけの位置づけをしたというところでございまして。","voiceIndex":135,"id":"exchange-045"},{"speaker":"西本委員","kind":"質問・要望","question":"その中の一端なのですというところのビジョンをしっかりと説明していくということが私は大切ではないかと思うのですが、そこの進め方については、どのようになっていたのでしょうかということが１つ。それから、開発がどんどん進んでおります。その上で、南地区、東地区、北地区の開発を進めていきたいと思うのですが、その辺のお考えはいかがですか。","respondent":"稲田都市開発課長","answer":"そういう中におきまして、この大崎駅の混雑というところにおきましても、鉄道事業者が対応するというところにはなるかと思いますけれども、区といたしましても、安全な対策がとれるよう、ＪＲ等々と協議をというふうに思っています。","voiceIndex":137,"id":"exchange-046"},{"speaker":"西本委員","kind":"質問・要望","question":"陳情のほうに入りますが、確認です。確認です。陳情の中に、都市計画法第１６条第１項にのっとりと、第１６条第１項の区としてやってきたことは、この説明資料の中の２番の(1)、８月７日、８日のことの認識でよろしいのでしょうか。これは大もとの根拠は第２項ですか、第１６条第２項がそうなっているので、そこの法的なところの関係性をもう一度確認させてください。","respondent":"稲田都市開発課長","answer":"権利者、当事者等についても話を聞いてきて、説明もして話を受けるということで、今回、１０月１０日に行うものは、広く区民の皆さんからご意見を伺うというところでやる予定です。","voiceIndex":139,"id":"exchange-047"},{"speaker":"西本委員","kind":"質問・要望","question":"準備組合の方々が権利者の方々に、どういう条件ですか、どういうお考えですかということを細かく聞いていると聞いております。私らはかかわって何となくそういう流れでわかっていますけれども、ほかの方はそこまで知られていないような気がするのですけれども、そこら辺をもうちょっとわかりやすいように区民の皆様方に知らせる方法を今後とっていくべきなのではないかと思いますが、いかがでしょうか。","respondent":"稲田都市開発課長","answer":"それぞれの説明会でご質問やご意見をいただいたときに、今後の説明会におきましても今後の進め方というふうには、ＰＲというか、進め方等はお知らせしているところでございまして、今後もより一層、地域の皆様には説明会の進め方等におきまして。","voiceIndex":141,"id":"exchange-048"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういった意味で、そこは１０月１０日の前にしっかり区としてもっと早くやるべきだったのではないですかということなのです。それが１点です。それと、今まで説明しましたかということ、これ、１０月１０日では遅いのではないですかということです。ですから、改めて伺いたいのは、区として、陳情の要旨にある先ほど読んだところは、これはやるつもりはないということなのですか。お伺いします。","respondent":"稲田都市開発課長","answer":"公聴会、説明会、違うのではないかですが、私どもは、説明会におきましても説明をして意見をいただき、また、ご心配やそういうものに対しても十分にこたえてきている。","voiceIndex":144,"id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川区としてはもう既にみんなの意見を聞いてつくったと、そういうふうなご見解をお持ちでしょうけれども、やはりマスタープランに載っています、それが公表されていますということで、地域の方に品川区が十分ビジョンを説明しているというふうには私はならないと思いますので、そこは今からでも遅くありませんので、もしこの品川区の大崎駅のこの１４９ｍ、３９階建て。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-050"},{"speaker":"大沢委員","kind":"質問・要望","question":"本日、結論を出していただきたいと思います。理由につきましては、先ほど来、質疑がありました。区は説明を段取りを踏みながら、平成１９年から組織をつくりながらして、そもそもの再開発というのは、地元の皆さんの自発、発意に基づいて行われるのが再開発であります。しかるに、この件に関しては、自民党・子ども未来としては願意に沿うことができないので、これに対しては不採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":149,"id":"exchange-051"},{"speaker":"新妻委員","kind":"意見","question":"本日、結論を出すでお願いいたします。これまで、今、説明をいただきましたとおり、平成１９年から準備組合が立ち上がって、また、この地元の当事者の方も２７組中２５人が加入をしており、これまでも説明会等も行っておりますので、ご説明いただいたとおりであると思います。よって、不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":150,"id":"exchange-052"},{"speaker":"安藤委員","kind":"質問","question":"結論を出すで、採択を主張したいと思いますが、やはり重要な問題を今回の陳情は投げかけているのではないかと思います。やはり、今後のまちづくりにかかわってくるわけですから、やはり周辺の方も含めて計画段階から早期に意見を伺いながらしっかりやっていくということがまちづくりの基本だと思います。採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-053"},{"speaker":"いながわ副委員長","kind":"意見","question":"本日、結論を出すということで、先ほど来、都市計画課長、都市開発課長からお話があったように、ずっと丁寧な説明をし続けてきたということでありますので、もちろんこの再開発に関しても、これまでの経緯に見られるように、しっかり都市計画法にのっとって進めてきておりますので、ただ、しかしながら、こういった陳情が出てきているというのも事実でありますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":152,"id":"exchange-054"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日、結論を出すということでお願い申し上げます。ただし、やはり同じ大崎地域に住む方々、良好な区民関係維持のためのご努力はしていただきたいということで、引き続き、区としては多くの区民の納得を得られるよう、丁寧な説明をお願いしたいと考えております。結論としましては、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":153,"id":"exchange-055"},{"speaker":"西本委員","kind":"質問・要望","question":"本日、結論を出していただきたいと思います。今回の審議の中で、この計画に権利者の２４名が同意されています。これは当然だと思います。ただ、その周辺の人たちは、そうは言っても、高層ビルが建つのはどうなのだろうか、いろいろな心配があるよねというようなところをお互いに出すことによっての理解を深めつつ、まちづくりをつくっていくのが最も好ましいことではないかというふうに非常に感じました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":154,"id":"exchange-056"}]},{"id":"topic-05","title":"平成２９年陳情第８号 北朝鮮のミサイル発射に対して万全の措置を求める陳情","agenda":"平成２９年陳情第８号 北朝鮮のミサイル発射に対して万全の措置を求める陳情","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"かなり心配されている区民の方々がたくさんいると思うのですけれども、せっかくですから、陳情に至った思いを直接伺いたいので、できれば審査の前に私は陳述を聞きたいと思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":161,"id":"exchange-057"},{"speaker":"大沢委員","kind":"質問","question":"通例どおり議事を運んでいただくことを望みます。ですから、前ではないということです。今、安藤委員の言ったことには反対をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":163,"id":"exchange-058"},{"speaker":"西本委員","kind":"意見","question":"こういう意見陳述という本来の姿なのですが、この陳情は受けているわけですので、この陳情を受けて、その議論をするということで、さらに説明が必要だというときにお願いするという形になると思うのです。なので、事前に聞くということは、この陳情、流れ、仕組みに関してちょっとおかしいのではないかと思っているので、大沢委員と同じように思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":165,"id":"exchange-059"},{"speaker":"安藤委員","kind":"質問","question":"共産党としましては、厳しく糾弾して抗議したいと思います。中身なのですけれども、今、ご説明もあったのですが、例えば、２項目目の対処法というのがあるのですけれども、対処法、ミサイルが着弾した場合の対処法とは何か、具体的に伺いたいと。それとあと、ミサイルが着弾した場合に備えた避難訓練については、いかがなのでしょうか。伺いたいと思います。","respondent":"川部防災安全担当課長","answer":"２つ目の訓練はいかにですけれども、これも先ほど防災課長が説明したとおり、まずは訓練以前に、着弾した場合もしくはＪアラートが発動した場合に何をすべきかというようなことを十分周知していくことが必要だと考えています。","voiceIndex":170,"id":"exchange-060"},{"speaker":"安藤委員","kind":"質問","question":"着弾前の措置が重要だということですけれども、どういった措置を考えているのか、もうちょっと、もう一度お伺いしたいのと、後段の高齢者の云々というところがちょっとよくわからなかったので、もう一度そこら辺をお聞かせいただけますか。訓練するということですか。","respondent":"川部防災安全担当課長","answer":"高齢者施設などにおきますと、例えば夜間などですと、少ない職員の数で多くの高齢者の方のいろいろな介助等をしなければいけないというようなことがありますけれども、そういうときにＪアラートが鳴ってしまったら、職員の方はどのようにするべきか。","voiceIndex":172,"id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"どのようなことでも軍事的緊張、米朝両国の軍事的緊張をエスカレートさせるような言動は、当たり前です、厳に慎むべきだと思いますし、そういった意味では、今の政府の対応は私は非常に問題があると、対話を否定したりとか、米艦に給油したりとか、こういう政府の対応は間違っていると思うのですけれども、同時に、国民保護法に基づく訓練というのも、やはりこうした軍事的対応ですとか。","respondent":"川部防災安全担当課長","answer":"訓練を推奨、周知を推奨することによって、そちらの軍事的な話にのめり込んでいってしまうのではないかという危惧に関しましては、のめり込んでいくかどうかというところは我々は言及はできないのですけれども、仮にそうなってしまった場合に、先ほども申し上げたとおり。","voiceIndex":174,"id":"exchange-062"},{"speaker":"安藤委員","kind":"質問・要望","question":"エスカレート、緊張をあおるということになりかねない。これはマイナスの面も大きいと思います。品川区が今一番やらなくてはならないことは、軍事衝突を避けるということに注力する、そこに全力を傾けてほしい。私としましてもは、そこに注力していただきたいと思うのですけれども、なかなか答弁は変わらないかもしれないのですが、そちらのほうに力を入れてほしいと思うのですけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":176,"id":"exchange-063"},{"speaker":"筒井委員","kind":"質問・要望","question":"２点目としましては、やはりこうした日に日に高まる緊張状態で、品川区民の方も、実際、そうしたミサイル着弾等の事態が起きたらどうしようかと、どう対処したらいいのかと悩まれている方が多いので、ぜひ徹底して国民保護ポータルサイトに載っているような情報の啓蒙周知活動をやっていただきたいと考えておりますけれども、その１つの手立てとして、区議会だよりや、区の広報掲示板や、町会掲示板等に。","respondent":"川部防災安全担当課長","answer":"３つ目の今後の積極的な訓練の推進ですけれども、当初はまずは周知というように考えてはありますが、段階的には、今度は実働的な訓練、体を動かしていただいての訓練というように、当然段階を踏んではステップアップしていかなければいけないというふうにも考えておりますので。","voiceIndex":179,"id":"exchange-064"},{"speaker":"西本委員","kind":"確認","question":"確認だけです。この陳情の文章の中の下から５行目、「北朝鮮のミサイルが失敗しており」とあるのですけれども、今までのものに対しては、これは品川区というより国の評価ということかもしれませんが、失敗という認識なのでしょうか。それとも、これはどういうふうに今までのミサイルの状況を認識しているのか。わかりましたらお答え願います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":181,"id":"exchange-065"},{"speaker":"大沢委員","kind":"質問","question":"状況だけお聞かせ願いたいのですけれども、避難訓練を実施したのは秋田県ということで認識をしておりますけれども、それ以外に避難訓練をやったという情報なりは行政のほうでお持ちでしょうか。","respondent":"川部防災安全担当課長","answer":"政府のほうの訓練ということで、正確には政府と自治体の連携訓練ということだと思うのですが、これは秋田県を筆頭に、島根県ですとか、各所で政府と自治体連携の訓練は既に実施されているところです。","voiceIndex":186,"id":"exchange-066"},{"speaker":"大沢委員","kind":"質問","question":"となると、特別区ということで絞り込んでお伺いしますけれども、今、千代田区の小学校がＪアラートが発令されたという想定で訓練を行った。それのみで認識してよろしいですか。","respondent":"川部防災安全担当課長","answer":"私のほうも直接各区なりに当たったわけではないのですけれども、今現在、報道されているというところでは、その１件のみかと思います。自治体として、例えば何々区としてＪアラートが発動したときの訓練を行ったというようなことは今まで掌握はしてございません。","voiceIndex":188,"id":"exchange-067"},{"speaker":"大沢委員","kind":"質問","question":"そうすると、先ほど来のご答弁の中で、まずはＪアラートについて、区民に周知がまず第一義、初段の段階だということで、先ほどのご答弁の中では、まだ全ての部分でしっかりとした対策に対する整備がまだできていないように感じましたけれども、それについてコメントをお願いします。","respondent":"川部防災安全担当課長","answer":"といったように、まず国の対応自体も、今そのような変化、ブラッシュアップを遂げているような段階でございまして、区といたしましても、今後、周知をかけていくにあたっては、いろいろなことを研究、検討しながら、その方法について追求していくべきなのだろうと。","voiceIndex":190,"id":"exchange-068"},{"speaker":"大沢委員","kind":"質問","question":"そうなると、今、ご答弁で伺いました。確かに陳情者の１から４番については、国の危機に関することですから、非常に納得のできるところではありますが、先ほどの避難訓練を防災訓練の中に組み込んだ、あるいは千葉市では小学校でやったという部分で、全体的な体制なり形づくり、対策がまた完備していないのが実情と、今の課長の答弁があった。","respondent":"川部防災安全担当課長","answer":"いろいろとやり方を研究、検討していかなければいけないということは確かなことだと思います。","voiceIndex":192,"id":"exchange-069"},{"speaker":"安藤委員","kind":"質問","question":"こういった重要な不安がある案件ですので、やはり区民の皆さんの付託を受けて行政にチェックしたり、物を言ったりする議会としましては、こうした生の意見を伺う機会はしっかりと保障していくといいますか、それがやはり議会改革にもつながることだと思いますし、私はぜひ積極的にこうした機会があれば受けていくべきではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":197,"id":"exchange-070"},{"speaker":"西本委員","kind":"意見","question":"私も、今回の質疑の内容で、現状、それから課題、これからしなければならないことが、対応していくだろうということも含めて理解した上での結論が出せるかと考えていますので、意見陳述は必要はないと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":200,"id":"exchange-071"},{"speaker":"いながわ副委員長","kind":"意見","question":"いろいろな委員の質疑に対してのご答弁で、防災安全担当課長、防災課長の話を聞いて、品川区の現状は理解できて、今後さらに磨きをかけて、まずこの国民保護法というものがあり、国民保護計画があるということを区民の皆様に知っていただくということが大切なところだと考えていますので、それを今後やるという話も先ほどされておりましたので、特に意見陳述を設けるに至らないと私は思います。","respondent":"たけうち委員長","answer":"それぞれありがとうございました。ご意見が分かれましたので、意見陳述の実施について、挙手にてお諮りしたいと思います。平成２９年陳情第８号についての意見陳述の申し出を受けることに賛成の方は挙手を願います。","voiceIndex":201,"id":"exchange-072"},{"speaker":"大沢委員","kind":"意見","question":"意見は、昨今の東アジア情勢を鑑みますと、この陳情者と懸念を私どもも一にするところではありますが、この４つの項目については、品川区の国民保護計画におきまして、既に実行されている。３番目の避難訓練等々についても、まずはそこに到達するための体制づくり、あるいはこの動き方の周知が肝要と考えます。したがいまして、この陳情については、願意に沿い難い、不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":204,"id":"exchange-073"},{"speaker":"新妻委員","kind":"質問・要望","question":"私も一区民としては、北朝鮮のミサイルの発射に対しては心配事ではありますけれども、今ご説明をいただきましたとおり、国民保護法に基づいて区も行っているということ、また、これからも発射する前のＪアラートが発信されたときの対応が大事であるということ、この周知が必要であるというご説明がありましたので、そのことをしっかりと行っていただきたいという思いを込めますが、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":205,"id":"exchange-074"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは品川区にかかわると、特に日本政府が対話否定論に固執する態度を示している今、やはり区民の命を守るためにこういった危機を何としても防ぐために、区長もこれだけの危機を目の前にしているわけですから、外交には口を出さないと言っている場合ではないと、みずから首相に今こそ対話に踏み切るべきだということを米国政府に説いてほしい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":206,"id":"exchange-075"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"結論を出す。不採択ということで、理由は、先ほど申し上げましたとおり、１項目目、２項目目、４項目目は、既に品川区としてはしっかりと行っているということであります。私は、この品川区民の全ての人に、国民保護法とか保護計画を周知されているとは思えない部分もあるので、ぜひＳＮＳを含む、ホームページは見なければ見られないわけですから、発信をするということは非常に必要だと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":207,"id":"exchange-076"},{"speaker":"筒井委員","kind":"質問・要望","question":"結論を出すということでお願いします。この陳情者がおっしゃるとおり、特に２項目目です、国民保護法の情報を区民に徹底し対処法を啓蒙すること、これは非常に重要だと考えていますので、区民の方が理解しやすいように、そして手にとりやすいように、区議会だよりや掲示板等々、いろいろな媒体を使って徹底した周知を行っていただきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":208,"id":"exchange-077"},{"speaker":"西本委員","kind":"質問","question":"本日、結論を出してください。結果は、不採択です。とりあえず政府と自治体が協力していろいろやっているようでありますが、それで本当にいいのですかというようなことがありまして、もう少し現状を分析しつつ、今の建物がどういう状況になっているのか、品川区内の公共施設がどういう形になっていて、避難する経路がどうなっているのかという細かい準備がやはり必要だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":209,"id":"exchange-078"}]},{"id":"topic-06","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"新妻委員","kind":"確認","question":"１点だけ確認します。たしかこれ、前の委員会のときに、損害賠償額は保険からまかなわれているということを確認させていただきましたが、たびたびこのような報告をいただく中で、年間で見ると、この事故の件数は減っているのでしょうか。それとも毎年同じぐらいの事故が発生してしまっているのでしょうか。","respondent":"工藤品川区清掃事務所長","answer":"年間によってばらつきがあろうかと思いますけれども、昨年が、車の事故が４件、作業中の事故が２件ということで６件でございました。今年度はすでに、今、車の事故が２件、作業中の事故が２件ということで、そういった意味では、少し増えているような状況です。","voiceIndex":216,"id":"exchange-079"},{"speaker":"西本委員","kind":"質問","question":"これは修理費だけなのですけれども、けがとかはいかがだったのでしょうか。","respondent":"工藤品川区清掃事務所長","answer":"けがの状況ですけれども、当日、救急車を呼びまして病院に運ばれたですけれども、その日のうちに退院した。しかしながら、重傷には至らなかったですけれども、胸の部分を打ったというお話を聞いておりますけれども、全治１カ月ということを聞いてあります。","voiceIndex":219,"id":"exchange-080"},{"speaker":"西本委員","kind":"質問","question":"この治療費とかはどこで、ここには計上されないのですか。","respondent":"工藤品川区清掃事務所長","answer":"いわゆる車の部分だけの請求です。その理由といたしましては、通勤の途上だったということで、会社のほうの通勤災害のほうでまかなわれるというお話をされておられました。そのような中で、私ども、示談をしたです。","voiceIndex":221,"id":"exchange-081"}]},{"id":"topic-07","title":"平成２８年度指定管理者による管理に対するモニタリング・評価","agenda":"平成２８年度指定管理者による管理に対するモニタリング・評価","exchanges":[{"speaker":"新妻委員","kind":"質問","question":"ご説明ありがとうございました。ここに自転車定期、当日、バイク定期、当日と利用率が書かれておりますけれども、この当日と定期のバランスといいますか、定期と当日の利用率は場所によって違うと思うのですが、このバランスは、利用率を見て変わっていく、定期が少ないから当日を多くしようとか、逆に定期が足りないから当日を減らしてというような、そういうことは日常行われているものなのでしょうか。","respondent":"桑波田交通安全担当課長","answer":"区営の駐輪場のほうは、定期と当日ということでご利用いただいていますけれども、今現在、そういった改修工事も実施しておるところですけれども、やはり定期をご利用していただきたくても、どうしても場所がなくて使えないという方もいらっしゃいますので。","voiceIndex":232,"id":"exchange-082"},{"speaker":"新妻委員","kind":"質問・要望","question":"なので、ちょっとここ、調査をしていただいて、かなり広い、置く場所はありますので、定期のところをちょっとずらして当日枠を増やしていただく対応をしていただきたいと思うのですが、いかがでしょうか。","respondent":"桑波田交通安全担当課長","answer":"ここは定期利用の利用率が非常に低い状況にありますので、その分、当日も多いという状況があります。この辺は指定管理者とも、そういった人員の関係等もありますので、その辺はよく調整させていただきながら検討していきたいと思います。","voiceIndex":234,"id":"exchange-083"},{"speaker":"安藤委員","kind":"確認","question":"そこら辺はどうなっているのかと、そういう裁量権があるのか、それともそこは区でしっかり決めていることなのか、そこを確認したいのと、あと、定期の利用率が下がっていて、当日がかなり上がっているのですけれども、これは原因は何でしょうかというのが２点目です。それと、使用料と委託料の関係なのですけれども、お伺いしたいと。","respondent":"桑波田交通安全担当課長","answer":"自転車の定期のほうは、平成２７年度より減っておりますけれども、やはりこういったところは、大型車への対応が増えてきたことによって、やはり自転車の置く場所的に狭くて、使えるような状況が影響して年々下がっているという状況だと思います。","voiceIndex":237,"id":"exchange-084"},{"speaker":"安藤委員","kind":"質問","question":"それはどういう関係で委託先は運営しているのかということをお伺いしたいと思いますのと、統括責任者の方が平日毎日来庁しているということですけれども、すごいことだなと思ったのですけれども、毎日来庁して何をやっていらっしゃるのかお伺いしたいと思います。区営住宅のほうにもいきますけれども、これも同様に管理委託料と使用料がありますけれども、この関係についてお伺いしたいと思います。","respondent":"桑波田交通安全担当課長、長尾住宅課長","answer":"来庁の関係なのですけれども、こちちはＮＣＤの方が当日の使用の状況の日報等もお持ちいただきまして、当日あったようなこと、もしくはいろいろな要望等があった場合は、当区の係のほうにお届けいただいて。管理運営委託料も同様になっております。修繕のお話ですけれども、この指定管理料の中で組み込まれた形で指定管理者がこの予算の範囲内で行っているものです。","voiceIndex":239,"id":"exchange-085"},{"speaker":"安藤委員","kind":"質問・要望","question":"わかりました。短時間無料枠を設けない理由は何かあるのかと、お伺いします。これらの意見や要望を住宅管理に反映させているというふうにあると思うのですが、これはいいことだと思うのですけれども、具体的にはどのような意見が出ていて、それを反映させているというのは、具体的にはどのような例があるのでしょうか。お伺いしたいと思います。","respondent":"桑波田交通安全担当課長、長尾住宅課長","answer":"区におきましては、やはり通勤・通学の方にお使いいただく、そういった長時間とめる方に対してご利用いただくということもありますので、やはり無料にしますと、短時間の自転車が増えることによって。それらに対して、直接関係する方が把握できる場合は、その方たちに対してお話を直接伺い、双方伺った上で、適切なアドバイスといいますか、仲介に入るであるとか、あとは、その当事者だけではなくて。","voiceIndex":242,"id":"exchange-086"},{"speaker":"西本委員","kind":"質問・要望","question":"宅建のほうです。これは滞納者への対応は、全てこの宅建にお願いをしているのでしょうかということ。それに対しての引き継ぎみたいなものはどうなっているのでしょうかということ。その工夫も何かできないのですか。今は入れてしまうと、１分でも、入れたら出すときに１５０円かかってしまうという、そういう現状になってしまったのですけれども、それは何か工夫できないのでしょうか。いかがでしょうか。","respondent":"長尾住宅課長、桑波田交通安全担当課長","answer":"３つ目につきましては、高齢のひとり暮らしの方への対応というところですけれども、区のほうでも、特に高齢の方、６５歳以上の方が住まわれている状況も把握しておりますので、区営住宅であれば宅建管理センターになりますけれども。これはほかの駐輪場のほうでも入れていますけれども、それ以外に、今度、自分で発券機で券を買ってもらって、そのシールを張ってもらうような場所もありますので、そういった両方の対応をしているのですけれども。","voiceIndex":246,"id":"exchange-087"},{"speaker":"西本委員","kind":"質問・要望","question":"宅建のほうはわかりました。１回入れても出せたと思うのです。多分、ちょっと前だとは思うのですけれども、そんな感じがしていたので、最近は１５０円要るのだと思って使っているのですが、そこら辺の経過を調べていただいて、可能であるならば、そのぐらいの配慮はしてほしいと思うのです。そこら辺はある程度わかる可能性はあると思うので、そこら辺の考慮はしていただくことはできないのでしょうか。","respondent":"桑波田交通安全担当課長","answer":"このラック式で電磁ロックというのは、私の知る範囲では、５分間無料だったということは把握がないのですけれども、やはり不正利用といいますか、ちょこっとかけてロックがかかるまで入れない人とか、脇に置いて入れたように見えるような感じとか。","voiceIndex":249,"id":"exchange-088"},{"speaker":"いながわ副委員長","kind":"確認","question":"駐輪場の件で本当に細かいことなのですが、その前に、これは、指定管理者にモニタリングシートか何か出して、どういう取組みをしているかを全部書いてもらって、最終的に品川区の所管がそれを確認して、この総括シートに何か書くという感じで流れとしてはいいわけですね。この接遇に関するテストとは何なのですかという。それを詳しく、簡単にでも構わないので教えてください。","respondent":"桑波田交通安全担当課長","answer":"この接遇に関するテストなのですけれども、こういったものは利用者への対応ですとか、個人情報の取扱いですとか、２０問程度のテストを行いまして、サービス向上に齟齬がないように努めるような内容のテストになっております。","voiceIndex":252,"id":"exchange-089"},{"speaker":"いながわ副委員長","kind":"質問","question":"要は、テストに１回合格してしまえば、もういいのですねという話にしか見えないのです。その中で１回テストをやって、しかも何回もやってようやく受かって、お客様の対応をして、１年間何もなかったら、またもとに戻ってしまうような気がするし、だから、これ、評価する視点が違うのではないかと思うのですけれども、いかがでしょうか。","respondent":"桑波田交通安全担当課長","answer":"こういったときに、事前の教養で実施されているものでありまして、それ以降も、毎月上長会議等がありまして、そこでの指示事項ですとか、こういった事案があったのだということは、逐一現場で働いている方にも情報提供ですとか。","voiceIndex":254,"id":"exchange-090"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4212#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":70742,"voices":260}},{"id":"h29-20170925-9","meetingId":"h29-cm09","date":"2017年9月25日","dateIso":"2017-09-25","committee":"文教委員会","time":"午前１０時００分～午後 ２時４５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を96件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第６２号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第６２号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"これまでもいろいろ出されている公務災害補償と同様に変更されるものだと思いますけれども、今回、条文の議案の書面を見ると扶養親族というのが新たにつくられるような形で書いてあるのですけれども、今までもそういったものがあったということの確認と、あと、２００円や３００円という額の算定の仕方について伺いたいと思います。","respondent":"有馬学務課長","answer":"一方、子どもにつきましては６,０００円を９,０００円に引き上げるということで、それを３０日で割ると１日当たり３００円となるものでございまして、子どもは２００円から３００円に引き上げとなります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、今回配偶者のほうが引き下げられて、子どものほうが引き上がったというところで、今までに品川区において、この公務災害補償を受けた方はいらっしゃるのか、また対象となる方が何人ぐらいいらっしゃるのか伺いたいと思います。","respondent":"有馬学務課長","answer":"これは以前、平成１３年度までは都条例ということでしたが、平成１４年に地方分権一括法により市町村が主体的に取り組むということで平成１４年度から移行されておりますけれども、その後１件も公務災害に該当しているというものはありません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"先ほどの説明の中で、主な改正内容の(1)のウ以降の説明のところが少しきちんと認識できなかったので、大変申しわけないのですけれどももう一度説明していただけないでしょうか。経験年数が１０年から１６年未満と１６年以上ということについては、メモできたのですけれども、それ以降の説明のところを教えてください。","respondent":"有馬学務課長","answer":"アの配偶者の２００円というところはよろしいでしょうか。","voiceIndex":10,"id":"exchange-003"}]},{"id":"topic-02","title":"第６３号議案 品川区立図書館条例の一部を改正する条例","agenda":"第６３号議案 品川区立図書館条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、大崎図書館の移転と分館設置ということで、現在の大崎図書館は区もご存じのとおり地域の名士の方の邸宅跡を図書館にしてほしいという願いから建物計画などを、区の営繕課がやったというお話も聞いております。現在、この大崎図書館でいろいろ行っています読み聞かせなどは、いつ頃から行っているのか伺いたいと思います。","respondent":"横山品川図書館長","answer":"申しわけございません。読み聞かせの開始の記録については、詳細なものを手元に持っておりませんが、開館当時からおはなしの部屋を用意していますので、開館のときから行われていたものと思われます。","voiceIndex":32,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"開館のときから行われていたということで、活発に読み聞かせなどを行っていたと思うのです。そういった図書館をなくすということは、やはり子どもたちが日ごろ読書に親しみを持つことを気にかけている区の損失になるのではないかと思うのですけれども、この点いかがでしょうか。","respondent":"横山品川図書館長","answer":"一番最初にできます大崎駅西口の取次施設についても、ただの取次施設ではなく、子どもの読み聞かせスペースであるとか、地域の方が交流するような場所を検討するという形で今進めてきているところでありますし、新しい大崎図書館につきましてもおはなしの部屋を設けて。","voiceIndex":34,"id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"それだけやはり地域の方々に利用されている図書館をなくす理由は何なのか伺いたいと思います。そして、分館に多目的室があると思うのですけれども、以前お聞きしたときにはそこで読み聞かせなどを行うということでしたが、この多目的室は図書館専用のものになるのか、もしならないとすると、貸室のような扱いということであれば使用が有料になるのかも伺いたいと思います。","respondent":"横山品川図書館長","answer":"こちらにつきましては従来からご説明させていただきましたように、現大崎図書館については老朽化により施設の存続についてかなり無理が来ている状態であったことと、産業支援交流施設、ＳＨＩＰが開設したことに伴いまして。","voiceIndex":36,"id":"exchange-006"},{"speaker":"のだて委員","kind":"質問・要望","question":"地域の方が求めているのは、現在地に残してほしいということなのです。区の公共施設等管理総合計画でも築３０年の場合は改修だと、大崎図書館は築３２年ぐらいでしたか、そのぐらいなので改修で十分やっていけるかと思うのです。以前は品川区も改修で予算組みをしていたと思うのですが、移転に変わった理由というのは何なのか伺いたいと思います。","respondent":"横山品川図書館長","answer":"その間、また別の施設を用意して戻ってくるというようなリスクを考えますと、先ほどご説明しましたように北品川五丁目に新しい用地が取得できる見込みがあって、それと比較考慮しますと移転したほうが皆様のためになるということで合理的な判断をさせていただいたところです。","voiceIndex":38,"id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"蔵書数としては全体では上がるという話ですが、新大崎の閉架書庫が３万点ありますけれども、これも利用者の方が借りられるということなのでしょうかということと、改修を行った場合は建てかえと同じレベルになってしまい、合理的に考えると移転のほうがいいというお話でしたけれども、やはり現地での存続が住民の方に望まれているというところをしっかりと受け止めて。","respondent":"横山品川図書館長","answer":"１点目の閉架書庫につきましては、こちらも全て新・大崎図書館もしくは平塚書庫のほうに移転する予定でございまして、今現在もそうですが、利用者の方にご予約いただきますと、書庫からお出ししてお貸し出しするものです。","voiceIndex":40,"id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"最初に分館について、図書館法に基づくものなのかということをお聞きしたので、基づくということでいいのかどうか確認させていただきたいと思います。そしてこの間、区も認めているところではありますけれども、この大崎図書館の移転、実質廃館の背景には、補助２９号線道路を進めるために行われているということがありますけれども、改めてそこのところを確認させていただきたいと思います。","respondent":"横山品川図書館長","answer":"子どものコーナーのことなのですが、こちらにつきましては芳水小学校が現在の大崎図書館よりも面積的には少なくなってしまうので、割合から言うと児童用の座席が一見少なくなっているようにも思いますが、こちらは多目的室がほとんど子どもの事業で使うということ。","voiceIndex":44,"id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"図書環境を考えたうえで移転するものではないというふうに受け止めてしまいますので、やはり現在の大崎図書館を守っていくということも含めて考えていただきたいと思いますけれども、いかがでしょうか。これら３施設が開設されていく中で、それに合わせて廃館になっていくのか、どういったスケジュールで何が行われるのか、伺いたいと思います。","respondent":"横山品川図書館長","answer":"その間、図書の関係施設がなくなってしまうことを補うために、大崎駅西口の取次施設を２月にオープンさせることで、芳水小学校跡の図書施設の開設予定である平成３１年１月まで、西口の図書環境を支えていくような予定です。","voiceIndex":46,"id":"exchange-010"},{"speaker":"のだて委員","kind":"質問","question":"今、現在の大崎図書館について、このままにしておくと危険性があるというお話でしたけれども、どういった危険性があるのか具体的に伺えればと思います。現在、大崎図書館は平成３０年３月末で閉館というと、今年度で閉館ということですけれども、利用者の方にはそういったことをもう十分お知らせされているのか伺いたいと思います。","respondent":"横山品川図書館長","answer":"平成３０年３月に閉館することについてのお知らせにつきましては、今、館内でお問い合わせにお答えできるようスタッフにいろいろなお答えをするような文言というか、統一的にお答えできるよう準備をしています。","voiceIndex":51,"id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"そもそも品川区はさまざまな公共施設を持っていますけれども、その公共施設の改修あるいは廃館ということについて、この間、どのような事例があったのか、その年限が３０年ということで、あった事例というのはどの程度あるのか、まずそこについて伺いたいと思います。","respondent":"横山品川図書館長","answer":"ただいま、区全体の改修の具体的なスケジュールについては手元にございませんので、具体的にお答えすることはできませんが、区の方針としまして、年限として３０年、もしくは６０年というような指標が出ておりますけれども、それは個々の状況に応じてということで。","voiceIndex":54,"id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"そのような甘い考え方ではないと思いますよ。それに、移転や廃館というふうなことを出す品川区として、そういう資料も準備しないで臨むというのは、私はいかがなものかというふうに思います。きちんとした答弁を求めたいと思いますので、資料を用意してください。でないと質問ができません。委員長、取り計らってください。","respondent":"つる委員長、横山品川図書館長","answer":"公共施設全体のことについては、所管がまた違うと思います。図書館に関してのことであれば、品川図書館長がお答えできると考えております。次の建てかえにつきましては具体的に出ているところではないのですが、老朽化に応じまして、築年数が古いところから検討してまいるような予定です。","voiceIndex":56,"id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"私どもが持っている資料は、建てかえの更新、あるいは改修、そういうものについて社会教育系施設の改修、大規模改修というのは３０年、そして建てかえは６０年となっています。これに基づいてやっているのではないかと思うのですけれども、それについてはどうかということを１つ答弁してください。そのところで、そういう経過を図書館としてはどういうふうに見ていたのですか。","respondent":"横山品川図書館長","answer":"ご指摘のとおり、３０年を超えた施設については改修、６０年については建てかえという原則はありますが、図書館につきましては早くから皆さんのお力で図書館を整備させていただいた反面、古い施設が多くあります。","voiceIndex":59,"id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"図書館は区の財産なのですから、区民の方にしっかり利用していただきたいということで、必要な財政を充ててつくってきましたし、さきほどのだて委員も指摘をしていたとおり、過去のいろいろな地域の方の思いが詰まってでき上がった図書館なので、他の図書館も活発に利用されていますけれども、この大崎図書館はとりわけ利用がされていたと。そして、そういうことに対して地域の住民は誇りも持っていたと。","respondent":"横山品川図書館長","answer":"考え方の違いだとは思うのですけれども、書庫につきましては、大切に使った結果、もう寿命が来てしまった状況で、本当に大規模な書庫ですので、それを取りかえる場合には、施設の建てかえ規模の改修が必要になります。","voiceIndex":61,"id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"３０年間大事に使い続ける、当たり前です。そうして３０年の間には、ここを改修したほうがいいなどの声が当然出ていたと思います。その点について１つ答弁をいただきたいと思います。今、品川区は、そういう指導を他の公共施設でも全部しているではないですか。では、なぜ図書館だけきちんとやらなかったのですか。その辺がわかりませんから、きちんと答弁を適切な役職の方にお願いしたいと思います。","respondent":"横山品川図書館長","answer":"結果として部品が足りなくて補修ができない状況が生まれておりますけれども、それは皆さんに使っていただきたくて大切にだましだまし施設を補修して使ってきたところです。その他の補修については毎年、大崎図書館についても予算を立てて改修をしてきたところです。","voiceIndex":63,"id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"大前提ですから。ですからそれに応じた適切な維持管理は必要だし、当然していると思うけれども、そういうことを全てきちんと行った上で、３０年しかたっていないのに使えない、こういうことで済ますわけにはいかないではないですか。利用者の方々、図書館利用者、あるいは近隣住民、そういう皆さんにどういう説明をしてこられたのか、それについて１つ伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"私が聞いたのは、説明会をしたのかというふうに聞いたのです。説明会はしたのですか。問い合わせに対して答えているというのは説明会にならないのではないですか。説明会だというふうに認識されて答弁されたということですか。","respondent":"横山品川図書館長","answer":"説明会という形で説明したことはございません。ただ、地域の町会長の集まりであるとか、地域を代表する方の場において、今の状況をご説明するということはしています。","voiceIndex":72,"id":"exchange-018"},{"speaker":"南委員","kind":"質問","question":"町会長に対する説明は、それは否定はしません。したほうがむしろいいと思います。しかし、私が聞いている説明会というのは、先ほども申し上げたように利用者の方々、大崎図書館を利用しておられる方々、そして近隣の住民の皆さんに説明会をしたのかということを聞いたのです。それはしていないということで先ほど答弁されたというふうに認識していいのですか。","respondent":"つる委員長","answer":"そのとおりに聞こえますが、確認しますか。","voiceIndex":74,"id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"私は、やはり地域の住民が、特にこの地域は、地域の住民がつくってほしいと、しかも土地まで提供してくださっています。だからこそ、広くなっても現在地から８００メートルも先まで行かなければいけないようなところにつくっても、地域の皆さんの思いは潰されたと思われてしまうと、私はそう思うのだけれども、そういうふうには思わないですか。","respondent":"横山品川図書館長、本城教育次長","answer":"それだからこそ、以前にいただいた請願を受けまして、大崎駅西口に図書取次施設、また芳水小学校に分館を設ける形で、今までの思いを受け継いだ、子どもを中心とした事業を発展させて、今度は新たに地域の方のお声もいただいて。まさにこういった対応は区民からいただいた趣旨、そしてこの委員会でも趣旨採択した趣旨にかなったような形で、現実としてこのような形で進めていると考えているところです。","voiceIndex":78,"id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"それが１つです。そういう認識はないのですか。あそこに行っているのですか。そして、今後どうするのか改めて聞いたら、あそこは会員制の施設なので、会員制のごく一部の人しか利用できないような施設に、区民の全ての皆さんが利用できる図書館の本を持っていくというのは、これは正しくないということでやめましたというふうに聞いていますけれども、そのことについて区の認識はどうなのでしょうか。","respondent":"横山品川図書館長","answer":"２点目のＳＨＩＰの開設につきましては、過去の記録を読ませていただきましたけれども、ＳＨＩＰの開設によってビジネス支援の本を動かすということはご説明させていただいておりません。","voiceIndex":81,"id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"そのように指摘をしておきます。その点についてが１つです。ですから、あの地域に６月までの２カ月の間は図書館がないということになるわけです。取次所がオープンしたにしても、そこでの取次所の事業内容は、現在の大崎図書館がやっている事業内容とは差が出てこざるを得ないではないですか。近隣の図書館に行かなければいけない、そういう空白期間があることについてどう考えているのかについて伺います。","respondent":"横山品川図書館長","answer":"１点目の説明会につきましては、確かに地域の皆さんに対する説明会は今現在させていただいていない状況です。区の方針につきましては議会の委員の方々のご審議を経て決定するものですので、正式にご説明するのはこの議会の後というふうに図書館側は考えているところです。","voiceIndex":83,"id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"後でするとおっしゃるけれども、それは決定した後ですから説明会とは言わないです。何を説明するのですか。ここから北品川５丁目に移転しますよ、大崎駅西口に取次所ができますよという説明、それは説明とは言わないではないですか。説明会という認識、区民が求める説明会というものと違うと思います。先ほども何回も言っているけれども、地域の要望が高まってつくった施設をなくしてしまうわけですから。","respondent":"横山品川図書館長","answer":"説明会についてなのですが、区の方針は議会のご審議を経てご了承を得た後、正式に決定するものだと承知しておりますので、そのことについて皆さんにお諮りするのはこの議会だと考えています。それが１点目です。","voiceIndex":86,"id":"exchange-023"},{"speaker":"南委員","kind":"意見","question":"最後に、１つ目は説明会の問題です。先ほども言ったようにそういうやり方は一般常識や社会常識では説明会とは言いません。引き続きいろいろな部分でやっていきたいと思っています。最初からやはり移転ありき、そこのところが大問題、大間違いだと、ボタンを１つ、区民との関係ではかけ違えたと、そこはやはり認めていくべきだと思います。そういうふうに指摘をしておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":88,"id":"exchange-024"},{"speaker":"こんの委員","kind":"確認","question":"その上で確認なのですけれども、ここの施設に限らず、区全体の図書館のあり方というところを少し確認というかお聞きしたいところなのです。そこでその対策としてどのようなことをお考えなのかというのが２点目です。それから、分館ですから本館との間をオンラインで、いわゆるどういう図書があるのかというのがきちんとつながって、分館で見られるようになっているのかということの３点をお聞きします。","respondent":"横山品川図書館長","answer":"ですのでご不便はおかけしないのですが、特に大崎の本館・分館についてはレクリエーションの事業であるとか一体での蔵書管理であるとか、そういう意味での連携を他の地区館以上に、一体で運営する予定になっております。","voiceIndex":90,"id":"exchange-025"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひお願いしたいと思います。その上で今、館長がおっしゃってくださったように、借りる方がより借りやすい環境ということが大事だと思いますので、お届けをするというサービスは非常に大事で、ご自宅にお届けする、あるいは返すのもやっていただけるとなると、非常に借りやすい環境が生まれるのではないかと思うので、この辺のところをより工夫をしていただきたいことを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":94,"id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"委員長、ほかになければ質問したいのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-027"},{"speaker":"南委員","kind":"質問・要望","question":"区が書いている広報の中に、この地域は住民の要望がたくさんあったと、図書館がない地域だったので図書館をつくりましたと、そういう紹介もあるのです。分館や取次所をつくるようですけれども、しかし今大崎図書館が果たしているさまざまな事業を分館や取次所で本当にイコールになるのかどうかということをどういうふうに考えているか伺いたいと思うのです。","respondent":"横山品川図書館長","answer":"子ども向けの事業につきましては、先ほどご案内しましたが、芳水小学校の分館でも西口図書取次施設でも、新・大崎図書館でも行いますので、こちらについては同等以上、より充実した形で子ども向けの事業を実施します。","voiceIndex":98,"id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"そこはもうきちんとした図書館ですから、しっかりやっていただきたいと思います。説明では同等の機能を有するのだとおっしゃっているわけですから。先ほども、のだて委員が質問されたけれども、子どものスペースは芳水小学校の分館と取次施設で同等の機能が保たれるのですか。それはついていたのだけれども、今度２つに分かれたところでどのくらい確保されるのか、同等なのか、それを伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":100,"id":"exchange-029"},{"speaker":"南委員","kind":"質問","question":"それだったら同等の機能なんて言えないではないですか。これからできてから検討するということであれば、同等の機能なんて言ってごまかさないほうがいいと思います。その辺を指摘をしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":106,"id":"exchange-030"},{"speaker":"渡部委員","kind":"質問・要望","question":"特に質問などをしなかったのは、先ほどもありましたように平成２６年の請願の段階で移転させるということに地域の方々からかなりいろいろな声が上がって、そこでちょうど建築、改築予定の芳水小学校のほうで何とかできないかということで、相当地域の方からも要望がありましたし、私どもも近い議員にしても、区長にしても相当な英断・決断があってやっと本日議案が出てきたのだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-031"},{"speaker":"南委員","kind":"意見","question":"今、質疑した中身が反対の理由なのですけれども、改めて簡潔に言うと、移転というふうに言っているけれども、実質大崎の地域は廃館にする、図書館がなくなる、代替施設はあるにしても、それは同等の機能ということはいまだにはっきりできないという状況ですし、しかも説明会もしていないというこういう点は、やはり賛成はできないです。反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":112,"id":"exchange-032"}]},{"id":"topic-03","title":"第５９号議案 平成２９年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第５９号議案 平成２９年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"区役所の近くにできるというところで、今までの病児保育の２カ所ではそれぞれ２人ぐらいの定員になるのでしょうか。ごめんなさい。今ある施設の定員数を教えていただきたいのと、今度は６人ということなのですが、保育士あるいは必要な看護師も含めて職員の配置の基準はどういうふうになっているのか、その辺が２つ目です。","respondent":"佐藤保育課長","answer":"実施スペースですが、こちらに関しましては都の要綱等で児童１人当たり１.９８平方メートル以上、観察室として大体３.３平方メートル以上の施設が必要ということになっております。","voiceIndex":123,"id":"exchange-033"},{"speaker":"南委員","kind":"質問","question":"平米数ですけれども、そうなると当然この施設は６０平方メートルなので満たしているという認識でいいのか、そして病児保育ですから必ずしも同じ年齢とか乳児に限らないと思うのですが、０歳から５歳までいろいろな子どもが親御さんの就労状況等によって違ってくると思うのですけれども、そういういろいろな異年齢にある中で保育士が３人に１人という考え方で配置をするということでいいのですか。","respondent":"佐藤保育課長","answer":"２点ほどご質問いただきました。１点目の新施設の保育室の関係ですが、６０平方メートルを予定しておりますので、６人定員ですので大体１２平方メートルぐらいあるという形で施設としては十分要件を満たしております。","voiceIndex":125,"id":"exchange-034"},{"speaker":"鈴木（博）副委員長","kind":"質問・要望","question":"かねてから要望していた病児保育の新しい施設がめでたく１つ誘致に成功して開設されるということは、課長・部長をはじめ関係者のご努力のたまものだと思って、非常に高く評価するとともに、敬意を表したいと思うのですけれども、幾つか問題がありまして、まず１つは病児保育というのは従来から都のほうで開設に向けていろいろ働きかけてきたにもかかわらず、全く医療機関から手が挙がらなかったということは。","respondent":"佐藤保育課長","answer":"１点目のキャンセルの関係なのですが、この件に関しましては以前も、ご質問いただいているところなのですけれども、私どもとしてはキャンセルの扱いというのを明確にして、どういったことができるかということを検討したいと考えているのですが。","voiceIndex":130,"id":"exchange-035"},{"speaker":"高橋（し）委員","kind":"質問","question":"済みません。それから、開設後の補助については今お話があったように看護師と保育士の経費というか、それは委託料で持つというイメージでよろしいでしょうか。","respondent":"佐藤保育課長","answer":"来年４月以降、採用されている保育士の分と看護師の分に関して基本的に委託料をお支払いします。そして新しい予算の中で考えますが、お預かりした子どもの数に応じてインセンティブのような形で出せればということを検討しております。","voiceIndex":134,"id":"exchange-036"},{"speaker":"のだて委員","kind":"質問","question":"今回、本会議でも答弁があったと思うのですけれども、今後も増やしていきたいということですが、具体的な方針として今の段階で言えることがあれば伺いたいと思います。現在の利用状況を教えていただければと思います。","respondent":"佐藤保育課長","answer":"１点目のご質問は今後の事業展開ですが、品川区子ども・子育て計画では現在年間約２,５００人程度のほかさらに需要が見込めるということになっていますので、大体年間８００人ぐらいお預かりする施設が開設できれば、あと３施設ぐらいは必要な状況だと認識しておりますので。","voiceIndex":137,"id":"exchange-037"}]},{"id":"topic-04","title":"平成２９年請願第１０号 大崎図書館を２９号線道路のためになくさないよう求める請願","agenda":"平成２９年請願第１０号 大崎図書館を２９号線道路のためになくさないよう求める請願","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"やはりこういった親しまれていた施設であれば、利用者の方の意見も聞きながらどうしていくべきかということをしっかりと考えていくべきだったと思いますけれども、いかがでしょうかと思います。先に図書館が決まって、移転の方針を決めて補助２９号線道路の打診があったということなのか、これは過去の答弁と違っているという印象を受けるのですが、その点についても伺いたいと思います。","respondent":"横山品川図書館長","answer":"２点目の、移転の補助２９号線の前後につきましては、図書館部局としましては移転を決定した後に行財政改革特別委員会等で検討しております話について伺ったところです。","voiceIndex":155,"id":"exchange-038"},{"speaker":"のだて委員","kind":"質問","question":"この議会が終わった後ということですけれども、やはり地域に親しまれた施設ですから、計画段階から住民の方からお話を聞いて計画をつくっていくべきだったと今も思っております。やはり区自ら広く住民の方に知らせていくというのが普通だと思いますし、利用者の意見を計画段階から聞いていくといったことが必要だと思いますけれども、このお考えを改めて伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":157,"id":"exchange-039"},{"speaker":"のだて委員","kind":"質問・要望","question":"同じ答弁なのですけれども。この後説明するというお話ですけれども、今のお話だと町会長と自治会長を中心にというお話だったと思うのですけれども、そうすると利用者の方にどれだけお知らせするのかという気がしますので、しっかりと利用者の方に広くお知らせできる方法として、他の方法も考えていただきたいと思いますが、いかがでしょうか。","respondent":"横山品川図書館長","answer":"この後、地元の代表でいらっしゃる町会長・自治会長にご説明するとともに、従来行っていますカウンターでのご説明、また館内の掲示、また広報しながわ等でのＰＲであるほか、地元での掲示等でもこれから周知を図っていくつもりです。よろしくお願いします。","voiceIndex":160,"id":"exchange-040"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり現地での整備を求めているということ、建てかえればできると思いますので、現地での存続という住民の声を区として取り上げていただきたいと思います。補助２９号線道路の関係でも、やはり道路によって大崎図書館が移転、実質廃館ということになっていく点もどうなのかと、おかしいと考えていますので、ぜひそういったところを考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":162,"id":"exchange-041"},{"speaker":"南委員","kind":"質問","question":"請願の後半部分に、区は議会で都のほうから補助２９号線道路の関係の話があって、そうした代替できるところはないかという打診があった、そういうところに協力していくという形をとりたいということで、これはまさに補助２９号線道路ができるために大崎図書館を移転させていくのだということを、協力していく形をとりたいというのはそういうことを示しているのかと私は理解したのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":164,"id":"exchange-042"},{"speaker":"南委員","kind":"質問","question":"私が質問したのは区が答弁しているということについて聞いているのです。私は、補助２９号線道路の計画を進めるために協力をしていくという形をとりたいというふうに読んだのですけれども、そうではないのですかと聞いているのです。","respondent":"本城教育次長","answer":"今ご指摘があった部分についてが教育部局の責任でお答えしたことではありませんので、繰り返しになりますが、私どもからの答弁は差し控えします。","voiceIndex":167,"id":"exchange-043"},{"speaker":"南委員","kind":"質問・要望","question":"そうしますとこの請願審査、私は審査できません。保留しなくちゃいけなくない。関係の部局の担当者をぜひ招いて、午後から調整していただいたらやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":169,"id":"exchange-044"},{"speaker":"南委員","kind":"質問・要望","question":"私は違うと思うのですよね。区が過去に答弁しているわけでしょう。しかも先ほどの説明には、ここの部分に関しては全然説明がなかったから、わからないので質問したら担当ではないので答弁できないということであるのだから、答弁できる人をこの委員会に呼んでこないと、この請願審査できないです。だから呼んでいただきたいというお願いを委員長にしているわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":171,"id":"exchange-045"},{"speaker":"南委員","kind":"質問・要望","question":"失礼かどうかは改めて判断したいと思いますけれども、少なくとも失礼なことを言いたくて言っているわけじゃありません。ですからその関係の答弁をできる方に来ていただいて、この時間内にできなければある程度のその方のいらっしゃる委員会との調整をぜひしていただいて、取り扱っていきたいというふうに思っておりますので、委員長として判断していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":173,"id":"exchange-046"},{"speaker":"南委員","kind":"提案","question":"ご提案ありがとうあります。しかし、さきほどの答弁は差し控えたいということなのですから、それが現時点での教育委員会の見解なのだと思うのです。ですから、それ以上のことは聞けないので、関係の担当者に来ていただく、そういう計らいをしていただきたいというお願いなのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":175,"id":"exchange-047"},{"speaker":"渡部委員","kind":"質問","question":"移転が決まれば空き地はできるわけですから、ではそこをどういうふうに使おうかというのを、これはどなたが答えたかわかりませんけれども、その代替地でこういう打診があった、だったらそこに協力したいというのは当たり前の答えであって、それをどうこう、ここでとやかくというのは、図書館とは全く関係ないですし、現に最初からの議論として図書館の移転が決定してから道路の話があったのだと、再三。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":176,"id":"exchange-048"},{"speaker":"南委員","kind":"質問・要望","question":"あまり感情的にならないように進めたいと思っています。どんなに答弁されても払拭できない。解明されるような答弁をしていないから、払拭できないのです。ですからそこをきちんと聞いて、そうではないのだという具体的な事実を示していただければ納得するかもしれません。それがないのですから、ここに触れざるを得ないのです。差し控えたいなどということではなくて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":177,"id":"exchange-049"},{"speaker":"渡部委員","kind":"意見","question":"だから、図書館が移転が決まりました。移転しようと考えました。その後に道路の話が出てきました。だったらそこが空いているから協力しましょうというのは普通ですよね。誰が聞いてもわかりますよね。以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":178,"id":"exchange-050"},{"speaker":"南委員","kind":"質問","question":"私の質問は全然解明されません。渡部委員がおっしゃったけれども、その見解とは違うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":180,"id":"exchange-051"},{"speaker":"南委員","kind":"質問","question":"だから、同じです。協力していくという形をとりたいというのはどういうふうに区は評価をしているのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":182,"id":"exchange-052"},{"speaker":"南委員","kind":"質問","question":"そういう考え方を持っているわけですよね。それに対して教育委員会としては、大事な図書館行政の１つである、しかも全国的にすごく評価されている児童へのおはなし会、そういうものを行う場所、しかもでき上がった背景が住民の切実な願いがあって、運動があってあの図書館ができたという、他の図書館にはない経緯があります。こういう理解を私はするのですけれども、教育委員会の理解とはどういうことですか。","respondent":"本城教育次長","answer":"ただ、もともと図書館長から再三ご説明させていただきましたように、大崎図書館の移転自体につきましては、教育部局の老朽化を契機にした総合的な判断の中で移転を決定したものであって。","voiceIndex":184,"id":"exchange-053"},{"speaker":"南委員","kind":"質問・要望","question":"私はとても残念だと思います。代替施設をつくればいいという問題ではないのです。だからこだわるわけです。そういう問題の１つだということを理解して、やはりきちんとやっていただきたいと思います。ですから、現地で存続させていただきたいというこの住民の皆さんの願いは本当に理解できるところだし、私は実現できるようにあらゆる力を尽くして頑張っていきたいと思っています。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":186,"id":"exchange-054"},{"speaker":"南委員","kind":"質問","question":"終了していいのですけれども、次に行く前に発言していいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":189,"id":"exchange-055"},{"speaker":"渡部委員","kind":"質問・要望","question":"先ほども議案審査で申し上げましたように、平成２６年からいろいろ始まっている中で、私どもの会派としてもこの件については地域の方々からの要望等もいただいて、何とかこの北品川への移転、そして芳水小学校の分館、大崎駅西口の取次施設という形で、大崎の地域の方々にこれからも図書館を継続して利用していただけるような仕組みづくりということで進めさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":195,"id":"exchange-056"},{"speaker":"こんの委員","kind":"質問","question":"本日、結論を出すということでお願いします。ということと同時に、移転によって今まで現在地で本を借りられていた方、借りるのに少し困難を要している方などに対して、今まで以上にサービスを向上させるという対策も先ほど伺いましたので、それについてはこの請願の趣旨には当たらないというふうに思いますが、区の姿勢としてはそれを理解できますので、この請願に対しては不採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":197,"id":"exchange-057"},{"speaker":"南委員","kind":"質問","question":"先ほど挙手して発言したかったことは、先ほどの条例審査のときも理由を述べないで態度を表明された会派がいましたけれども、私はやはり今回の請願でもきちんと、賛成にするにしても反対にするにしても、その理由は明確にするべき、それが付託された議員の責務だというふうに思いますので、ぜひそういうふうにそれぞれ戒めてしっかりと発言できるように努力をしていければいいかなと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":199,"id":"exchange-058"},{"speaker":"松永委員","kind":"意見","question":"本日結論を出す。私たちの会派で話し合った結果、不採択にいたします。先ほど条例議案の中で質疑等がいろいろありましたように、現大崎図書館は建てかえレベルの改修が必要であるため、また移転先付近にもＳＨＩＰが近くにありまして、連携や効率化を考えますと移転する必要があると結論いたしました。そのため不採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":201,"id":"exchange-059"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そのときに地域の方々の要望を踏まえ、趣旨採択という形で議会としてのそのときの委員の１人としても考えを述べさせていただきました。その結果、区のほうが先ほどご答弁があったような分館をつくり、新図書館や取次施設などの対応をとったということで、地域の方々の要望に対応したことで実現しているということもありますので、移転をするという形で、この請願は不採択ということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":203,"id":"exchange-060"}]},{"id":"topic-05","title":"平成２９年陳情第６号「（仮称）キッズガーデン小山」（小山７丁目）の認可保育園の認可差し止め等を求める陳情","agenda":"平成２９年陳情第６号「（仮称）キッズガーデン小山」（小山７丁目）の認可保育園の認可差し止め等を求める陳情","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"ただ、事実関係を確認させていただきたいと思うのですが、理由の１番のところで近隣住民の７３名が品川区に開設反対の要望を提出しているということ、３番のところで小山７丁目自体の待機児童は少ないということ、４番目のところでこの運営事業者キッズ・スマイル・プロジェクトが川崎市においても補助金の不正請求で係争中だということについて伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"待機児童の状況ですが、当該予定地の１キロメートル圏内において、通学利用範囲と想定している部分ですけれども、平成２９年４月時点の不承諾数は９６人、そのうち５００メートル以内の方は４５名でありまして、保育需要としましては非常に高い地域です。","voiceIndex":212,"id":"exchange-061"},{"speaker":"のだて委員","kind":"質問","question":"この小山と合わせて荏原の地域でも比較的多く待機児童がいたと考えています。そういった中で、満員電車の中を送迎するという話も聞いております。補助金の不正についてはないということですけれども、そうするとこの川崎市で補助金の不正が係争中だということは勘違いだということなのでしょうか。補助金の不正はないということを改めて伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"当事業者は川崎市内にある保育施設の元職員１名から雇用に関して訴訟が起こされておりまして、その件に関しましては昨年と今年の２度にわたりキッズ・スマイル・プロジェクトの社長から直接区に説明がございまして、合わせて書面による説明もいただいております。","voiceIndex":216,"id":"exchange-062"},{"speaker":"のだて委員","kind":"質問・要望","question":"裁判の件については雇用に関してのものだということで、雇用についても今保育園では大変だということですので、そういったところもしっかりと配慮していただきたいと思います。こういった住民の声もまた大切ですので、引き続き住民の方の理解を得られるように努力していただきたいと思いますけれども、いかがでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"事業者からは地域の方が懸念として出された駐輪場の問題でありますとか、納品時の車の問題、ごみの出し方、災害時の対応等、子どもの声や親の声といった騒音等については、よりよい方向に向かうために住民の方と検討会を実施する、継続して実施するという報告を受けております。","voiceIndex":218,"id":"exchange-063"},{"speaker":"のだて委員","kind":"質問・要望","question":"もしこの保育園が開設されたとすると、地域の住民の方との関係も子どもたちの成長・発達に影響を与えると思いますので、良好な関係がつくれるように区としても力を尽くしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":220,"id":"exchange-064"},{"speaker":"こんの委員","kind":"確認","question":"この中で事業者が住民の方へのご説明をということでしたけれども、運営についての説明がなされていなかったというような内容があるのですが、そもそもこういう開設をするに当たって、設置をする事業者が住民の方への説明のときというのは、区としてはどのような立ち位置で、また区としてはどういうふうに説明の場に臨み対処していくというのが本来行われるものなのでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"保育施設の運営に関する地域への説明につきましては保育事業者の努力義務とされておりまして、戸別訪問や説明会など具体的な実施方法や周知範囲について法的な定めはございません。","voiceIndex":222,"id":"exchange-065"},{"speaker":"こんの委員","kind":"質問・要望","question":"決まったルールはないといっても、いわゆるこういうふうに近隣の方から説明を求められて、事業者としての説明がきちんと住民の方へのご納得いく合意を得ていくようなことができない場合は、区としてはどのような対応をしていくのが本来、こういう場合にはどういうふうに対応していくのですか。","respondent":"大澤待機児童対策担当課長","answer":"その後、区民の方から説明会の開催要望が区に参りましたので、区としましてはキッズ・スマイル・プロジェクトおよびＶＩＤＡコーポレーションに対して工事着工は見合わせて説明会を実施するように要請しまして。","voiceIndex":224,"id":"exchange-066"},{"speaker":"こんの委員","kind":"質問・要望","question":"いわゆる住民の方への戸別訪問もしながら、結局説明が欲しいという要望で区が間に入り、きちんと説明会が行われて同席もされたということですから、事業者の住民の方への説明というのがどういうふうに行われ、区としてはどう評価されているでしょうか。その説明の仕方なり、内容なり、住民の方が思ってらっしゃる説明というのは、区として、どうゆう評価をされているのでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"当初、２回の説明会を行って事業者としては２回で説明会を終了する予定だったのですが、説明会の内容に区民の方がご納得していないご様子でしたので、区のほうから継続して説明会をするように指導しております。その時点でもう一度、工事に関しては見合わせていただいております。","voiceIndex":226,"id":"exchange-067"},{"speaker":"こんの委員","kind":"質問","question":"さらに細かいことで恐縮なのですが、そのときに区から業者に指導をして、説明なり話し合いの場を持つように指導されているということですが、その説明会での説明の仕方等で区が口を挟むということは、例えば、その場で説明をするということはあるのでしょうか。いわゆる説明の仕方で、そこはこういうことではないですかというふうに、その説明会の中で区が説明をするという場面はあるのでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"基本的には事業者が説明をする説明会ではありますけれども、例えば先ほどの区内の待機児童の状況ですとか、区が答えるべきご質問に対しましてはお答えをしております。","voiceIndex":228,"id":"exchange-068"},{"speaker":"こんの委員","kind":"質問・要望","question":"今は住民の方とも何とかこの保育園をということで説明会などを行い、さらに住民の方との意見交換というか、検討会というか、そうしたものを継続していくということですので、そうなると区も説明をしながら業者の指導をしながらというところで、要は待機児童対策として認可保育園が必要であるという区の対策と、一方で業者がやはりこの地で保育園を運営させていただきたいという区民の方への説明と。","respondent":"大澤待機児童対策担当課長","answer":"委員おっしゃるとおり、近隣住民の方のお気持ちも大変大切だと認識していますので、この辺は事業者に伝えながら、もちろん調整と言っても事業者としてできないことというのは確かにあるのですけれども、できるだけ住民の方の要望には応えられるように話はしています。","voiceIndex":230,"id":"exchange-069"},{"speaker":"南委員","kind":"質問・要望","question":"区としては待機児童がいる地域だということで、私もそういう点では、保育園ができて待機児解消に１つの地域の状況を受けとめて開設していければいいかなと個人的にはすごく思っているのですけれども、そのあたりの考え方も伺っておきたいのと、一緒に、同時に待機児童が先ほど紹介していただいた数字として、１キロ圏内だと９６人で５００メートル以内で４５人という話ですけれども。","respondent":"大澤待機児童対策担当課長","answer":"事業者としましては近隣の方との検討会の中で妥協点を見出していきたいということを言っておりますので、それは区としても責任を持って確認していきたいと考えています。待機児童につきましては４月時点で２１９人という数字です。車の登園については全園禁止しています。","voiceIndex":233,"id":"exchange-070"},{"speaker":"南委員","kind":"質問・要望","question":"そうすると、先ほど待機児童の部分ですけれども、メモしていないのですけれども二百数十人中、この地域では距離に応じて４５人と９６人がいるという、そういう関係で見ていいということですか。その確認をしたいと思います。その辺について今後の検討会というのも事業者任せにするのではなくて、品川区も入って、ここも含めてどのような姿勢で臨んでいこうと思っておられるのか、その辺を伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"今、説明の方法についてその方法や範囲に国も都も明確な基準は定めていないのですが、今回のこともございまして、今後区としてはやはり説明について一定のルールを明確化して事業者に提示したほうがよいというふうに考えておりますので。","voiceIndex":235,"id":"exchange-071"},{"speaker":"南委員","kind":"質問・要望","question":"ルール化ということについての今の時点での考え方、どのような内容を盛り込もうとしているのか、必要性があってそういうふうにしていきたいという考え方が表明されたわけですから、どういう内容かというのを一定お聞かせいただきたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"説明へのルールですけれども、まだ具体的には検討してございませんけれども、例えばですが説明の範囲を中高層建築物の建築に係る紛争の予防と調整に関する条例に準じて範囲を明確に、この範囲でお願いしたいというふうに出すですとか、戸別訪問等のときに。","voiceIndex":237,"id":"exchange-072"},{"speaker":"南委員","kind":"質問・要望","question":"区がご近所の皆さんへの説明会によるアプローチというか、それについて本当にそこが一番基本だと思うのですよね。しっかりと理解していただけるような姿勢で、まず第一線に立ってやっていただきたいということと合わせて要望をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":239,"id":"exchange-073"},{"speaker":"渡部委員","kind":"質問","question":"今、南委員やこんの委員の質問を聞いていましたので、私もそうなのですけれども要旨にかかわることと言うよりも、やはり説明がどのようにというのは、ここに限らず今後もさまざまな課題がやはりあるのかという意味で聞いていたのですけれども、先ほど課長のご説明の中で、説明会をこういうふうにやって検討会も行うという話を伺いますと、今まで品川区内で業者は、そこまでやってくださっているのか。","respondent":"大澤待機児童対策担当課長","answer":"説明会の回数としては、今まで区内で私が知る限り一番多かったのは５回です。この件に関しましては今後も継続していく形ということですので、恐らく最高回数になるのではないかと考えています。","voiceIndex":240,"id":"exchange-074"},{"speaker":"渡部委員","kind":"質問・要望","question":"多分これは皆意識としては同じで、やはり近隣の地域の方々に愛される施設になってほしいというものであるから、それは最大限の努力を重ねてもらうわけなのだけれども、では、この保育施設に限らずさまざまな行政施設をつくる中で、そうしたら全て要望を聞いていかなければいけないのかと言ったら、やはりすべてではないのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":242,"id":"exchange-075"},{"speaker":"渡部委員","kind":"質問","question":"３番に関しましても今の状況等も伺いましたし、そのほかで理由の中に書かれていることにつきましても今後対策と、私どもも述べさせていただきましたような近隣との対策をこれからどのようにしていくかというのは、毎回の課題となることかもしれませんけれども、そこはまた別の話ですのでしっかりやっていくとして、今回の陳情に関しては不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":245,"id":"exchange-076"},{"speaker":"こんの委員","kind":"確認","question":"今回、これで結論を出すということです。意見というか、先ほども確認をさせていただきましたけれども、今住民の方との十分に協議をしてくださっている、また検討会も開かれるという姿勢、それから事業者としても住民の方との妥協点もその中で見出しているという姿勢も確認ができました。態度としては、結論的には不採択ということになりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":247,"id":"exchange-077"},{"speaker":"南委員","kind":"質問・要望","question":"私どもは今日結論を出していいと思います。私どもはこれをどうしようかと、初めて触れて皆で読んだときに、なかなか本当に率直に申してどうしたらいいのかというふうに悩みました。態度としては、陳情者の皆さんには申しわけないとは思うのですけれども、不採択というふうにしたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":249,"id":"exchange-078"},{"speaker":"松永委員","kind":"意見","question":"本日結論を出す。不採択でお願いいたします。１に関してはやはり認可は東京都が行うということ、２番のキッズ・スマイル・プロジェクトに関しても、そういった不正請求等はないということで、先ほど課長からご説明いただきまして、３番に関しても今後説明会を丁寧に行っていくということもありましたことを踏まえ、私たちの会派は、今回の陳情に関しては不採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":251,"id":"exchange-079"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"結論を出すということで、不採択です。陳情の要旨のところで説明していただきましたが、１番は権限の問題、認可の問題については理解しました。今後もやはりこういった問題では調整、言葉はあれですけれども利害関係をどう調整していくかと非常に難しい問題ですが、ぜひとも先ほどお話があったような意気込みで相互の理解を得てよりよい関係に努力していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":253,"id":"exchange-080"}]},{"id":"topic-06","title":"平成２９年陳情第９号 保育所職員に対しての処遇改善に関する陳情","agenda":"平成２９年陳情第９号 保育所職員に対しての処遇改善に関する陳情","exchanges":[{"speaker":"南委員","kind":"確認","question":"それと賃金のところも、今の状況では１０万円ほどの賃金の格差があると言われておりますけれども、平成２７年度には３万８,０００円で、平成２９年度にはいろいろプラスされてそれを超える額となっているのですが、しかしまだまだ実質的には賃金格差があると言えるのではないかと思っているのですけれども、その辺の認識はいかがですか。","respondent":"大澤待機児童対策担当課長","answer":"保育士の確保ですけれども、新規園につきましても保育士が集まらなくて開園できないということもございませんし、平成２９年度、今の年度途中でも突然足りなくなって困ったというようなこともございませんので、一定確保ができていると理解しております。","voiceIndex":261,"id":"exchange-081"},{"speaker":"南委員","kind":"質問・要望","question":"再確認をしたいと思います。５対１ですから職員が４人ですね。ですから、５対１で基準どおりだからいいということにはならないわけです。そういう事実を、現実をやはりきちんと見て、基準だからいいのだというふうには、私はそういう見方を担当のところではしていただきたくないと思っているのですけれども、５対１としているからいいという認識でいらっしゃるのかどうか、ここについても伺いたいと思います。","respondent":"大澤待機児童対策担当課長、佐藤保育課長","answer":"それよりも宿舎の借り上げのほうがかなり効果があるというふうに事業者からのヒアリングで聞いておりまして、宿舎借り上げ支援につきましては品川区はかなり柔軟に対応しておりますので、こちらの活用が増えていくような状況です。区といたしましては一応７２７名の保育士を配置しておりまして、それ以外にも７００名近い非常勤を配置していますので、特別支援児等も増えている関係もありますけれども、保育士等。","voiceIndex":263,"id":"exchange-082"},{"speaker":"南委員","kind":"質問・要望","question":"年齢や時期によって、入園時期などの時期はそれぞれで違うけれども、それなりに子どもも育っていますので、必要な手というのは多ければ多いほどいいわけですし、子どもにとっても保育園に喜んで来てもらう、登園してもらって安心して育っていただくという条件整備は欠かせない最低限の条件ですから、この５対１のことを思ってよしというふうにはできないという見解で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":266,"id":"exchange-083"},{"speaker":"こんの委員","kind":"質問","question":"趣旨の１番ですね。先ほどの、区としても国の公定価格で加算をしていますというお話と、平成２９年度の処遇改善、キャリアアップ、経験年数等々でいわゆる賃金アップの対策をとっていますよというご説明をいただきました。改善はされているのですが、それはどのように、いわゆる、これだけ区としてはしているけれども実感がないということについて区としてどのように捉えていらっしゃいますか。","respondent":"大澤待機児童対策担当課長","answer":"賃金に関しては経験年数等でも違ってくるので一概には言えないのですが、一番わかりやすいのが初任給だと思うのですけれども、平成２８年４月の初任給は平均で出したところ１９万５,０００円だったのですが。","voiceIndex":268,"id":"exchange-084"},{"speaker":"こんの委員","kind":"質問・要望","question":"は２番は既にもう５対１になっているということですので、これは私立保育園が開設をするときに国基準では６対１だけれども品川区では５対１ですと、職員の人数としては国基準よりも多めに配置をしていただきたいというふうになりますけれども、そのことはご理解のうえ、私立保育園などは運営してくださっているという理解でいいのでしょうか。その点はいかがでしょう。","respondent":"大澤待機児童対策担当課長","answer":"５対１につきましても新規開設のご提案があった時点で区としてはこの体制でやっていただきたいということでお願いして、全事業者がそれでやっていただいております。","voiceIndex":270,"id":"exchange-085"},{"speaker":"こんの委員","kind":"質問・要望","question":"調査はそうしたことでしてくださっているということで、引き続きお願いをして、５対１のほうはいろいろな、ここに書かれている保育の生活の中での１歳児の動きというのも想像できますので、保育士の方が子どもを安心して、見ていける体制というのは、人数だけの問題ではないものもあると思いますので、合わせてその点もお願いをしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":272,"id":"exchange-086"},{"speaker":"のだて委員","kind":"質問","question":"今の議論の中では認可の話が主だったと思うのですけれども、小規模ですとか認証の配置というのも５対１ということになっているのか、そのあたりもお伺いしたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"平成２９年度のキャリアアップ補助金が２万１,０００円、処遇改善が６,０００円で、それまでの平成２７年度、平成２８年度のキャリアアップが２万３,０００円、処遇改善が２万４,０００円ですので、それを足して７万４,０００円になります。","voiceIndex":274,"id":"exchange-087"},{"speaker":"のだて委員","kind":"質問・要望","question":"小規模のことなのですが、お答えの中で認証についての基準がやはり認可では５対１になっているということで、認証や小規模についても上げていく必要があるかと思うのですけれども、そのお考えをぜひ、都や国にも求めていただきたいと思いますし、区独自でもやっていただきたいと思うのですけれども、伺いたいと思います。７万４,０００円のところは計算上はわかりました。","respondent":"大澤待機児童対策担当課長","answer":"調査につきましては認可、小規模、認証の全園を対象に実施しております。認証の配置につきましては、認証保育所そのものは東京都の施策ですので、区として配置基準を変えるというのは今のところ考えてはおりません。","voiceIndex":276,"id":"exchange-088"},{"speaker":"のだて委員","kind":"質問","question":"それは制度上もできないということになるのですか。これは都が担当という話ですが、何か工夫してできるという余地はあるのか伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"認証の配置基準について区で制度変更できるかどうか、今わかりませんけれども、恐らくできないと考えております。","voiceIndex":278,"id":"exchange-089"},{"speaker":"のだて委員","kind":"質問・要望","question":"わからないけれどもできないということでしたが、やはり皆品川区の子どもたちであるわけで、認可、認証での保育の格差と言いましょうか、差が出てきているということになると思うのです。そういったところでやはりいいところに引き上げていくということが必要だと思うので、認証についてもぜひ引き上げていくというところを考えて検討していただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":280,"id":"exchange-090"},{"speaker":"渡部委員","kind":"意見","question":"２番は品川区は５対１でもうずっとやってきていますから、なぜ陳情として提出されてきているのかわからないと思っていたのですけれども、１番に関しましても説明いただいたようにここ数年来さまざまな処遇改善をされていまして、ただ、私どものほうにはこれに近い、これではない職場の方が、他も何とかしてくれないと離職が相次いで大変だという話が入ってきているような現状もありますし。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":285,"id":"exchange-091"},{"speaker":"こんの委員","kind":"質問・要望","question":"態度は、先ほどご説明をいただきまして、１番はきちんと処遇改善、キャリアアップや経験年数の賃金アップの努力もされていますし、それに対して職員の方にどのようにお金が流れているのかのチェックもきちんとしてくださっていることがわかりました。２番はもう既にされているということですので、残念ながらこのご要望は全て区としてはかなえているということの理解でありますので、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":287,"id":"exchange-092"},{"speaker":"南委員","kind":"意見","question":"結論を出していいと思います。態度は採択をしたいと考えています。１番の処遇改善の大きなところは賃金です。それから２番の人員の配置基準なのですけれども、５対１は都基準なのですけれども、やはり最低基準を見てもっと引き上げは必要です。したがって、これらの陳情内容については支持できる内容だと思いますので、採択をしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":289,"id":"exchange-093"},{"speaker":"松永委員","kind":"意見","question":"本日結論を出す。我が会派で話し合った結果、不採択にします。１番に関しては区独自の賃金加算ということでキャリアアップや宿舎借り上げなどの対策を行っているというところです。２番に関しても６対１から引き上げてくださいということで、今品川区では５対１で行っているということで、そうした理由から不採択をします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":291,"id":"exchange-094"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１番はさまざまな賃金加算などをされていることも伺いました。それから、先ほどの調査のことがありましたけれども、やはり事業者に対する行政としてのチェックはこの委員会で質問させていただきましたけれども、人件費の割合等も含めて、運営費等の使い道等については引き続き目を緩めないでいただきたいと思います。２番のほうは５対１でされているということで、了解をいたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":293,"id":"exchange-095"}]},{"id":"topic-07","title":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、文教委員会にかかわる項目","agenda":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、文教委員会にかかわる項目","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"飯沼議員の保育の質問のところで、待機児ゼロに平成３０年度４月でなる見通しができつつあるというお話だったので、それについて具体的に教えていただきたいと思います。認可保育園が何園できて、他のものについてもどのくらいできて、需要見込みが幾つでどのようになりますというところを教えていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":298,"id":"exchange-096"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4922#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":64497,"voices":301}},{"id":"h29-20170925-5","meetingId":"h29-cm09","date":"2017年9月25日","dateIso":"2017-09-25","committee":"総務委員会","time":"午前１０時００分～午後 ２時３２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を61件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"視察","agenda":"視察","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"第６５号議案のほうから順番にお聞きしたいと思います。１０ページ・１１ページのところに図面が描かれているのですけれども、工事内容のところで、最近屋上プールの設置が多くなっていると思うのですけれども、工事の費用の関係で、上につくる部分と従来の土地のところにつくるあたりの違いがどのくらいあるのか教えてください。ここの校庭は人工芝ではないのですか。そこをよろしくお願いします。","respondent":"小林施設整備課長","answer":"それとあと人工芝について。今回契約にかけているのは校舎のほうの建物の部分のみです。それで、グラウンドについては今計画をしておりますので、また解体と一緒になるかと思いますけれども、今後になると思います。今検討中です。","voiceIndex":7,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"すごく細長い校舎というところで、入口と子どもの動線がどうなのかなというところが一つ気になったのと、やはり工事をするにあたって結構奥まっているなというところで、ぜひ工事車両の出入りのところを気をつけていただきたいのと、あと、今日伺ったら、旧東海道の石畳のきれいな舗装がされているので、そこのところをかなり工事車両が行ったり来たりというところにおいて。","respondent":"小林施設整備課長、篠田学校計画担当課長","answer":"それと３点目の児童の動線ですが、建設工事中は皆さんが今日通った旧道のところは工事専用とし、児童は北門から入れさせておりますので、工事中はそういうラップをなるべく避けて計画をしておりますので。特別支援教室ですけれども、３階に普通教室が並んでいるところの中で１教室使うという形になります。それから、改築後の動線ですけれども、小学校は正門を入りまして２階に上がった形で昇降口があるという形になります。","voiceIndex":9,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２１ページのところに「太陽光発電設備」とありますけれども、ぜひ新しい施設に関してはエコを重視して取り組んでいただきたいと思うのですが、ここの太陽光発電のところもどのような設備がどこにつくのか、ちょっと具体的に教えてください。","respondent":"小林施設整備課長","answer":"太陽光につきましては、今のは電気のほうなのですけれども、これは屋上に１０キロワット程度の発電能力のソーラーパネルを設置する予定です。","voiceIndex":12,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この太陽熱利用設備というのは屋上の温水シャワーということで、とても歓迎するのですけれども、これは今回初めて設置されるものなのか、今までもどこかで設置されていたのかどうか、費用がどのくらいかかるのか、わかったら教えていただきたいと思います。給食の調理室も地下１階というところではいろいろ配慮が必要かと思うので、その辺がどのように対策がとられているのか、お聞かせください。","respondent":"小林施設整備課長","answer":"それとあと、非常用発電を今回この城南小学校でも設置をしますので、７２時間の稼働に耐えられる燃料も保管をします。","voiceIndex":14,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"太陽熱給湯のところですが、プールの比較的近いところに設置をすれば、配管とか云々かんぬんで、そう費用もかさまないということで、これからあちこち改修がありますし、既存のところもやはり冷たいシャワーで子どもがびくっとするのではなくて、温水にしてほしいという希望もあるので、やはりそういうよいところはぜひほかにも活かしてほしいと思ってちょっとお聞きしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"総金額ですが、約４９億円ということで、幼稚園園舎が一緒に入るということなのですが、かなりやはり高いのかなと。そして、今日、視察現場で埋蔵文化財発掘をやっていましたが、あの費用というのは別の課から出ているでしょうか。その辺をちょっとお聞かせください。","respondent":"篠田学校計画担当課長","answer":"埋蔵文化財の経費ですけれども、こちらは教育委員会の予算のほうで実施しているものです。","voiceIndex":17,"id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"もう一点お聞かせいただきたい。ちょっと見解をお聞きしたいのですけれども、今、私立小学校、中学校もそうなのですが、この間ちょっと中学生に聞いたら、私立は体育館にエアコンがついている。今、小山小学校などもそうですが、そういう体育館、これから新築する学校、校舎等に対して、やはりエアコンは、あくまで今後も区としては導入をしない方向で行くのでしょうか、お聞かせください。","respondent":"篠田学校計画担当課長","answer":"ですので、今後状況に応じまして、場合によってはそういう対応をとれるようにということで、今行っているところです。","voiceIndex":19,"id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"品川区はやはり教育が本当に進んで先端を行っていると思うのですが、やはりこういう子どもたちのことを考えて、また地域の人のことを考えて、やはりそれなりの準備、また設備というのを整えていただきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"今日、現場で渡された資料を見ますとコンセプトが書かれていて、それぞれとても賛同したいコンセプトなのですけれども、その中で環境にやさしく災害に強い学校づくりというのがありまして、先ほど太陽熱利用とか太陽光発電のことはご説明いただいて、それは資料のほうにも出ているのですけれども、品川区の今の環境計画の中では雨水利用も結構進めていて、この前環境課に確認させていただいた時点では。","respondent":"小林施設整備課長、篠田学校計画担当課長","answer":"１点目の雨水利用ですけれども、これは外構のほうで雨水タンクを設ける予定で計画をしております。それと屋上の緑化ですけれども、これは構造の負担はないことはないと思います。屋上につくるわけですから。こちらのほうと、あとは通常の昇降口とありますので、３方向で外に出られるような形での設計となっています。","voiceIndex":22,"id":"exchange-009"},{"speaker":"吉田委員","kind":"質問","question":"もう一点、さっき伺えばよかったのですけれども、環境にやさしく災害に強い学校づくりというところでは、いろいろ工夫されている今の屋上緑化のこととか、太陽熱利用とか、太陽光発電というのを、園児や児童が体感できる施設として、地域の環境教育の発信拠点としての先導的な役割を果たすエコスクールとして整備しますとなっておりまして。","respondent":"小林施設整備課長","answer":"それを見ても当然わかりません。委員のおっしゃるとおり、１階だとか昇降口だとかいうところにパネルで、今電気どのくらい発電していますよ、どのくらい消費していますよというような装置・パネルを設置して、見える化を図っております。","voiceIndex":25,"id":"exchange-010"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"何点か質問します。いつも議会から要望しても、「いや、設置をしないのです」というような話ですけれども、何をそれほど拒んでいるのかなと。もう時代がこういう時代の中で、一定の必要性を我々議会としても感じていますし、地域の方たちも、特に災害時のことも心配をしてそういうような要望を常に出されているのかなと思うのですけれども、なぜそこまでかたくなに体育館への冷暖房を設置しないのか。","respondent":"篠田学校計画担当課長、小林施設整備課長","answer":"今回城南小学校に関しましても、計画段階におきまして、現状が１２学級で対応しているところなのですけれども、湾岸地区の開発等が進んでいるということで、各学年３クラスの１８クラスを今設定しています。ちょっと補足します。今の備蓄倉庫なのですけれども、地下１階に約４０m2ほどの倉庫を現在計画しております。","voiceIndex":27,"id":"exchange-011"},{"speaker":"石田（し）委員","kind":"提案","question":"プラス、プール等が学校には設置されるので、できたら、災害時に言われているのが１つは冷暖房の件ですけれども、もう一つ言われているのはやはりお風呂の課題があるのかなと思うので、以前にも提案をしていますけれども、そういったプールのところに例えば温水のシャワーを設置しておいて、災害時でも若干活用ができるようなつくりに、これは学校というだけではなくて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":30,"id":"exchange-012"},{"speaker":"吉田委員","kind":"確認","question":"先ほど確認すればよかったのですけれども、先ほど城南小学校のあたりは地下で水が出るとおっしゃっていたかと思います。結構水が出るところに地下をつくるということは、一応の対策はしても、実際稼働させてみると何か結構かびの被害が出たりということを私自身も経験していますので、その辺どうなのか教えてください。","respondent":"小林施設整備課長","answer":"給食室については空調換気、外の新鮮な空気を入れて、それを循環させて、湿気をなるべく外に持っていくというような空調をつけたりだとかして、検討して設計を今回進めたところです。","voiceIndex":31,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"すみません、１点。先ほど途中でした。特別支援教室なので、障害を持ったお子さん等が通ってくる、教室から移ってくるという意味においては、この横長のずらっと教室が並んでいる動線の中で、できるだけ真ん中にしてほしいという希望が結構出ているのです。だから、もうこの段階なのですけれども、その辺が具体化されているのかどうか、１点お伺いします。","respondent":"篠田学校計画担当課長","answer":"特別支援教室に関しましては、まず教室の仕様は普通教室と同じものという形で考えてあります。","voiceIndex":33,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問","question":"ぜひ動線を考えて、中央に配置をしていただけたらと思うのが１点です。もう一点、車椅子利用の児童の方のためのルートはどうなのかなという説明をしてください。エレベーターはあるのですけれども、その辺のバリアフリーの考え方を教えてください。","respondent":"篠田学校計画担当課長","answer":"車椅子の児童に関しましては、一般のお子様に関しましては正門を入ってから階段を上がって２階の昇降口という形になりますけれども、その昇降口がある２階のバルコニーといったところがあるのですけれども、その下の部分に入口をつくりまして。","voiceIndex":35,"id":"exchange-015"},{"speaker":"あくつ副委員長","kind":"質問","question":"それで、予定価格が４９億３,０００万円余でかなり大型の工事であるにもかかわらず、１者入札になっているということについての区の見解と、もう１点だけ、１４ページのほうの給排水衛生設備工事のほうですけれども、一番下の４番目のところのＪＶが結果として「無効」となっているのですけれども、この無効の理由を教えてください。","respondent":"立川経理課長","answer":"８ページの入札状況ですけれども、３者申し込みがありまして、実際の札が入ったのが１者です。辞退理由ですけれども、１者が都合によるということでございまして、もう一者が予定価格を超過しているです。","voiceIndex":39,"id":"exchange-016"}]},{"id":"topic-02","title":"第６９号議案 天王洲公園ＡＢ面他改修工事請負契約","agenda":"第６９号議案 天王洲公園ＡＢ面他改修工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"１点だけなのですが、昨今天王洲の天王洲公園運動場が、非常に使用頻度が高くなったのかなというのを感じます。そういう意味で、駐車スペースというのはもう少し何か工夫できないのかと思うことがあるのですが、いかがでしょうか。ちょっとご見解をお聞かせください。","respondent":"溝口公園課長","answer":"そういった中で駐車場ですが、やはりこれだけの運動施設を維持しながら、新たに駐車場を整備していくというのはなかなか難しいのが現状です。","voiceIndex":78,"id":"exchange-017"},{"speaker":"須貝委員","kind":"質問・要望","question":"あそこはなかなかいい場所で、お子さんたち、家族連れが散策するというところで、天王洲が日曜祭日などなかなか賑わっているような状況になってまことにうれしい限りなので、何かいい方法がありましたら、ぜひご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問","question":"運動するのだけれども、芝生の上が暑いというので、ああ、そうなのかなと、場所によって違うのかなという思いがしたのですけれども、その辺、工事の仕方とかいろいろな工夫があるのかと思うのですが、ちょっとその辺の平米単価が幾らぐらいで計算されているのか、またそういう選択肢があるのかどうか、排水の状況とかも含めて選択肢がどのくらいあるのか。","respondent":"溝口公園課長","answer":"これにつきましてはグレードとしてはかなりいいもの、通常よりも高級なものを使って、大体平米単価でいくと１万円前後のものを入れるような形で考えておりまして、使用実績におきましては神宮球場とか、そういうプロの野球場でも使われているような人工芝を入れることによって。","voiceIndex":81,"id":"exchange-019"},{"speaker":"吉田委員","kind":"質問","question":"先ほども人工芝のことが出ましたけれども、今、老朽化に伴いというようなことでしたが、今までの人工芝よりもグレードを上げたと理解してよろしいのでしょうか。どれぐらいでまた張り替えの必要性が出てくると考えられたのか、その辺の見込み、計画があれば伺いたいと思います。","respondent":"溝口公園課長","answer":"今回のＡＢ面につきましては、人工芝が設置されてから１５年以上経過しているということで、人工芝の種類によってもいろいろ変わってきますし、使い方によってもいろいろ耐用年数は変わってくると考えております。","voiceIndex":85,"id":"exchange-020"},{"speaker":"吉田委員","kind":"質問","question":"もう１個、この透水性ＩＬＢ舗装が２７m2と、図面で見るとここだけということなのですが、これはどういうもので、どういう目的でこういう舗装をここだけするのか教えてください。","respondent":"溝口公園課長","answer":"今回のＩＬＢ舗装につきましては、部分的に傷んでいるところ、またベンチ等そういったものを今回新たにスタンドベンチを設置するところも出てきている現状ですので、それを復旧するところだけをＩＬＢ舗装として直すということで。","voiceIndex":87,"id":"exchange-021"}]},{"id":"topic-03","title":"第７０号議案 書架・カウンター等の買入れ","agenda":"第７０号議案 書架・カウンター等の買入れ","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"書架でも今いろいろな書架がありますね。電動式で検索できるようなものもあるので、カウンターは大体イメージがわくのですけれども、どの程度の規模か書架について教えていただきたいのが１点です。これは北品川に移転をするためといった理由なのですけれども、大崎図書館の移転に伴っての大崎の取次所とか、あと芳水小学校の分館についてはここに含まれているのか、いないのか、教えてください。","respondent":"立川経理課長","answer":"書架について説明いたします。書架には複式書架と単式書架がございまして、今回複式書架については７段の８連のものと、７段７連、また４段６連。単式につきましては７段６連、３段９連。","voiceIndex":103,"id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問","question":"新大崎図書館の部分の設備だというのはわかりましたけれども、ちょっとイメージがわかないので、既存のところでいうとこの程度という規模があったら教えてほしいのです。それと、フロア的にはどのようになっているのか。１フロアなのか、２階とか３階とかいう構造になっているのか。それによっても、書架はかなり違ってくると思うのですね。特別な新しいタイプの書架ではないということなのですか。","respondent":"立川経理課長","answer":"イメージとしましては、１フロア１,５００m2、そうした中に書架を配置していくです。","voiceIndex":105,"id":"exchange-023"},{"speaker":"石田（し）委員","kind":"質問","question":"２７ページのところで、製品選定経過のところでは、いわゆる機能的で利用しやすいものということで考慮して選定されたとなっているのですが、これはそうはなっているのですが、普通に入札というのは予定価格があって、入札をされた方の中で一番安いところが落札をされると思うのですが、カウンター等では機能的で利用しやすいものを考慮し選定したというのと、例えばその金額が高くても。","respondent":"立川経理課長","answer":"書架なら何でもいいというわけではございませんで、いわゆる新しい図書館のレイアウトに合わせて、もう既に製品を選定した上で棚割りというのを確定します。ですから、入札に際しましては全てメーカーとかを特定した段階で、それで金額勝負してもらうです。","voiceIndex":107,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ちょっと一言申し添えます。なぜなら、大崎図書館を現地でそのまま残してほしい。老朽化しているのだったら改修をしてほしい。ですけれども、北品川の地域に新しい保育園を求める意見がたくさんあるのと、本予算においては芳水小学校の分館の問題とか取次とかのほうの予算は入っていないと、新しいところの予算であるということで、新設、充実をするといった意味で、この議案に対して賛成をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":113,"id":"exchange-025"},{"speaker":"吉田委員","kind":"意見","question":"ネットも、大崎図書館の移転については手続き的にそもそももう少ししっかり地域の人たちの意見を聞いて、手順を踏むべきだということで、疑問を持っております。ただ、これについては、新しくできるところについては特にこれ自体に問題はないと考えていますので、その点については賛成したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":116,"id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"人件費についてなのですけれども、様々な職種の方がかかわっているわけですけれども、この積算をしていく段階で、最低賃金のところがきちんと保証されているといった根拠というのは、区はどのように把握をされているのか、１点教えていただきたいと思います。","respondent":"立川経理課長","answer":"予定価格を算出するに際しましては、国が示します設計労務単価の最新のものをまず確認いたします。それから東京都の積算基準もありますので、予定価格につきましては、国・都が示しました労務単価に沿って適正な価格ということで決まっているところです。","voiceIndex":122,"id":"exchange-027"},{"speaker":"飯沼委員","kind":"確認","question":"当然のことと思うのですが、そこの根拠はそうなのですが、区としてどこの段階でその辺がきちんと価格を積算するところで使われているか。法令遵守もそうだし、赤本のところに書かれているとおりですという、そこのチェックというのは、区も同じことをやって確認して正しいと評価をするのか、どこで事業者が出しているものが妥当であるという評価をするのか、そこのところを教えてください。","respondent":"立川経理課長","answer":"入札に際しましては、いわゆる積算の内訳というものを出していただいておりますので、当然その辺をチェックしまして、いわゆる労働者の賃金、下請けの支払いにつきまして適正であるかどうかというのを事前にチェックしています。","voiceIndex":124,"id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"そこで、１つここに書かれている会社が直接する部分ではなくて、一次、二次、三次とか下請けに出す場合の最低保証のところは、どこでどう把握するのかも教えてください。","respondent":"立川経理課長","answer":"下請けがある契約につきましては、いわゆる工事全体の施工体制台帳というものを出していただきまして、そこでそれぞれ下請契約の金額等をこちらに提出していただいておりますので、当然その積算についてもチェックしています。","voiceIndex":126,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"手続き上はきちんとされていると思います。どこでもそうなのですけれども、最終的にそこで本当に汗を流して働いている労働者の方々に、実際に賃金のところも労働環境もそうですが、きちんと行っているかどうかというチェックを、やはり事業者任せではなくて区のほうでしていただくような仕組みにしてほしいと思っています。その点一つ答えていただきたい。","respondent":"立川経理課長、松山高齢者地域支援課長","answer":"今後につきましては、契約制度の中でどういった工夫ができるのか、そういうことにつきましては当然研究していかなくてはいけない課題と考えております。委員お尋ねの一般区民の利用料についてですが、こちらの施設の位置づけについて、今検討を図っているところですので、また利用料につきましては、決定次第お示しさせていただこうと考えています。","voiceIndex":128,"id":"exchange-030"},{"speaker":"須貝委員","kind":"質問","question":"ちょっとお伺いしたいのですが、入札金額、先ほどのもあったのですが、今回２億７,８２６万２,０００円というのが予定価格で、落札が２億７,８１０万円。それは１番目の方が落札された。何か非常に違和感を覚えるのですが、これはどういうふうに我々などが理解すればいいのでしょうか。全く同じ額もあるというのは何か不思議な気がするのですが、これに対して我々はどのように思ったらいいのでしょうか。","respondent":"立川経理課長","answer":"接近している理由ですけれども、いわゆるあらかじめ設計図書を公表しておりますので、どういった工種でどういう人工が要るかといったところについては、事業者側のほうでも細かく積算ができるようになっておりますので、そうした積算に使うソフトが同じだった場合には。","voiceIndex":131,"id":"exchange-031"},{"speaker":"須貝委員","kind":"質問","question":"ちょっと１点だけ。以前も聞いたことがあるのですが、区としてはこの予定価格を出すにあたって、どのように積算して、入札予定価格を決めているのですか。ちょっとそれだけお聞かせください。","respondent":"立川経理課長","answer":"予定価格につきましては設計事務所が設計をして、そこで金額をある程度出しています。","voiceIndex":133,"id":"exchange-032"},{"speaker":"須貝委員","kind":"意見","question":"最後に１点だけ。先ほどのもそうなのですが、最近すごく金額が、今お話を受けたとおり接近している。資本金がかなり違っても同じだというのは、一般の区民から見ても非常に違和感を覚えますので、それだけちょっと一言言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":135,"id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"この図面で、だれでもトイレが１階と２階にあるのですけれども、例えばだれでもトイレといってもいろいろな仕様があると思うのですが、私たちはいろいろな場面でユニバーサルベッドを求めているのですけれども、そういう設備があるのかどうかということが１つです。","respondent":"小林施設整備課長","answer":"だれでもトイレの備品関係のお話ですけれども、ここについては委員のおっしゃった多目的シートについては設置をする予定です。ほかにオストメイト、洗面所、あとベビーチェア等を設置する予定です。","voiceIndex":136,"id":"exchange-034"},{"speaker":"吉田委員","kind":"質問","question":"１階のテラスはそこから出られる窓ということですよね。一般的に掃出し窓というか、そういう感じに理解してよろしいでしょうか。","respondent":"小林施設整備課長","answer":"はい、そのとおりです。","voiceIndex":138,"id":"exchange-035"},{"speaker":"高橋（伸）委員","kind":"確認","question":"すみません。契約以外のことで、施工面のことでお聞きしたいのですが、４ページの５番のところに関連別途工事というところで、電気設備工事が入っているのですけれども、６ページの図面を見ますと、東立面図と西立面図のところの屋上に、おそらくこれはソーラーパネルだと思うのですけれども、これはソーラーパネルなのかどうか、確認させてください。","respondent":"小林施設整備課長","answer":"別途電気工事の中で、屋上にソーラーパネルの設置を予定しております。","voiceIndex":140,"id":"exchange-036"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうすると、これ、ソーラーパネルは建物の中のどの部分にソーラーパネルによる電気供給をするのか。わかる範囲で結構ですので教えてください。","respondent":"小林施設整備課長","answer":"通常ソーラーパネルを設置しますと、電気照明の補助等に使っておるところが一般的です。","voiceIndex":142,"id":"exchange-037"}]},{"id":"topic-04","title":"平成２９年請願第６号 固定資産税及び都市計画税の軽減措置の継続","agenda":"平成２９年請願第６号 固定資産税及び都市計画税の軽減措置の継続","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"一言だけ。こうやって小規模住宅用地、また商業地等あるのですが、都市計画税、固定資産税が減額されて多くの方が助かっております。毎年このように意見書を出していますけれども、何とか恒久的になるような方向がとれればいいと思います。意見だけ言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":158,"id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問","question":"雇用の不安の拡大、金融事情の悪化、後継者不足など、様々な危機にさらされていますといった訴えは本当に全くそのとおりで、同感をする中身だと思っていますけれども、小規模住宅用地にしても、小規模非住宅用地にしても、またあと商業地等の固定資産税、都市計画税のところにおいても、それぞれ昭和６３年度に創設されたり、平成１４年度、平成１７年度に創設されて現在に至っているわけですけれども。","respondent":"伊東税務課長","answer":"マクロ経済の認識ですけれども、この土地の関係で申し上げれば、先日１月とか４月時点の調査によりますと、地価のほうは若干上昇傾向にあるというような調査結果があります。","voiceIndex":159,"id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問・要望","question":"東京都のほうはどのような判断をされるか、区がそこをいろいろ言うところではないとは思いますけれども、やはりこういった多くの方々から出されていること、特に中小、小規模の事業者の方々には本当に厳しい中頑張っていただきたいというところにおいては、この願いを届ける機会ではあるのかと受けとめました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":161,"id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問・要望","question":"わかる範囲でいいのですが、職場とどのくらい非正規職員がいらっしゃるかその人数、漠然としているので、職場によって多い順に１位から５位ぐらいまで、非常勤の方が多いところを順番に、職場とどのくらいの人数がいらっしゃるのか教えていただきたいと思います。それぞれどのような職種の方がいらっしゃるのか、わかったら教えてください。やはりこの辺がわからないので、ぜひお願いいたします。","respondent":"黒田人事課長","answer":"次に多いところですと、保育園のいわゆる園医、お医者さんが８７人とか、あと教育ですと教育支援相談員が２４名ですとか、学校の専科の指導員が３５名など、そのようなところが多いです。","voiceIndex":177,"id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問","question":"それぞれの職場はわかったのですが、職種はどのような職種なのでしょうか。","respondent":"黒田人事課長","answer":"職種と申しますか、専門職員につきましては任用基準を定めてございまして、先ほど申し上げた例えば園医はお医者さんでないといけませんので、ドクターであるということになりますし、請願の中にあります例えば戸籍関係ということであれば戸籍等相談員で、戸籍法。","voiceIndex":179,"id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問","question":"正規職員と非正規職員の労働条件の違いとか、賃金格差についてどのくらいなのか知りたいのですけれども、正規職員とほとんど同じ仕事をしていて、均等待遇の対象者になってよい立場の人は何％ぐらいいるのですか。それが１点です。専門非常勤は１,４００円、一般非常勤が１,１４０円で、１０年間据え置きでいる理由がわからないのですが、その理由を教えてください。","respondent":"黒田人事課長","answer":"時給の設定の考え方ですが、先ほどのいわゆる給与勧告については一貫してマイナスだということを申し上げましたが、現在の一般職員の１類、３類、いわゆる事務の職員の基本給を時給に割り返しますと、勤務時間が７時間４５分で週３８時間４５分で５２週というところから。","voiceIndex":181,"id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"待遇のところで、労働条件の違い、正規職員と非正規職員が決定的に違うのはどの辺か教えていただきたいのと、例えば今回最低１,５００円以上にすることを求めると書かれているのですが、それを１,５００円に引き上げたら区の負担はどのくらい増えるのか、計算をされたことがおありだったら、どの程度増やせば大事な仕事をしていらっしゃる方の賃金が引き上がるのかなというところが知りたいので。","respondent":"黒田人事課長","answer":"いわゆる労働条件というのは時間だけではなくて、いわゆる常勤職員ですと職務の計画を立てたりとか、いわゆる時間には換算できない仕事も担っているという意味では、同じ労働条件というのはなかなか比較は難しかろうと考えているものであります。","voiceIndex":183,"id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問","question":"なかなか仕事の中身が時間では言えないという、それは専門的なところを担っている正規職員ならではのところは当然あると思うのですが、正規職員と大体同じぐらいの時間数を働いている方々は、この１,３００人のうちどのくらいいらっしゃるのでしょうか。","respondent":"黒田人事課長","answer":"先ほどの答弁を少し繰り返しますが、同じぐらい働いている方はいないというものです。","voiceIndex":185,"id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２０１５年度の退職者が１６９人のところ、２０１６年の新規採用が１２１人なのですね。マイナス４８人なのです。お伺いすると、経験の長い方が辞められて新規採用になっているので、人件費が安くなっていると多分そうおっしゃると思うのですけれども、それだったらよりその経験者が退職された後の穴埋めを一生懸命やっている部分に、やはり還元をするべきであると思うのですが、その辺はいかがでしょうか。","respondent":"黒田人事課長","answer":"そういった意味で退職者のことですが、退職しても、今、再任用フルタイムということでそのまま残っていただいて、経験を若い職員に伝えるということもしていますので、そういった中で正規職員と非常勤職員の役割分担で業務を担っていると認識しているものです。","voiceIndex":189,"id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問","question":"今、数字のところ、私は２０１６年で示したのです。人事課長は２９年、今年のを言いましたが、今年のは確定していないですよね。退職者と新規の差はどうなのですか。去年と比べて人を採用していますというのではなくて、退職した分、採用がされているのかどうかというのを私は今ここで述べたので、比較するのだったら同じように比較してください。","respondent":"黒田人事課長","answer":"退職の人数につきましては手元に数字がございませんが、基本的には事務事業見直しをしまして、そこに必要な人数を採用しているですし、そういった中でいろいろ工夫を図って事業を執行しているというものです。","voiceIndex":191,"id":"exchange-047"},{"speaker":"吉田委員","kind":"質問","question":"私もこの請願をいただいて、ちょっと自分で知識が足りないものですから、今のご説明に加えて伺いたいのですけれども、例えばこの請願の中で、非常勤職員の職は専門性が高くということで、先ほど幾つか事例で戸籍のこととか、保育のことがございましたけれども、請願の中に学校事務非常勤職員というのも出ています。","respondent":"黒田人事課長","answer":"いわゆる学校事務につきましては、いわゆる都の職員が学校事務でおりますので、区の関係につきましては非常勤職員を置いて、学校のそういった事務を行うということで、平成２９年４月１日現在で５２名ほどいらっしゃいます。","voiceIndex":193,"id":"exchange-048"},{"speaker":"吉田委員","kind":"質問","question":"それともう一つ、非常勤職員が１年ごとの採用ということですが、現実問題としてその１年ごとの採用を繰り返しながら、継続して働いている方がいらっしゃると思うのですが、その割合を教えていただけますか。どう聞けばいいですかね。例えば５年以上継続している人とか、そういうのがわかりますか。","respondent":"黒田人事課長","answer":"基本的に任用は１年ごとですので、繰り返し任用しているというところについては把握してございませんので、お尋ねの件についてはちょっとこちらでは承知していないです。","voiceIndex":195,"id":"exchange-049"},{"speaker":"須貝委員","kind":"質問・要望","question":"今回、請願の趣旨は本当によくわかります。倒産したら、もちろん働く人は失業してしまうという事態になると思います。この最低賃金は、中央最低賃金審議会において労使の意見を聞いて、地域別に賃金改定しているわけですから、民間の区内産業のアルバイト代が自然と上がってくれば、区内で働く非常勤職員の方の最低賃金も私は自然と上がってくると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":199,"id":"exchange-050"},{"speaker":"あくつ副委員長","kind":"質問","question":"けれども、ご説明の最後にあった、今年法改正があって、今後非常勤職員の方の待遇が改善をされるというようなことが先ほどあったのですけれども、これは法律のことだと思うのですが、具体的にはそれはどういう背景で、平成３２年度とおっしゃっていましたけれども、今後どのように処遇が改善されていくのか、もう少しわかりやすくお願いします。","respondent":"黒田人事課長","answer":"ただ、こちらのほうがではどういった水準になるかというところにつきましては、基本的には各地方自治体での判断になるのですが、特別区の場合はいわゆる特別区の特殊な事情がございまして、一般職の公務員ということになれば人事委員会の関与というところもあろうかと思いまして。","voiceIndex":200,"id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問","question":"専門非常勤職員のところを聞くのを忘れてしまったので、専門非常勤職員の内容をわかりやすく教えてほしいのと、どういう職場に何人くらいいるのかということと、定年退職をした後、豊かな経験を活かしていただくということらしいですけれども、専門非常勤で働いていらっしゃる方がものすごく本当に激務の中で、フルで１週間は働けないけれども、かなり働いているのだけれども賃金が半分とか。","respondent":"黒田人事課長","answer":"あくまで専門非常勤職員につきましては職を規定してございまして、先ほど申し上げましたように５５の職務があります。","voiceIndex":202,"id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問・要望","question":"戸籍のところと税務のところだけだったのですが、もうちょっと区民と接点のあるところはどのようなものがあるのか教えていただきたいです。それと、勤務時間もいろいろ違うということで、報酬が違うのは当然ですが、職員給与と最低賃金と専門性を鑑みてということで賃金を決めているということなのですが、そういうことだと、この１,４００円が妥当であるとお考えでしょうか、お尋ねします。","respondent":"黒田人事課長","answer":"１,４００円が妥当かどうかというお尋ねですが、先ほど申し上げたとおり、１類の職員の初任給を時間で割り返しますと大体１,３８０円ですので、１,４００円という報酬の設定については適正であると考えています。","voiceIndex":204,"id":"exchange-053"},{"speaker":"飯沼委員","kind":"意見","question":"時間に直すと適正ということですが、様々な待遇の面で大きな差がある中で、この時給だけ比較して妥当であるというのは、私は違うと思います。現実的に働いていらっしゃる方が仕事量と照らし合わせて、この賃金が非常に安いという訴えが届いていますので、このことはしっかりお伝えをしておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":206,"id":"exchange-054"},{"speaker":"吉田委員","kind":"質問","question":"先ほど聞き忘れました。この請願の文の中に「どちらも最低額」というのが括弧書きであって、専門非常勤職員の時給は１,４００円、一般非常勤は１,１４０円が最低額とお聞きしたのですが、だから１,４００円、１,１４０円というのは最低ということだと思ったのですが、だからもう少し高い方がいらっしゃるとか、それこそ専門性に鑑みてとか、その辺はいかがですか。","respondent":"黒田人事課長","answer":"例えば保育園の非常勤医務資格ですと、例えば１,５００円の設定をしていますし、例えば先ほど申し上げました消費生活相談員ですと、これはちょっと勤務日数から割り返していますので少し端数が出ますが２,６１５円ということで。","voiceIndex":207,"id":"exchange-055"},{"speaker":"高橋（伸）委員","kind":"意見","question":"結論を出すでお願いします。平成３２年４月から新しく改正された法律が施行されるということで、その改正に伴って非常勤職員の給与体系も区でも検討するということなので、今回の請願については不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":211,"id":"exchange-056"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"時間だけではかれるものではないということもあって、そういう中で先ほどのご説明を聞いて、また今後、先ほど意見の中でもありましたけれども、国のほうでもそれをしっかりと捉える法改正も行ったということで、ただ、今、制度設計を行っているというところなので、どこまで反映されるかというところで、これはしっかり大事な仕事をしていただいている大切な非常勤職員の皆様ですので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":212,"id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"態度を決めるということで、共産党としてはこの間の正規職員を減らして非常勤職員に置きかえているこの品川区の状況、人件費をどんどん削っているというところにおいて、大事な区政を支えてくださっている非正規職員の待遇改善、特に時間当たりの賃金を引き上げてほしいというのは出ていますが、均等待遇というところをもう少しきちんと実態を調べて検討していただきたいと思うのが１点。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":213,"id":"exchange-058"},{"speaker":"石田（し）委員","kind":"意見","question":"結論を出すで、意見を言います。説明の中でもありましたが、いわゆる一般職員の方の給与を時給に割り返すと、そこまで差がないのではないかということ。正規職員の給与がマイナス改定をされている時に、非常勤職員のところに関してはそのまま据え置きとされていた等々の理由の説明があったので、我々としては今回のこの請願に関しては不採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":214,"id":"exchange-059"},{"speaker":"須貝委員","kind":"意見","question":"結論を出すということと、先ほど申し上げましたが、東京都内の最低賃金が今度時給９５８円に改定されます。まだまだ民間の中小零細企業で働く、商店で働く方たちの時給が低いということをやはり我々は念頭に置いて、そのうち賃金が上がってくれば、おのずと品川区で働いている非常勤職員の方の賃金も上がってくると思いますので、それまでは我慢をしてほしいということで、今回は不採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":215,"id":"exchange-060"},{"speaker":"吉田委員","kind":"質問","question":"意見を言います。なので、この趣旨はとても理解するのですが、実はやはりこの１,５００円という金額を定めてしまうということについて、ちょっと生活者ネットワークの周囲には市民事業としてなかなか厳しい中で、ミッションから事業を継続している人たちがたくさんいて、今売り手市場というのでしょうか、労働者のほうが足りないという中では大変厳しい状況があるのも実態なのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":216,"id":"exchange-061"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2086#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":41493,"voices":223}},{"id":"h29-20170926-6","meetingId":"h29-cm09","date":"2017年9月26日","dateIso":"2017-09-26","committee":"区民委員会","time":"午前１０時００分～午後 ０時１６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２８年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"平成２８年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"私からは、昨年に引き続き、天下りについて率直に伺いたいと思います。人数について把握しているのかを伺いたいのですが、指定管理者である品川ビジネスクラブ・マグネットスタジオ共同事業体と公益財団法人品川文化振興事業団、それと公益財団法人品川区スポーツ協会、それぞれ品川区からの天下りは現在何人在籍しているのか。人数を伺いたいと思います。","respondent":"山崎商業・ものづくり課長、鈴木文化観光課長、池田スポーツ推進課長","answer":"区のＯＢ職員という捉え方ですけれども、１名です。文化振興事業団につきましては、ご質問にあった管理職ということで言えば、４名です。スポーツ協会におきましては、区のＯＢ職員ということに関しましては、８人です。管理するところでは、非常勤、常勤含めての数字です。","voiceIndex":7,"id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"それぞれ１人、４人、８人と、管理職のＯＢということでよろしいのでしょうか、確認させていただきたいのですけれども。","respondent":"池田スポーツ推進課長","answer":"大変申し訳ございません、管理職ですと、２人です。","voiceIndex":11,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"改めて、管理職のＯＢという枠組みでは、１人、４人、２人というわけになるわけですね。区としてはこれをどう考えていらっしゃるのか。私は、区民の理解も得られないし、やめるべきだと思うのですけれども、その点いかがでしょうか。２つの部と３つの課に分かれているので、誰にまとめてその考えを聞いたらいいのか聞きにくいので、３つの課それぞれに伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"改めて伺いたいのですけれども、例えば公益財団法人は公益性が高く、独立性も高い。こういうところに区の管理職のＯＢがいるというのは、公益財団法人の趣旨に照らしても私は疑問が残るのですけれども、その点いかがかというのが１つ。もう一つは、やはり区としても天下りを規制するルール化が必要だと思うのですけれども、このルールはあるのか。そこもご説明いただきたいと思います。","respondent":"安藤文化スポーツ振興部長、堀越地域振興部長","answer":"決算もそうです。そういうことで、公益法人独自に理事会等を行って、しっかりコンプライアンスと申しましょうか、法令順守のもとに運営しているということで、それで問題ないと考えています。そういった意味で、適切かつ公正に運営されていると認識しています。","voiceIndex":16,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"予算委員会や決算委員会の場ではないので、ルール化のところは答えにくい部分もあるのかなとは思います。年間の決算と予算についての中身であって、そこは少し違うのではないのかなと思いますので、改めてお伺いしたいと思います。いずれにしても、チェックする側とされる側が、このような関係を続けているというのは問題だと思いますので、この点は改善を要望したいと思います。","respondent":"安藤文化スポーツ振興部長","answer":"理事会の理事については、評議員が決定するという決まりになっています。それと、決算と人事の理事のほうです。","voiceIndex":19,"id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"ビジネスクラブのほうをお伺いします。それならば、業務の１つなのですから(6)として書けばいいではないですか。書かなかった理由、もしくは区長の業務というのは実質上ないのか、その理由についてお伺いしたい。それと、スポーツ協会も書いていないから、その他区長が必要と認めた業務は入っていないのですかという質問。それと、数字的にはすごく評価します。","respondent":"山崎商業・ものづくり課長、鈴木文化観光課長、池田スポーツ推進課長","answer":"それで区が、例えば創業支援の支援メニューで、このような方面をやってほしいとか、あるいは同時に。それからスクエア荏原のほうですが、こちらは逆に、先ほどもご説明いたしましたように、基本的には文化、スポーツ。かといって、区長が認めた業務がやられていないかということになりますと、こちらは区と連携して行っております。","voiceIndex":21,"id":"exchange-006"},{"speaker":"藤原委員","kind":"確認","question":"でも、今はないのですよということでいいのですねという確認。それと、地域振興部長にお伺いしたいのですけれども、あえて伺いますが、ビジネスクラブの利用率はすばらしいではないですか。限りなく１００％に近いほうがいいのですけれども、ここで私はすばらしいと思っているのです。その施策に対する利用率の評価を部長としてはどう考えているのか、その辺についてお伺いさせてください。","respondent":"池田スポーツ推進課長、堀越地域振興部長","answer":"今の委員からのご指摘のとおりでございまして、需要の低くなったものについては縮小という形になりまして、平成２８年度につきましては、前段の部分で、新たな事業といたしまして。それから産業振興の施策をどう打っていくかという部分については、区からもしっかりと申すことは申して、かつ連携するところは連携してやっていきたいと思っているところです。","voiceIndex":25,"id":"exchange-007"},{"speaker":"藤原委員","kind":"質問","question":"あえて部長に伺ったのは、部長はいろいろな課の部長ですから、そういう意味において、ここの本題と少しずれてしまうかもしれないのですが、利用率の数字が区民に評価されている。それで、もう一つ新しく質問をするならば、利用率があまりよくない事業に関しても、今日の本題とは違うかもしれないけれども、どう考えていくのかということを答弁していただければ幸いです。","respondent":"堀越地域振興部長","answer":"私がちゃんと解釈できているかどうかというところはあるのですけれども、まず、基本的には、指定管理施設の場合では、利用率を１つの指標にするということが基本だと思いますので、それをしっかりと見ていく必要があると思います。","voiceIndex":28,"id":"exchange-008"},{"speaker":"塚本副委員長","kind":"確認","question":"スクエア荏原なのですけれども、予算執行の視点ということで、区からの指定管理料の返還につながった、予算額が余りましたということで、これは平成２８年度だけではなくて、平成２７年度や平成２６年度もそうだったのか。平成２８年度になって、そういうことに至ったということなのかということを最初に確認したいです。","respondent":"鈴木文化観光課長","answer":"すみません、今、手元に資料がないので具体的な額はお答えできませんが、毎年度、余裕が出た場合には返還ということでお願いしています。","voiceIndex":30,"id":"exchange-009"},{"speaker":"塚本副委員長","kind":"意見","question":"指定管理料の返還というか、利用料が当初よりも上回っているというところがあるのだと思うのです。利用料を下げるのか、指定管理料を返すのか、文化振興事業団との話し合いの中でそのようになっているという前提だと思いますが、使用料に対して下げていこうみたいな考え方は出てくる部分はどう考えておられるのかお願いいたします。","respondent":"鈴木文化観光課長","answer":"指定管理料ですが、これは最初に提案いただいたときに、予定する５年間の毎年の指定管理料の提案をいただいておりますので、基本的にはその額になります。","voiceIndex":32,"id":"exchange-010"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"このようにいろいろしている中で、なぜお神輿の写真を使ったのかをお伺いします。それと民泊について１点、生活安全担当課長にお伺いしたいのですけれども、民泊という形で制度ができて、民泊に向けた動きがあるのですけれども、ご意見があればでいいのですが、警視庁的には、民泊という意味において、全てがよしという形ではないと思うのです。","respondent":"鈴木文化観光課長、菅生活安全担当課長","answer":"これまでに６回、年１２回の予定の半分を実施しているのですが、最初の３回はＳＮＳで写真を、それから、４回、５回、６回目は、動画も含めて情報発信していただいたところ、かなり外国人の方の注目度が高く、アクセスも。そういったことも、外国人に対してルール、マナーを教えていく、指導していくということも大事なことではないかなと考えているところです。","voiceIndex":38,"id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"このお神輿は御霊を担いでいるわけですから、神事ですよね。それで、2)の禅は、禅宗があるくらいで、神仏の仏ですよね。改めてその辺について、２つの写真が出ているけれども、観光ですけれども、細かく言えば宗教行事、それが１点。もう一点は、あえて生活安全担当課長にお伺いして、このような課題がありますということを何点か答弁していただいたのです。それを伺って、課長はどのように思われるか。","respondent":"鈴木文化観光課長","answer":"２点目の民泊の課題についてです。先ほど口頭でご説明しましたように、９月８日に国の連絡会議がございまして、課題への対応についてもある程度の方向性は示されております。","voiceIndex":41,"id":"exchange-012"},{"speaker":"中塚委員","kind":"確認","question":"私からは大きく２つ、ＬＧＢＴなどのセクシュアルマイノリティーについてが１つと、民泊について、それぞれ伺いたいと思います。やはりオリンピックを踏まえ、様々な方々が楽しみに来ている中で、宿泊というのはとても大事なことだと思いますけれども、品川区内の４８施設は、同性同士のダブルルームは拒否しない、ウェルカムだということを確認しているのかどうかご質問したいと思います。","respondent":"鈴木文化観光課長","answer":"先ほどご報告した区内施設の状況です。口頭でも申し上げましたように、観光振興協議会と国の調査の中で把握した情報でございまして、ご質問のＬＧＢＴ等の対応の可否については、これまでまだ調査をしておりません。","voiceIndex":43,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"レズビアンの方や、ゲイの方や、トランスジェンダーの方など、日本国内はもちろん、世界中から集まるわけです。品川区としてこのような事業を進めていくわけですから、そのような理解と、法律と、オリンピックの趣旨を伝えて、レインボーフラッグを受付に置いたり、パンフレットに紹介するなど、そのような取組みも必要になってくるのではないかと思うのですけれども、２点、いかがでしょうか。","respondent":"鈴木文化観光課長","answer":"協議会本体の下に実働のワーキンググループを設定しておりますので、今年度、まずはそこでテーマとしてお出しして、皆様からも意見をいただきながら、今後、区内でしっかりとした対応ができるように情報共有や対応を検討したいと考えております。","voiceIndex":45,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひいろいろ取組みを進めていただきたいと思うのですが、１点だけ。新聞報道だけで申し訳ないのですけれども、豊島区の副区長は、宿泊を拒否する理由が同性同士であることだけなら、旅館業法の違反に当たると、そのような報道がされているのです。先ほどの答弁ではその辺がはっきりしなかったので、その点だけ確認させてください。","respondent":"鈴木文化観光課長","answer":"先ほど申し上げたのは、具体的にそのような訴訟があって、法解釈についての方向性を示す事例があったことを副区長は言っているのではないということで、ただ考え方としては、委員もおっしゃったように、状況に応じての判断になりますが。","voiceIndex":47,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"人権啓発課や厚生委員会だとどこの課なのかわかりませんが、旅館業法を取り扱う課ともよく確認、調整していただいて、私は旅館業法違反に当たると思っていますので、そこは確認していただきたいと思います、これは要望です。次に民泊について伺います。私は、規制緩和ではなく、しっかりした安全ルールの確立が必要だと思っているのですけれども、その点についても区の問題意識をお伺いしたいと思います。","respondent":"鈴木文化観光課長","answer":"特区の場合は、特区に指定されるだけではなくて、そのための条例制定等も手続きがありますので、現実的には、特区の仕組み以上に裁量権や規制の度合いが緩和されている新しい法律に基づいて、民間が通常の事業として実施するほうがスムーズに移行できると考えております。","voiceIndex":50,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"私は、規制緩和ではなく、旅行者も、また地域の方々も、安心して旅行を楽しめるためには、しっかりした安全のルールの確立が欠かせないと思うのです。届出が東京都で、区としての条例は考えていないというお話ですから、ただ一応資料には、区内での事業開始に向けた準備を行っているとありますので、そういう住民の不安や旅行者の安全確保についてどのようにお考えなのかお伺いしたいと思います。","respondent":"鈴木文化観光課長","answer":"区もそれに準じて、しっかりと区の権限の中でできることについては対応したいと考えております。","voiceIndex":52,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に意見だけ述べたいと思います。民泊については、やはり海外の方が日本の文化や風習を心から安心して味わってもらうためにも、またビジネスマンが宿泊先に困らないためにも、違法な民泊を野放しにすることは当然だめなことだし、危険な規制緩和ではなく、旅館業法などの規定に適合した許可制をしっかり堅持したルールの整備こそ必要だと思いますので、そこを踏まえていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-018"},{"speaker":"田中委員","kind":"意見","question":"民泊についてです。地域の方からは不安の声があります。区内で事業開始に向けた準備を行っているという部分なのですが、地域の方からは不安の声が上がっているのです。事業者が民泊を始める前に、近隣住民への説明がどのように行われるとか、そのような具体的なことは何か決まっていますか。","respondent":"鈴木文化観光課長","answer":"いずれにしましても、政省令にしてもガイドラインにしても今検討中で、そのような項目については認識をして、検討しているというところまでの報告だったので、具体的な中身については未確定です。","voiceIndex":55,"id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"トラブルが本当に起きてしまったり、今住んでいる方たちに何かしらが起こってしまう、そのような事態が招かれないように、住民の方たちが納得するようなちゃんとした説明と、民泊が行われる前にきちんと話し合いがされる場、住民の方たちの意見が聞ける場というのは必ず用意してほしいという要望をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-020"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"田中委員","kind":"質問","question":"予算の内訳、ありがとうございました。ただ、もう少し詳しい内訳が欲しかったなと思うのです。去年、私が電話でヒアリングしたときには、ＬＥＤの電球が幾ら、設置費用が幾ら、維持管理、撤去代が幾らということを伺っているのです。維持管理や設置部分にお金がかかるということをそのときに知って、そういうものなのだなとわかったのです。もっと具体的な内訳を書いてほしいと思います。","respondent":"鈴木文化観光課長","answer":"ご指摘のあった設置費用やＰＲ費用などの具体的な内訳がまだ確定していませんので、今の時点では主な項目として、協議中ということで記載させていただいています。その辺は、今後、実施しまして、報告のときには詳細な内訳についてもご説明ができるようになるです。","voiceIndex":66,"id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"シナモロールの切手について１点だけ伺いたいのですが、これは１,５００円で１,０００シートだから、１５０万円ではないですか。切手は１０枚だから８２万円ではないですか。切手が１０枚ついているから、そうですよね。その差額がありますけれども、当たり前ですが、郵便局に行くわけですよね。考え方を伺いたいのですけれども、そういうものなのですね。差額が出て、利益が出て、郵便局、どうぞと。","respondent":"鈴木文化観光課長","answer":"これは、あくまで郵便局が利益を上げる活動に協力してくれという申し出があったことではなくて、区がその事業の中でシナモロールを使ってもらってＰＲしていただくという考え方です。","voiceIndex":68,"id":"exchange-022"},{"speaker":"田中委員","kind":"質問","question":"イルミネーションのことなのですけれども、一応予算額がついているので、大体の予算の内訳は目星がついているというか、何となく大体幾らくらいというのはわかっていると思うので、次からはそこら辺までを書いてほしいと思います。なるべく情報はいっぱい欲しいので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど聞けばよかったのですけれども、その他での報告と報告事項の差がよくわからないのです。先ほどのシナモロールの切手販売も、今回の体育の日の事業についても、報告事項ではなくてその他として扱う。それぞれしっかりやっていただきたいとは思うのですけれども、何だかなという思いが。","respondent":"本多委員長","answer":"言われることはよくわかります。最初から報告事項に上げられるような委員会運営に努めていきます。ご理解をよろしくお願いします。ほかになければ、以上でその他を終了いたします。","voiceIndex":74,"id":"exchange-024"}]},{"id":"topic-04","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"現地でそのようなことは言いませんけれども、要するに安全のルール化、条件をどのように整理しているのか、その点について伺いたいと思います。伊勢市ですけれども、スポーツ合宿の誘致ということですが、やはり地元の小・中学生や地元の地域スポーツとどういう交流を図られているのか、その視点は踏まえたいなと思います。具体的には、正副にお任せいたしますけれども、調整していただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-025"},{"speaker":"渡辺委員","kind":"質問","question":"それで、やっているノウハウをいろいろお聞きしたいなと思いました。稼働率の低い時間帯、シーズンオフであったり、平日であったり、そのようなところをどのように取り組んでいるのかを細かく、世代や対象をどうやっているのか。当初の想定から、いざ実際やってみてが違うと思うので、そういうものが取材できたらいいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2792#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":38245,"voices":84}},{"id":"h29-20170926-7","meetingId":"h29-cm09","date":"2017年9月26日","dateIso":"2017-09-26","committee":"厚生委員会","time":"午前１０時００分～午後 ２時４４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"南品川４丁目特別養護老人ホーム（法人立）の整備計画進捗状況","agenda":"南品川４丁目特別養護老人ホーム（法人立）の整備計画進捗状況","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それと、補助金のほうについても内示があったということですけれども、補助金が幾らになるのか。今、品川は、促進係数も１.５になっているということですけれども、そういうのも含めて、補助金が何床で幾らになるのかも教えてください。それからあともう一つ、介護予防拠点併設と書かれているのですけれども、この介護予防拠点というのはどういうものなのかについてもお聞かせください。","respondent":"大串福祉計画課長","answer":"介護予防拠点です。先ほど最初の資料でもご説明しましたが、今も一宮市で特養を運営している法人です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"特養ホームは８１床ですけれども、この補助金は１床当たり５００万円×１.５となると思うのですけれども、ショートステイの通所というのも同じような形で計算されるのかを教えてください。総事業費、総建設費というのでしょうか、それがわかったら教えていただきたいと思います。それから、この道路は幅何メートルぐらいあるのか。","respondent":"大串福祉計画課長","answer":"売却金額につきましては、申しわけありません、非公開ですので、私からはお答えしかねます。それから、整備費のところです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"わかりました。特養ホームの補助金の関係では、介護予防拠点併設というのだと、補助金として併設加算というのがつくと思うのですけれども、これ以外のところでは加算がつくようなものは併設されないのでしょうか。例えば、認知症対応のデイサービスだったりとか、そういうふうな併設加算がされるようなものがほかにはないのかだけ、確認をお願いします。","respondent":"大串福祉計画課長","answer":"今委員からありましたようなデイサービスとかそういった施設の併設は、今のところ考えていません、スペース的に少し厳しいといったところです。やはり９０床とるということで、そちらのベッドを確保することに法人のほうでも注力したところかと思います。","voiceIndex":9,"id":"exchange-003"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"先ほど道路の確保で法人の努力と言われていたのですけれども、区は努力できなくて買えなかったのかなというふうにも聞こえるので、そういうのは区が道路を確保することはできないのか、伺いたいと思います。","respondent":"大串福祉計画課長","answer":"区としては、国有地と提示があった中での検討となります。その先の話としての前面の土地所有者の方との交渉、そういったことを前提とした土地の購入はできかねます。","voiceIndex":12,"id":"exchange-004"}]},{"id":"topic-02","title":"平成２８年度指定管理者の管理に対するモニタリング・評価の結果","agenda":"平成２８年度指定管理者の管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"６１ページなのですけれども、西大井つばさの家の積極的に評価した事項ということで、障害者グループホーム連絡会がつくられて年５回開催されたということなのです。どんな目的でこれがされているのか。区の職員もここにかかわっているのかについて、まず教えてください。","respondent":"中山障害者福祉課長","answer":"これは知的・精神全ての区内グループホームの世話人に声をかけて実施しているものです。目的としましては、グループホームは、法人立のものもあれば区立のものもあるのですけれども、小さいＮＰＯ法人が運営している事業所もたくさんあります。","voiceIndex":22,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ありがとうございました。こういう取り組みはすごく大事なのではないかと思います。そしてまた、ぜひ質の向上につなげていただけたらなと思いました。その点では、高齢者の分野でも、品川は、いろいろなところから社会福祉法人が入られて、すごく広がったと思うのですけれども、そういうところでの交流はあるのかお聞かせください。","respondent":"寺嶋高齢者福祉課長","answer":"従来からの５法人につきましては、交流会というか、担当者会議、事業所会議みたいなものを継続してやっております。それから、新しく入ってきたところについては、自主的に情報交換をしているというのを施設訪問等したときに聞いております。","voiceIndex":24,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"それで、この認知症のデイのところが利用率が低い、課長からも、１０人の定員のところは２名下がると下がってしまうとありましたが、それは１日ということなので、多分、毎日来ている人ばかりではないので、これだけ減るということになると、実際は２名よりももっと減っているのかなと思うのです。今後どういう取り組みを考えられているのかもあわせてお聞かせいただけたらと思います。","respondent":"寺嶋高齢者福祉課長","answer":"ただいまのご指摘のとおりで、あと、先ほども説明の中で触れたとおりですが、認知症デイの利用が少ないのは数字として出てきているもので、原因の１つはパイの問題で、数字の変動幅が大きいというのはもちろん考えられるのですけれども、実は先々月。","voiceIndex":26,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"わかりました。もう一つ、２７ページなのですけれども、八潮南認知症グループホームで、転倒事故が４７件発生したというところで、筋力低下が要因だと書かれており、ほかでも事故の件数が増えてきているとあるのですけれども、４７件はかなり多いように思うのです。そして、もし全くの民間だったら、これがないまま介護報酬だけでやるのか、その辺もお聞かせください。","respondent":"寺嶋高齢者福祉課長、中山障害者福祉課長","answer":"もちろん、頻度が高い方については、それ相応の対応はどの施設もやっておりますけれども、そういったことがつかめるまでの間に転倒事故が起きてしまっている、これが現実に起きていることなので。私からは、障害者福祉施設の管理委託料の考え方についてご説明いたします。基本的には障害者のほうも支援費が入りますので、その収入を基本とはしているところです。ただ、それ以外にも区からの委託事業というのがあります。","voiceIndex":28,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"高齢者施設のほうも管理委託料の計算の仕方、どういう基準で出ているのかということでは、要綱とかあるわけではないですか、その辺の仕組みを教えていただきたいと思います。それと、特養ホームの介護報酬は平成２７年度からかなり下がっていると思うのですけれども、それによる影響がどうなのか。","respondent":"寺嶋高齢者福祉課長","answer":"それと、賃金ということがありましたけれども、全ての法人にこと細かに全てを聞いたわけではないのですが、報酬改定等も含めた法人とのヒアリングの中で、制度改正については法人側の運営の努力として当然取り組んでいくべきだという認識は持たれていると確認していますし。","voiceIndex":31,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"管理委託料は、各法人との協定の中でどういうふうに計算しているのでしょうか。幾ら委託料を出すよという協定になっているという意味でしょうか、その点、１点お願いします。それともう一つ、離職率が各法人によっても多分違うと思うのですが、品川全体の、この区立の介護の現場で働く方々の離職率がどうなっているのかについてもお聞かせください。","respondent":"寺嶋高齢者福祉課長","answer":"これにつきましては、区内５法人の平均ということで、法人によっては１桁台のところもまだまだありますので、この辺はどういった取り組みをしているのかも、先ほど言いました法人の連絡会等で情報共有をしながら、人材確保・定着に努めているところです。","voiceIndex":33,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、離職率は、１４.８％になってしまった、２.７％も上がったというのは、区としてはどう捉えているでしょうか。働き続けるのが困難な状況があるのではないかと思うのですけれども、そういう点で言えば、処遇の改善なども含めてどうなっているのかというあたり、離職率が２.７％も上がってしまったことに対して区としてどう捉えているかをお聞かせいただきたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"もう一つは、個別にかかってくる経費として単価分というのがあります。これについては、加算等で負担化しておりまして、例えば、送迎とか配食サービスの実施とか、そういった個別の事業について加算をして給付金額を決めていくといった内容です。","voiceIndex":35,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"４ページなのですけれども、４番の組織管理体制および業務の適正執行の視点というところで、介護福祉士の資格取得職員の配置が多く、質の高いサービスを提供できるとあります。それともう一つ、ショートステイの利用が下がってきていると思ったのですけれども、ショートステイの全体の需要は区としてはどうなってどう捉えられているかについてお聞かせください。","respondent":"寺嶋高齢者福祉課長","answer":"非常に低い数字があらわれている後半の地域密着型多機能ホームのショートステイは、かなり低い数字がたくさん書いてあったと思うのですけれども、これは、地域密着型の小規模多機能のまさに特質でありまして、登録者のみが使うことになっておりますので。","voiceIndex":38,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、先ほど、特養ホームは介護報酬はそこにあわせた報酬で問題ないということでしたけれども、現場の実態を一番よく知っているのが地方自治体の区なので、今度の介護報酬では、引き下げないようにという声はぜひ区のほうからも上げていっていただきたい。そういうところもぜひ区のほうからも求めていただきたいということで、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問","question":"簡単に２点だけお聞きします。１９ページの三徳会の荏原特別養護老人ホームですけれども、ここだけ特別に入所者の平均年齢が８９歳ということだったのですけれども、全体的にこの辺の流れ、ほかの施設が特別に書いていないのか、ここだけなのか、その辺の感覚をまず。","respondent":"寺嶋高齢者福祉課長","answer":"ご指摘のとおりここにしか書いていないのですけれども、ほかの施設については実際には上がっているという認識です。原因は分析していないのですけれども、ここの施設が結果的に下がったので、こういう記載があったと認識しております。","voiceIndex":42,"id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問","question":"何でここだけと非常に気になったのでお聞きしました。それからもう一つだけ、５７ページ、品川児童学園です。きのう少しお話が出たと思ったのですけれども、原因の分析のところに、肢体不自由児への対応や保育園等との併用利用というのが出てきて、昨日もたしか出ていたので、この辺もう一回教えてください。","respondent":"中山障害者福祉課長","answer":"ただ、今後の需要を見ますと、通園タイプで通ってくるだけではなく、よそに所属を持ちながら、やはり療育が必要だということで、例えば週２日の療育を受けられる、そういう機会を確保していく必要がある。","voiceIndex":44,"id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問","question":"児童学園、これから変わっていく中で、福栄会がこういうコメントを出していること、グローが今後はやっていく、その辺の引き継ぎ関係は十分とれているのか。場所としても、あの場所ではできないですよね、その辺はどう考えているのか教えてください。","respondent":"中山障害者福祉課長","answer":"今までも保育園と併用利用ができるような仕組みがとれないかというのは課題として持っておりましたので、福栄会のほうでもそうしたプログラムをどうしていったらいいかという話もゆうゆうに引き継ぎながら、ただ実際には。","voiceIndex":46,"id":"exchange-016"},{"speaker":"浅野委員","kind":"質問・要望","question":"このような施設、機械室などを持っているところで、同じような形で費用削減ができるようなところがあるのかどうか。そしてもう一つ、今回のこの省エネ診断については、どこが発案というのでしょうか、きっかけとして行うことにしたのかを教えてください。","respondent":"寺嶋高齢者福祉課長","answer":"そういう取り組みをしたことによって、ランニングコストが５００万円、実際７,５００万円程度のものが７,０００万円ぐらいに下がったということを、改善点として上げたという内容です。","voiceIndex":49,"id":"exchange-017"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"先ほど事故についての質問があり、ほかにも事故防止の研修会を開いている特養ホーム等、多くあるなと思いました。先ほど、法人の意見を聞きながら人材確保をしていきたいということで賃金アップということもあったのですが、それ以上に区として人材確保の支援を進めていく体制、今後どうされていくのかというのを伺いたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"経験のない職員という話もありましたけれども、経験のない職員の方を法人の経営方針にあわせて１から研修をしていくというやり方が効果的だと捉えている法人もいますので、これは経験者をとる、全くの新しい方をとる、これは施設・法人の考え方によるところだと思います。","voiceIndex":52,"id":"exchange-018"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"そういったところから人材確保にもつながっていかざるを得ないのですけれども。そういうところでも、区としては、先ほどありましたけれども、報酬を引き下げないとか、人材確保のための賃金アップを国に求めるとか、介護の改悪をストップさせるとか、そういった立場に立っていただきたいと思います。これは要望です。そうすると、児童発達支援ほぼそれの利用率になるのでしょうか。","respondent":"中山障害者福祉課長","answer":"すみません、ご説明が足りませんでした。児童発達支援のうち通園の部分の利用率になっております。","voiceIndex":54,"id":"exchange-019"}]},{"id":"topic-03","title":"平成３０年度分「高齢者住宅（建設型・借上型の単身用）」および「区立大井林町高齢者住宅（単身用・２人用）」の入居待機者の募集","agenda":"平成３０年度分「高齢者住宅（建設型・借上型の単身用）」および「区立大井林町高齢者住宅（単身用・２人用）」の入居待機者の募集","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"順位をつけて登録者を１番から何番とやっていくと思うのですけれども、その順位をつけるに当たって明確な点数になっているのかを教えていただきたいのですが、特養ホームだと、自分の点数が要介護度と年齢で計算するとわかる点数表が公開になっていますけれども、そういう点数表があって、高い順番から順位が決められるのか。そこの点数表の中身についても教えてください。","respondent":"松山高齢者地域支援課長","answer":"そのうち入居した方が平成２８年度は２７名になっております。それから、審査会の点数ですけれども、こちらは基準に基づきまして点数化はされています。ただ、点数では判断できないご本人の生活状況等もありますので、そちらも加味しながら行っているものです。","voiceIndex":63,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"わかりました。平成２８年度に向けたというのはその前の年ですよね。ちなみに、平成２９年度の申込者は何人いたのか教えてください。大井林町のほうなのですけれども、補欠登録者は単身が２０人と２人用が１０組ということなのですけれども、ここのところでは１年間で何人ぐらい入れたのかを教えてください。","respondent":"松山高齢者地域支援課長","answer":"失礼いたしました。先ほど申し上げたのが前年度の数字になります。その前でしたら、平成２７年度が申請者が６６人、入居者が１９人になっております。それから２点目ですけれども、大井林町の入居人数ですけれども、平成２８年度は９名の方が入居されております。","voiceIndex":65,"id":"exchange-021"}]},{"id":"topic-04","title":"後期高齢者医療制度保険料","agenda":"後期高齢者医療制度保険料","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"財政安定化基金は国と東京都と区と３分の１ずつ出すという仕組みなのかなと思うのですけれども、その財政安定化基金というのは、東京都広域連合で幾らたまっているというのがわかったら教えていただきたいと思います。剰余金は８４億円、保険料抑制のために、平成２８・２９年度のときは使われたということで考えていいのでしょうか、それが１点です。","respondent":"三ッ橋国保医療年金課長","answer":"と言いますのも、剰余金の考え方です。例えば、平成２８・２９年度の保険料算定におきまして、平成２７年の決算が終わらないと剰余金がはっきりしませんので、そちらに関しましては現時点では剰余金を見込むことが困難となっております。","voiceIndex":72,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ、そういうふうにしていただきたいということです。それともう一つお聞かせいただきたいのが、一番初めのページの２つ目の保険料率算定時の設定条件というのがありますけれども、ここのところで、国の保険料軽減特例については、現在公表されている見直し内容によったとあるのですけれども、これがどういう中身なのかについてお聞かせください。","respondent":"三ッ橋国保医療年金課長","answer":"それに加えまして、東京都ですが、東京都広域連合の軽減措置といたしまして１５万円までは７０％、また、２０万円までは４５％の軽減措置をしています。国の制度施行時の特例措置については、現在２０％ですが、今後、平成３０年度は廃止の見込みとなっております。","voiceIndex":74,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"国のほうが、平成３０年度これが廃止の見込みということなので、こうなると少し大変だなという思いがしています。それとも、国が０にするのだからと東京都までなくしてしまうとか、そういうところまで話し合われているのかどうかを１つお聞かせいただきたい。それをさらに今度は平成３０年からは本則の５割まで軽減措置を引き下げる、だから、５割負担になると国としても出しています。","respondent":"三ッ橋国保医療年金課長","answer":"均等割・所得割額、国によったとこちらに書いていますけれども、先ほど私が要望していると申し上げたのですが、その中にも、均等割や、所得割の部分、低所得者の方々にどの程度軽減するかという部分、このままでいくと。","voiceIndex":76,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この特例軽減って、本当に多くの方、６割、もっとですかね、かなりの方が対象になるところなので、この後期高齢者医療制度がつくられたときに大きな反対運動が起こって、そのことによってこういう特例軽減もできてきたという経緯もあって、後期高齢者の方、７５歳以上ですから、年金も引き下げられて本当に生活が大変な状況がありますので、ぜひ、この特例軽減は。","respondent":"三ッ橋国保医療年金課長","answer":"平成２８年度の収納率ですが、現年度分が９８.９％、滞納繰越分が４６.７％となっております。次に短期証ですが、短期証の方は、平成２９年８月１日現在で６０名になっております。滞納者数は平成２９年５月末現在で１,２０５名となっております。","voiceIndex":78,"id":"exchange-025"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"先ほど２枚目の資料のところで、剰余金と財政安定化基金が多分今回も見込まれるであろう、まだわからないということですけれども、前回のこの８４億円の剰余金、それから財政安定化基金が１４５億円で、充当することとしたけれども、しなくて済んだ。そういう中で、均等割の上がりが２００円と。それぐらいに今回もなっていくのか、そういうのは今の時点ではわかりますか。","respondent":"三ッ橋国保医療年金課長","answer":"この１人当たりの平均保険料率につきましては、増加する要因と減少する要因、剰余金とこの基金以外にもさまざまな要因があります。したがいまして、今の段階では広域連合が算定できておりませんので、またわかり次第お伝えする予定です。","voiceIndex":82,"id":"exchange-026"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"私も上がってほしくないという思いで、幾らかなということで質問してしまいました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-027"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"意見","question":"地下１階と言いながら地面から入れるところなのか、その辺のところがわからないのですけれども、なぜ地下１階なのか。もう一つは、今まで使われていた上大崎１－３－１２そのものもどんな状況なのかよくわからないのですけれども、その後は何かに使うのか、その点についてお聞かせください。","respondent":"寺嶋高齢者福祉課長、松山高齢者地域支援課長","answer":"移転の理由ですけれども、１つは、現在の場所が若干手狭だということがありまして、この再開発事業に伴って、再開発事業の中で公共公益施設の設置というものがありますので、この中で寄付をいただいたということで。この移転後につきましては、２０平米ほどの洋室ですので、部屋の化粧直し、クリーニング等を行いまして、机を整備して。","voiceIndex":94,"id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そういうところからすると、この地下１階というのは、これだけの開発で、補助金もたしか税金投入が１００億円を超えたと思うのですけれども、そんな中で何で地下１階しか出さないのかという思いがするのです。本当に地上からそのまま入れるようなところへ要求はできなかったのか、その思いだけ言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":97,"id":"exchange-029"},{"speaker":"若林委員","kind":"確認","question":"現在の在支から目黒駅前の開発ということで、利便性とか、面積も大変広々となって、在支の役割を十分に果たしていただけるものだと期待しております。今ご説明で、地域の方々への貸し出し等と、そうしますと、近隣の町会とか、また、利用者のお声はどういうふうに聞かれて、相談しながら進めることになるのでしょうか、そこの確認だけ。","respondent":"松山高齢者地域支援課長","answer":"利用者の減免の方々につきましては優先になると思いますので、３月１日に受け付けを開始しまして、一般の方々向けには３月１０日から受け付け開始を考えています。ですので、そのスケジュールで逆算しまして、町会と近隣の方々にはご説明をしようと考えています。","voiceIndex":98,"id":"exchange-030"},{"speaker":"若林委員","kind":"確認","question":"今の２０平米の部屋を内装をして、しつらえて、そこはまた地域の方の交流の場に使っていただけるということで部屋について、どういう仕様、使い勝手のよさにするかという、地域の方の町会等の声は聞いて何か反映させる方向性があるのかどうかだけ確認します。","respondent":"松山高齢者地域支援課長","answer":"何か新しいものという工夫がなかなかできない狭い面積ですので、机・椅子は用意して、空調などもきちんと整備した上で、使い勝手のいいような形では考えたいと考えています。","voiceIndex":100,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"手狭で引っ越すということなのですけれども、今度のところの広さだけ教えてください。","respondent":"寺嶋高齢者福祉課長","answer":"新しく移転する先の在宅介護支援センターの床面積は、現在の資料では１４８.０５平米となっています。","voiceIndex":103,"id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3488#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":65915,"voices":110}},{"id":"h29-20170926-8","meetingId":"h29-cm09","date":"2017年9月26日","dateIso":"2017-09-26","committee":"建設委員会","time":"午前１０時００分～午後 ３時４５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"目黒駅前地区第一種市街地再開発事業の施設建築物竣工","agenda":"目黒駅前地区第一種市街地再開発事業の施設建築物竣工","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"すみません。在宅介護支援センターですけれども、これを入れると決めた理由は何だったのでしょうか。ちょっと確認したいと思います。需要見込みのようなものがあれば、ちょっと具体的に教えていただきたいのと、それと３階ということですけれども、緊急時の二方向避難というのはどんなふうになっていらっしゃるのか教えてください。","respondent":"稲田都市開発課長","answer":"そのようなことで、まちづくりのコンセプトをつくっております。再開発組合は、事業計画の中でこのようなことを提案してきておりまして、協議を重ねて、この施設を導入したです。次に、住居数をお知らせいたしますと、全部で９４０戸の予定です。","voiceIndex":9,"id":"exchange-001"},{"speaker":"安藤委員","kind":"提案","question":"理由が、組合からの提案があって、組合は在宅介護支援センターを上大崎一丁目のものを持ってきてほしいと言って区が了承したということでよろしいのか、というのをちょっとお伺いしたいのと、それと子育て支援施設は、伺ったのは１２０名の定員だということですけれども、それはマンションの部屋割りが大体発表されましたところ、このマンションの子育て世帯の方々の需要を満たすのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"ちょっとはっきりしていないのですよね。１２０名となったのは、保育課の判断なのですか。お答えください。そういう施設が必要だとなれば、実は新しくつくればいいのではないかと思うのですけれど、ほかのところから引っ張ってくるというのは、都市開発課としてのどんな判断があったのかなというか、そのあたり都市開発課としての判断はどうだったのかなというのもお伺いしたいというのが２つ目です。","respondent":"稲田都市開発課長","answer":"在宅介護のほう、保育もそうなのですけれども、所管と協議をしながらこのような形でやってきたです。","voiceIndex":14,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"所管とどんな協議をしているのかというのをお伺いしているのですけれど。まちづくりなわけですから、最終的には……。これはちょっと後で。今日はこの辺にしておきますけれど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"それを１点お伺いしたいのと、公共施設負担金というのが補助金とは別にあると思うのですけれども。それは今回幾らで、それは同様に、この公共施設との関係は何かあるのかというのを、２点目、お伺いしたいと。最後ですけれども、今回、寄付を受けるということなのですが、寄付を受けるということは、区として権利床として取得するということでよろしいのでしょうか。それをお伺いしたい。","respondent":"稲田都市開発課長","answer":"現段階で、区が再開発組合に支出する市街地再開発事業の補助金としましては、１０９億円ほどです。それから、これは公共性があるというところで、共同施設整備等々のところの費用に充てているです。それから、公共施設管理者負担金のことだと思います。","voiceIndex":18,"id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"新たに区がビルの中に権利床を取得されるということですね。わかりました。それと、公共施設管理者負担金のところは、額が、ちょっと聞いたのでお伺いしたいなと思いますのと、補助金のところは１０９億円ということですが、これは今回の公益施設ということもあるから、そこに対応して幾らというわけではないのかどうかと。そこはちょっとはっきりしなかったので、お伺いしたいなと思います。","respondent":"稲田都市開発課長","answer":"公共施設管理者負担金の、区としてこの組合に充てている補助金の総額が、９億９,８２１万７,０００円、約１０億円です。それから、寄付が補助金を充てているからもらったのかという話ですけれど、そうではございません。","voiceIndex":20,"id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"１点だけ、確認します。この地域のここの場所の駐輪対策、自転車の対策がどうなっているのかというところを確認したいと思います。目黒駅はかなり乗客数も多い駅で、放置自転車、また通勤でとめてしまうことも考えられると思いますので、その対策がどのようになっているのか、お知らせいただきたいと思います。","respondent":"稲田都市開発課長","answer":"この開発の中で、一般の方、ここに住んでいる方以外が使える駐輪場の台数が２１５台あります。その中で、保育施設に１０台、在宅介護施設に１０台ほど割当てがあるということで進めております。","voiceIndex":23,"id":"exchange-007"},{"speaker":"新妻委員","kind":"質問","question":"これは保育施設のところに１０台とかではなくて、決まった場所に。駐輪場がどこの位置になるのでしょうか。","respondent":"稲田都市開発課長","answer":"この下のところ、要するにこの青色があって、この北側部分です。ここの部分にあります。その下のＡ棟１階平面図というものがありますが、この１階の部分で、行政サービスコーナーの赤枠がありますけれども、その矢印の少し左斜め上に黒いぎざぎざの部分、これが駐輪場です。","voiceIndex":25,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"もう少し朝だけや夕方だけでも融通がきくような駐輪場というものが確保できないものなのかなと思ったのですが、その辺の融通策があるのでしょうかというのが１点です。それから、寄付を受ける公共公益施設というのがあるのですが、これは何か決まり事はあるのですか。それともできるにあたって、区の要望や所管もいろいろあると思うのですけれど、区の要望を踏まえた形で決められるものなのか。","respondent":"稲田都市開発課長","answer":"そういうものの中で、こういう地域貢献施設が具体的には区のほうとしてはあったほうがいいなというところで、再開発組合等々と協議をして、ではこれぐらい、あれぐらい。では、これでいこうかというようなことで決まっていくという状況です。","voiceIndex":29,"id":"exchange-009"}]},{"id":"topic-02","title":"平成２９年度ウォームビズキャンペーンの実施","agenda":"平成２９年度ウォームビズキャンペーンの実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"室温１９度ということを目途にということなのですけれども、部屋によっても違うと思うのですけれども、そのためには大体エアコンは何度ぐらいの目安になるのかと、どのように呼びかけをするのでしょうかということをお伺いします。","respondent":"小林環境課長","answer":"ただ、その設定する、感知する場所によって１９度が適切かどうかというような判断は多少変わってくるかというふうに思っております。部屋の中にある温度計を見ながら、１９度に細かく調整していくということが必要なのかなというふうに思っているところです。","voiceIndex":36,"id":"exchange-010"}]},{"id":"topic-03","title":"シェアサイクル事業の開始","agenda":"シェアサイクル事業の開始","exchanges":[{"speaker":"横山委員","kind":"質問","question":"２点質問します。２点目なのですけれども、こちらの区内のモデル周遊コースのようなものは想定されているのでしょうか。それを例えばパンフレットですとかホームページ等で周知・告知していったりするということなど、何かお考えがありましたらお聞かせください。","respondent":"今井土木管理課長","answer":"次にモデル周遊コースですが、こちら、運用のほうはやはり文化観光課と連携して行うということにしておりまして、観光振興協議会などでもショートトリップ推進部会という部会の中で、今後、自転車を活用した検討を進めていきたいというお声もありますので。","voiceIndex":43,"id":"exchange-011"},{"speaker":"横山委員","kind":"質問・要望","question":"先行自治体との比較ですとか、そういったところも、うまく広域化とともに進めていただきたいと思います。文化観光課との連携で進めていくというお話で、かしこまりました。こちらも、やはりモデルのコースですとかショートトリップ推進部会で検討していくということだったのですけれども、うまく周知のほうを連携して進めていただきたいということで、ご要望だけさせていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"コストの件です。ドコモとの役割分担になっているのですが、初期投資は品川区中心で、運営の費用はドコモなのかなと思うのですが、それがどういう形になっているのでしょうか。それと、収入が入ってくると思うのですけれど、その収入の配分というのは、どういう配分になってくるのでしょうか。持ち運びしていくのですかという形をどう考えられているのですかということ。だけれども、そこだけなのか。","respondent":"今井土木管理課長","answer":"それから４点目の設置ポートですけれども、やはり今後スタートしていくのは、民間の方にもご協力していただく形で進めていきますけれども、今はやはり区が管理しているところで、まずは自分たちでやってみませんと、なかなかメリット、デメリットもご説明できませんので。","voiceIndex":47,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"１点目のコストの件ですが、これはドコモのほうでもうけがなかった場合、品川区は補助するということはあり得るのでしょうか。その考え方をお聞きします。それと、品川区でできることということなのですけれども、確かに品川区の持ち物であって、今までも推進してきたというところがありますが、文化観光課とのコラボで一緒にやっていくのでしょうが、検証する際に観光という視点だけだとやはり……。","respondent":"今井土木管理課長","answer":"やはり、これは広域連携をして、なるべく広域連携をすることで、例えば大田区境、港区境、そういうところにもそれぞれの区のほうで置いていただく中で、自転車でどう行くかは別ですけれども、大田区から今ずっと進めれば江東区までつながるような考え方ですので。","voiceIndex":49,"id":"exchange-014"},{"speaker":"西本委員","kind":"確認","question":"再度、確認です。初期投資だけを品川区ということなのですが、これは採算が合うからドコモが手を挙げたかどうかはわからないのですけれど、もしかしたらマイナスになってしまう可能性も出てきた場合には、区としてはどういうふうな態度をとられるのかというふうな思いがありますので、その考え方をお聞かせください。１点目だけ、お願いします。","respondent":"今井土木管理課長","answer":"別事業者の参入というのも、中国なども含めてありますので、今後どういうふうな中で展開していくかということで、まずは社会実験という形で進めながら、状況に応じて対応していくものだというふうに考えております。","voiceIndex":51,"id":"exchange-015"},{"speaker":"安藤委員","kind":"確認","question":"ドコモ・バイクシェアなのですけれども、事業実績といいますか、どれくらいの自治体で実施実績があるのかお伺いしたいのと、あと料金設定ですけれど、これは消費税別ということですかねという確認と、あと他区と比べてこの利用料金というのはどんな感じなのか。料金というのは、ドコモが決めるのか、区が決めているのか、そこら辺です。お伺いしたいと思います。","respondent":"今井土木管理課長","answer":"利用料金につきましては、私どもも種々検討いたしましたけれども、今後広域連携していくという中では、やはり同じ料金体系で進めるということで、私どもの判断で先行自治体と同じ料金ということで決定いたしました。","voiceIndex":56,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"サイクルポート設置場所の基準や考え方を教えてください。それと充電の件です。非常に便利な乗り物で、私も使っていますけれど、使ってくるとだんだん充電が短くなったりするのですが、これはどういうシステムなのかなというのをお伺いしたいと思います。","respondent":"今井土木管理課長","answer":"大田区に整備のポートを持っておりまして、そちらのほうで行うと聞いております。フル充電したときには、平たんな場所であれば持続可能距離が５４キロと聞いておりますので、区内の今の面積を考えますと、一定の期間は十分ご利用いただけるというふうに考えております。","voiceIndex":58,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"そうですか。わかりました。目的にもかかわってくると思うのですけれども、このメーンの利用者の想定を、区としては観光客を考えているのか、昼間人口、ビジネスマンの方なのか、それともここに住んでいる区民の方なのか。区としては、どの辺を一番ターゲットに考えているのかと、そこら辺をお伺いしたいのですけれど。","respondent":"今井土木管理課長","answer":"先ほども買い物という話もありましたけれども、日常利用につきましては、やはり自宅のそばに返却のポートがなければなかなか使えないものですので、まずは日常というのは、今後ポートを増やしていった中で活用されていくものだというふうに考えております。","voiceIndex":60,"id":"exchange-018"},{"speaker":"新妻委員","kind":"質問・要望","question":"今回、社会実験ということもありますので、まずはやっていただいて、どういう成果があるのかというのを検証していただきたいと思いますが、広域になるというところが大きな一つのポイントかとも思うのですけれども、例えばちょっと所管が違うので要望だけしますが、例えばしながわ水族館、また他区の施設、区内でもそうですが、行くことで、あえてこの自転車で行く中での、回る中で。","respondent":"今井土木管理課長","answer":"２点目につきましては、既に先行自治体も、逆に利用した人がそこのお店に行くと例えば食べ物が５０円引きになるなどのサービスをして、ポートの設置とともに集客力に結びつけている店舗もありますので、今後またいろいろな所管と連携してまいります。","voiceIndex":63,"id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"自転車のデザインや形というのは、この写真のとおりなのでしょうか。広域ということで、それは全て統一ですということで、よろしいのでしょうか。","respondent":"今井土木管理課長","answer":"ただ、現時点で、２９年度は自区内運用ですので、平成２９年度は、後輪の巻き込み防止のカバーのところにもうばっちり品川区のシェアサイクル事業ということと、あと「わ、しながわ」というふうなデザインを入れながら。","voiceIndex":66,"id":"exchange-020"},{"speaker":"筒井委員","kind":"質問","question":"形はこれということで、多い荷物を運ぶにはちょっとかごが少ないのかなという。後輪のカバーのところに、「わ、しながわ」と入れているということなのですけれども、先ほどコストの話が出ましたけれども、最終的にはこのドコモ・バイクシェアがお考えになることかもしれませんけれども、ここに広告を載せたりするということもあり得るのかなと思うのですけれども、その点、ご見解はいかがでしょうか。","respondent":"今井土木管理課長","answer":"広告収入のことですが、実は、運営収入の中で運営会社が占める多くの収入はそちらですので、ほかの広域連携になりますと、「わ、しながわ」と書いて、それがほかの区に行くのはなかなか難しいですので、３０年度以降の自転車のときには、ここのところには広告収入。","voiceIndex":68,"id":"exchange-021"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"何点かお伺いしたいのですけれど、僕の聞き間違いだったらあれですけれど、先ほどの最初の説明で、事業主体が品川区で、品川区が自転車とラックを購入するという話だったのですけれど、これで自転車は最終的に２９年度は１８箇所、アシスト自転車が２００台以上なのですけれど、この２００台というのは、品川区としては財産になるものなのですかということが一点と、最初のこの社会実験のときは。","respondent":"今井土木管理課長","answer":"それから水族館ということもありましたけれども、子どもが乗れるようなチャイルドシートつき自転車ですとか、あとスマートフォンを設置する場所ですが、来年度以降になるかどうかわからないのですが。","voiceIndex":71,"id":"exchange-022"},{"speaker":"いながわ副委員長","kind":"意見","question":"自転車が増えれば増えるほど、それは恐らくポートでないところにとめて帰るというのもあるのですけれど、一番心配なのは、そこにとめておいて、自転車の撤去の車が来て、それを載せていって八潮なりどこかに持って行かれてしまうというケースも僕はあると思うのですけれど、そういうのは何か連携というか、この赤いドコモのシェアサイクルはそのままにしておいてくださいなのか。","respondent":"今井土木管理課長","answer":"撤去した後は状況に応じましてドコモ・バイクシェアが利用者の方にかわって取りに行くということも、可能性としてはほかの自治体で行われておりますので、それも含めての運営というふうに考えているところです。","voiceIndex":73,"id":"exchange-023"}]},{"id":"topic-04","title":"交通安全宣言５０周年記念「しながわ交通安全フェア」の開催","agenda":"交通安全宣言５０周年記念「しながわ交通安全フェア」の開催","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"近年、自転車の深刻な事故などが増えているので、自転車も走行ルール、逆走ですとかちょっと見られますので、そういったことが啓発できるよう、啓蒙できるような展示ですとか、あるいは自転車保険というものを、やはりいざ事故が起きてしまった場合などは大事だと思うので、そういった周知といったこともぜひこの中にあるといいなと思うのですけれども、いかがでしょうか。","respondent":"桑波田交通安全担当課長","answer":"警察署のほうにも協力いただきまして各展示ブース等も出しまして、そちらのほうでいろいろな交通に関する啓発等も実施していくように考えております。","voiceIndex":80,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひよろしくお願いします。自転車保険のことに関しては、意外にまだ入られていない方も多いのかなと思うので、ぜひそういったものがあって、加入できますよということで、周知できるようなブースなどを工夫できれば、ぜひお願いしたいというふうに思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-025"}]},{"id":"topic-05","title":"本日は防災対策に関することのうち、地域防災計画の改訂","agenda":"本日は防災対策に関することのうち、地域防災計画の改訂","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それと、やはりそういったところも大きく章立てをしてつくっていっていただきたいのですけれども、いかがでしょうかというのが１つです。それは、今回入れるということですよね。そこら辺がどのように充実、あと高層マンションの被害ですとか、コンビナートの火災ですとか、区内で起こり得る被害想定というものをどこまでされているのか、そこら辺についてはどうでしょうか。","respondent":"古巻防災課長","answer":"予防対策についてですけれども、予防対策についても十分に記載をするというようなつもりでおりますけれども、検討経過のところで記載させていただいている中で、備蓄の関係で、備蓄の充実をしていただくような啓発をしていくですとか。","voiceIndex":87,"id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"それから質問のもう一つは、新たにその間にあった災害ということですけれども、熊本地震の一つの教訓として、新耐震基準以降の住宅についてもなかなか厳しかった、倒れてしまったということがありますけれども、そうした点での１９８１年から２０００年築の住宅についても、やはり対策をとっていかないと人命が守れないというふうになったと思うのですけれども、そこに関しては。","respondent":"古巻防災課長","answer":"それからインフラ整備、インフラ対策といったところで、予防対策についても当然ふれていきますし、当然今の計画の中にもそういった記述はあって、区としても耐震助成などを進めているですので、そのあたりは十分対策を考えて区としても進めているというふうに認識しております。","voiceIndex":89,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"熊本地震のところは、今の品川区の耐震改修助成というのは、１９８１年以前ということだと思うのですが、それですと熊本地震の最新の教訓に対応できないのではないかというふうに思ったので、そこら辺を今、新たに対応していくということだったのですか。新ルート計画とは切り離していいですけれども、そこら辺ははっきりお答えいただきたいというふうに思います。","respondent":"鈴木建築課長、古巻防災課長","answer":"私のほうから、熊本地震で被害が出たというところの新耐震基準以降の建物についてのご質問についてお答えをいたします。基本的に品川区で行っている助成は、昭和５６年以前、旧耐震の建物について助成を行っていると。まさに熊本地震におきましても、なかなか職員の方が運営をせざるを得ないというような局面があったところが、やはり職員の手が回り切らなくなったり。","voiceIndex":91,"id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"航空機のところは、あらゆる想定ということですが、シンプルに伺っているのですけれど、別に新ルートは置いておいて、この航空機の事故と書いていますけれど、先ほどの想定の中には墜落事故も入っているのですよねという確認だけなので、お伺いしたいと思います。","respondent":"古巻防災課長","answer":"そういったことも含めて航空機あるいは飛行物体といったものが何らか地上に影響を与えるということを全体的な計画の中で対応するというのは、被害の想定というよりは、どちらかというと多分連絡体制でありますとか。","voiceIndex":94,"id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"町会の人がやるのですか。それから１－２のところには、１週間程度の備蓄というのがありますが、この中にローリングストックとあります。２－３で男女共同参画の方々に意見を伺いということなのですが、それも必要だと思いますが、いろいろな災害の中で女性ならではの視点で考えなければいけないということの蓄積、情報収集されているところもあるので、それらはまとめられているのでしょうか。","respondent":"古巻防災課長","answer":"ですので、それぞれ思いといいましょうか、要配慮者の受け入れでありますとか、ペットの受け入れですとかといったところなどがありますけれども、例えば要配慮者の受け入れに関しましては、今現在行っております個別計画の作成の支援の中で。","voiceIndex":97,"id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"なので、これに入れ込めるのかどうかわかりませんが、この防災計画の中にそれも一本入れないといけないのではないかというふうに思っておりますので、すぐにとは言いませんけれども、現状を踏まえながら、実際必要なことをまず見直しを図っていただきたいと考えています。なので、この初期の体制を何とか研究を進めていただきたいと思うのですが、最後にお聞きしたいと思います。","respondent":"古巻防災課長","answer":"今ご指摘いただいた点は、やはり非常に必要なことであるというふうには認識しておりますので、基本的な考え方については、地域防災計画の中にある程度記述しようかと思いますけれども、具体的なそういったマニュアル的な部分になるかと思うのですけれども。","voiceIndex":99,"id":"exchange-031"},{"speaker":"新妻委員","kind":"質問・要望","question":"そのことをまた区民にも、まずは自分の命は自分で守るんだというところがまず前提にあるのだというところをしっかりと周知をしていただきたいと思います。具体化を促進するというふうになっておりますけれども、この中で、促進をしていただきますが、促進ができているのかどうかというのは、区はどうやって確認をしていただくのでしょうか。そこをお聞かせいただきたいと思います。","respondent":"古巻防災課長","answer":"避難所と運営マニュアルの具体化の促進ですけれども、今お話があったとおり、現状におきましては、マニュアルもそうですし避難所ごとに温度差があるということも、区は認識をしていますので、まずマニュアルに関しましては。","voiceIndex":102,"id":"exchange-032"},{"speaker":"新妻委員","kind":"質問・要望","question":"よろしくお願いします。自分が飼っている犬・猫が主になるのでしょうが、その犬・猫を連れてきてのペット同行の避難訓練をぜひやっていただきたいと思いますが、いかがでしょうか。減ったら追加、減ったら追加。家庭の中でのトイレの確保というところ。そういう具体的な各それぞれのご家庭でのトイレを確保するということの必要性もあわせて訴えていただきたいと思いますが、いかがでしょうか。","respondent":"古巻防災課長","answer":"ローリングストックの周知につきましても同様で、今年度は地域防災計画のほうの修正をしていきますけれども、当然「わが家の防災ハンドブック」につきましても今後修正をするというふうなことを考えておりますので、そういった中で。","voiceIndex":104,"id":"exchange-033"},{"speaker":"大沢委員","kind":"質問・要望","question":"表記のことで伺いたいところなのですが、方向性のところの２－１、２－２、２－３とありますが、２－１の１番目の「『受援計画』を地域防災計画に追加する」。２－３で「意見を伺い、計画へ反映する」というのですけれども、この計画なるものはどのようなものか。別の計画なのか、それとも当然考えられるのはこの地域防災計画でしょうけれど、あえて「計画」としたのでしょうか。","respondent":"古巻防災課長","answer":"検討結果の２－３の「意見を伺い、計画へ反映する」の「計画」につきましては地域防災計画のことです。特に意図があって計画というふうに縮めたものではありませんけれども。","voiceIndex":107,"id":"exchange-034"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"確認というか、どういうイメージかだけ教えていただきたいのですけれども、１－３、黒丸「円滑な災害対応に向けた災害対策本部の再編を進める」。緊密な連携をとるというけれど、中身は同じではないのかなという部分で、同時に２つが存在していくのか、それともこちらで災害対策受け入れも全部終わりました。それはこれから議論されるのかもしれないですけれども、今の現段階でのイメージを教えてください。","respondent":"古巻防災課長","answer":"ちょっと説明がうまくいっていなかったでしょうか。","voiceIndex":115,"id":"exchange-035"},{"speaker":"いながわ副委員長","kind":"質問","question":"今のを聞いていると、何か多少リンクして、ここだけちょっと緊密に連携をとりましょうというイメージに聞こえてきてしまって、立ち上がったときには災対本部とこの復興本部の人というのは、兼務することになるということでいいのですか。要は、密にするというのは、当事者がやっているわけですから、密も何も、何かぴんとこなかったので質問させていただいたので。わかりますか、僕の言っている意味。","respondent":"古巻防災課長","answer":"震災復興に関しましては、やはり災害の規模がある程度大きくなって、計画的に復興を進めていかなければならないというふうな判断があったときに、復興本部を立ち上げていくというような形になろうかと思いますので。","voiceIndex":117,"id":"exchange-036"},{"speaker":"いながわ副委員長","kind":"質問","question":"それを加える、推進するために設置すると書いてあるということは、要は今はないわけではないですか。この文章で見る１行だと、その際にはもともとある災害対策本部と連携を図っていきましょうよというイメージだと。それを、恐らく今回の修正で、こういう案件が出て、これからそれをもんでいくのかなという思いなので、今お答えができないなら無理して答える必要性もない……。","respondent":"古巻防災課長","answer":"震災復興に関しては、今も既に現行の計画の中に記載がございまして、ここのマニュアルもつくってありますし、震災復興本部の設置についても現行の計画の中できちんと記載があるものですので、改めてここに新しく追加をするというイメージではなくて。","voiceIndex":119,"id":"exchange-037"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"例えば建設防災協議会は緊急警戒をしなければいけないので、早く警戒するべき道というのは、建防が全てやるというのは結構明記されているのです。ただ、例えばそうではない、この間、建設４団体が協定を結んだと言っていますけれど、では、その人たちの役割というのは何なのですかといったときに、そういうのをしっかり明確にできる、わかりやすい計画にしていただきたいなと思いますが、いかがでしょう。","respondent":"古巻防災課長、曽田災害対策担当部長","answer":"わかりやすい計画にということは当然意識しておりますので、震災復興マニュアルにつきましても、今後改訂をしていくというような形になろうかと思いますので、中できちんと明確にしていくということを意識してまいりたいと思います。したがいまして、多分ご指摘のように同じようなメンバーになろうかと思いますけれども、それぞれ組織の目的が違いますから、やっていることが違いますから、それはやはり整合させていくという観点から。","voiceIndex":121,"id":"exchange-038"}]},{"id":"topic-06","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それとあと糸魚川市のところは、飛び火がかなり怖かったという話を聞いていますので、やはりどんな状況だったのかということも、現地でぜひお話などを聞かせていただきたいと思いますし、そういった教訓を踏まえた上で、防災まちづくり、これからのまちづくりということをしていると思うのですけれども、先ほど説明がありましたけれども、そういったまちづくりをしていく上での住民参加の状況ですとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-039"},{"speaker":"新妻委員","kind":"質問","question":"長岡市ですが、中越市民防災安全士会がありまして、防災士の資格がここで取れるということで、これは事業として市がお金を出しているのだと思いますけれども、ここら辺の取組みを少しお伺いしたいと思います。長岡市の資料の後ろのほうです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-040"},{"speaker":"新妻委員","kind":"確認","question":"安全大学、そうです。それと、富山市はシェアサイクルもこれから進めますので、ちょっとまち並みが品川区と全く違うと思うのですけれども、自転車レーンの整備、自転車の走行にあたっての道路整備がどのくらい進んでいるのかというのをちょっと確認したいのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4214#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":56955,"voices":148}},{"id":"h29-20170926-9","meetingId":"h29-cm09","date":"2017年9月26日","dateIso":"2017-09-26","committee":"文教委員会","time":"午前１０時００分～午後 ２時５８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を57件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"学校改築事業の進捗","agenda":"学校改築事業の進捗","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"後地小学校の図面のほうでお聞きしたいのですけれども、１階のところで、左側に広場門というのがあると思うのですが、今現在だとこちら側から生徒の登校などもしているという話を聞きまして、改築したときにこの広場門は生徒が使えるものになるのかどうか伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"管理スペースに関しましては、例えば職員室等は校庭が見晴らせるような形で何かアクシデントがあったときに、教員がすぐ飛び出していってすぐ対応するなど、それと同じような形で保健室等を１階に置くことで。","voiceIndex":5,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、生徒の通学の際に正門と北門からだけになるという考えでいいのか、改めてお聞かせいただきたいと思います。先ほどご説明がありました体育館を「後地ひろば」とするということで、コミュニティの場所にするということなのですが、これはそうするとどういった活用の仕方になっていくのか、イメージが湧かないものでご説明いただければと思います。","respondent":"篠田学校計画担当課長","answer":"具体的に、例えば、休み時間等の開放ですとか、運用面については学校の中でさまざまなあろうかと思うのですけれども、こちらのほうは今後学校運営の中で検討していくことを想定しているものです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"後地小学校のことを中心に聞きたいのですけれども、全体的に学校改修とか改築とか、幾つかこれからやっていかなければいけないと、そういう予定があると思うのですけれども、今計画として、４校を示していただいたわけですけれども、それ以外にどのくらい残っていて、基金も含めてずっと積み立てをしているという状況もありますので。","respondent":"篠田学校計画担当課長","answer":"ただ一方で、学区域はなかなか勝手に変えることは難しい部分ですので、そういった部分でどういった対応ができるかということを考えたときに、例えば学校生活もさまざまありますので、後地小学校のほうで受け入れられる可能性についても、今後想定した上で。","voiceIndex":9,"id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"たくさん質問させていただきましたけれども、ぜひ改築計画をできるだけ速やかに出していただいてわかるようにしていただきたいなと思いました。もちろん子どもたちは注意するでしょうけれども、とにかく２階のこのあたりの混雑というか、そういうのがちょっと心配かなと思って取り上げて質問したので、ぜひ安全性が担保されるようにお願いします。蛇足ですけれども、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"こんの委員","kind":"質問","question":"私のほうからも、後地小学校の改築のこの図面のほうから何点かお聞きしたいと思うのですが、まずコンセプトの４点目に安全で安心な学校づくりの中の二つ目のポチですね。いわゆる冷暖房の設置はどう考えているのかというのが２点目です。後地ステップの上がそうなるのですか、この図面でどう見たらいいのかというのを教えてください。","respondent":"篠田学校計画担当課長","answer":"あわせまして、体育館の空調に関してですけれども、現在のところ、区の学校の施設としましては、当初から冷暖房の設置というのは今のところ学校の仕様にはございませんので、今回の後地小学校に関しましても、当初から冷暖房を入れる予定は今のところございません。","voiceIndex":12,"id":"exchange-005"},{"speaker":"こんの委員","kind":"確認","question":"確認です。ただ、今ご説明いただいたように、空調の配管を設置しておくということで、今後の対応が可能になるということがわかりましたので、それは本当にありがたいことでありますし、今後もそういう考え方で区の改築される学校を整備していくということでいいのか、３点確認ですが、お願いいたします。","respondent":"篠田学校計画担当課長","answer":"体育館の空調に関しましては、委員からお話があったとおり、ご説明申し上げたとおり配管だけは通しておくという状況ですので、状況によってはその配管を活かして冷暖房が設置できるように設計しております。","voiceIndex":14,"id":"exchange-006"},{"speaker":"こんの委員","kind":"確認","question":"参考までに進捗状況を一つだけお伺いしたいのですけれども、今、大井第一小学校で人工芝の工事が行われておりますけれども、これは過去の文教委員会でもご報告があった事項だと思いますが、いつ頃完成になるのでしょうか。ちょっとこれだけ確認をさせてください。","respondent":"品川庶務課長","answer":"大井第一小学校の人工芝ですけれども、秋ごろを今予定しております。","voiceIndex":16,"id":"exchange-007"},{"speaker":"こんの委員","kind":"質問","question":"もう間もなくということで、これまで運動会はいつも秋だったのを今度春にしたので問題はなかったと思うのですが、例えば、校庭で行う授業は全部体育館でやっていたということだったのでしょうか。その辺を教えてください。","respondent":"品川庶務課長","answer":"人口芝の工事をしている期間ですけれども、基本的には体育館等を利用しておりまして学校内でいろいろな工夫をしながら体育等を行っているものと考えております。","voiceIndex":18,"id":"exchange-008"},{"speaker":"渡部委員","kind":"質問","question":"城南小学校についてですが、説明会に結構な方がお見えになっていて、地域の方々が喜んでいるという話を聞いたのですが、城南小学校で出た埋蔵文化財は、学校の中で展示室みたいなものをつくって、今後展示するということでよかったのでしょうか。同様に、鮫浜小学校はこれからプロポーザルということですけれども、想定としては何クラスと考えているのかというところもあわせて教えてください。","respondent":"篠田学校計画担当課長","answer":"こちらにつきましても、湾岸地域に大きなマンションの開発が多数進んでいますので、今のところ私どもがつかんでいる範囲では、鮫浜小学校の学区域内で多数の大きな建物が建つ見込みはないのですけれども、ただ周辺の地域においてかなり多くなっていますので。","voiceIndex":20,"id":"exchange-009"},{"speaker":"渡部委員","kind":"質問","question":"できれば、区内の児童などにも機会があれば見てほしいなという思いで質問をしまして、答えが何にも返ってこなかったので、それはできないのだなというところで、今、課長がおっしゃっていただいたようにその学校の学区域でという考え方を当然していかなければならないのだけれども、やはり品川区内に、すごく大きな建物がどーんとできて、それがその学区域。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-010"},{"speaker":"高橋（し）委員","kind":"質問","question":"特別支援教室が２階ですけれども、教室をここに置いたお考えを伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"後地小学校の特別支援教室につきましては、こちらの図面では２階の真ん中あたりに今、実施設計において考えているところです。","voiceIndex":23,"id":"exchange-011"},{"speaker":"高橋（し）委員","kind":"意見","question":"現在、他の学校の特別支援教室は、何とか教室をつくり、確保したということで、環境的には今お話があったように、他の生徒、児童と一緒にではなく、ちょっと外れる場所にあったりする所もあるので、今お話になったようなコンセプトで他の児童と交流できるような形でつくっていただくのは大変ありがたいので、ぜひそのお考えで進めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":25,"id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"先ほど聞き忘れましたけれども、普通教室の２階のところのスペースが教室の前にあり、一方、３階、４階にないと思いますが、この部分の活用法は、実際どうなのかということ、あと先生などからお話を聞くと、プールのろ過器がなかなかその担当になると大変だというお話を聞きまして、今回ろ過器が最新のものになることで、あまり負担がなくなるというお話を聞いているのですが。","respondent":"篠田学校計画担当課長","answer":"申し訳ありません。スペースが２階にあるけれども、３階にないというのは。","voiceIndex":26,"id":"exchange-013"},{"speaker":"松永委員","kind":"確認","question":"１点だけちょっとお伺いしたいのですけれども、確認でトイレについてなのですが、以前学校等には洋式、和式があり、和式については一つ設置し、その他は全部洋式化という話をされておりました。そこで、その割合と誰でもトイレのような設備はあるのか、確認だけさせてください。","respondent":"篠田学校計画担当課長","answer":"誰でもトイレですけれども、１階に入っていただいた体育館の下にありますちょっと広目のトイレを誰でもトイレといって、逆に言うとバリアフリーのトイレを設置することを予定しているものです。","voiceIndex":30,"id":"exchange-014"},{"speaker":"松永委員","kind":"質問・要望","question":"１階部分にということで、みんなが使えるようになるのかなと思います。特別支援教室の前にはなく、１階だけということですか。和式については、フロアごとに全部一つずつつけられるのか、再度質問させていただきたいと思います。","respondent":"篠田学校計画担当課長","answer":"和式ですけれども、各フロアに一つずつまでは想定しておりませんで、１階に一つ入れるということを考えてありますけれども、ただ詳細な部分は、今実施設計の段階ですので、まだ最終的な確定ではないです。","voiceIndex":32,"id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"特別教室の関係で聞きたいのですけれども、今までの説明を聞いていると、１・２年生は２階で、３・４年生が３階で、５・６年生は４階という配置かと思ったのですけれども、２階には家庭科室と図工室があるのですけれども、低学年でもやはり雰囲気が変わったりすることも大事だと思うので、図工室の活用などがあると思うのですけれども、家庭室の活用はあるのですか。","respondent":"篠田学校計画担当課長、大関教育総合支援センター長","answer":"確かに委員ご指摘のとおり家庭科室に関しましては、場合によっては３階等に上げたほうが使いやすいため、上げるということは想定されるものですので、いずれにしても、現在詳細について設計をしている段階であり。学校が現場の事情に応じて、また工夫していく場面もあろうかと思いますが、基本的にはこの考え方で小学校にとって使い勝手のいいスペースでの設置を考えております。","voiceIndex":34,"id":"exchange-016"}]},{"id":"topic-02","title":"学事制度審議会第１０回～１２回の報告","agenda":"学事制度審議会第１０回～１２回の報告","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今、各回について説明いただいたのですが、第１２回の分はまだ議事録要旨が公開されておりませんので、第１２回目のところで学校選択制についてどういった意見があったのか、もう少し詳しくご説明いただければと思います。いろいろな方にも影響していきますので、やはりできるだけ長く、例えば１カ月ぐらいはとったほうがいいのかなと思うのですが、これから１カ月間の延長ができるのか伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"パブリックコメントですけれども、委員から２週間では短いというお話をいただいたのですが、中間答申をいただきました結果につきましては、今週の金曜日に答申をいただければ、その後できるだけ速やかにホームページ等にはその報告書をアップしていく予定です。","voiceIndex":43,"id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり、こういった制度をもとに戻していく、学校と地域と保護者、子どもと教育を充実させていくというためにも、学校選択制というのは中止したほうがいいと思いますけれども、改めて伺いたいと思います。そのための説明会などもぜひやっていただいて、多くの方に意見を求めていただければと思うのですけれども、説明会の開催をぜひやっていただきたいと思うのですが、いかがでしょうか。","respondent":"篠田学校計画担当課長","answer":"あわせまして、中間答申の骨格にわたる部分、概要版といったような形のリーフレットのようなものも作成する方向で整理をしておりますので、あえて説明会を開催する予定はございません。","voiceIndex":45,"id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"選択制については効果があるという話でしたけれども、やはり学事制度審議会の中でも地域のつながりが弱まっているとか、保護者がお客さん化してしまったのではないかという声もありますので、やはり、選択できるから選択するという方もいらっしゃると思うのです。説明会をやったほうがいろいろ質疑もできて理解が深まると思いますので、ぜひ検討していただきたいと思いますが、改めて伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"繰り返しになってしまいますけれども、わかりやすくつくりつつ、またリーフレット等も作成して、皆様方にお配りしたいと考えておりますので、説明会については今のところ開催する考えはございません。","voiceIndex":47,"id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"ですから、少なくとも要旨でしか出せないのであれば、最低限そこは準備をしていただきたいと思っています。それについて改めて伺いたいと思います。この件について、教育委員会の考え方も含めて中学校の学校選択をどういうふうに思って、こういう発言になっているのかというのがわからないので教えていただきたい。制限するという方向性が出てきているのは事実かどうか、その辺について伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"最初に議事録の公開のタイミングなのですけれども、もともと学事制度審議会に関しても非公開で出していただいてありますので、議事録の公開も要旨で行なわせていただいております。","voiceIndex":49,"id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"いろいろなやりとりの中で、そういう制限はしない方向で今までどおりということになっていくということで了解していいわけですか。そういう状況が今あると思うのですけれども、まちの中の意見が町会長をはじめとするいろいろな委員の発言に出ているのではないかなというふうに思っているのですけれども、そのあたりの認識というのはどうですか。","respondent":"篠田学校計画担当課長","answer":"そういったことは今申し上げたような形にもつながっているところですので、きちんと対応されているものと考えているものです。","voiceIndex":53,"id":"exchange-021"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっと最後のところがよくわからなかったのでもう一度伺いたいのですけれども、私はまちの中の意見と町会長たちの意見は、同じで凝縮されて出ているのではないかなと思っているのですけれども、そういうふうな捉え方をしているのか、していないのかで質問したつもりなのだけれども、ちょっとよくわからなかったので申しわけないですけれども、もう一回お願いします。","respondent":"篠田学校計画担当課長","answer":"時代との関係で、時代だけではないですけれども、当然時代の推移の中での変化もありますし、先ほど申し上げたとおり教育委員会として新たに品川教育ルネサンスに取り組んでいて、その中で地域との関係を重視しているというのもありますし。","voiceIndex":55,"id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"したがって、私はやはり説明会というのは、開催する必要があるというふうに思うのです。したがって、もっと堂々とまちの中に出て、こういうふうに思います、説明しに来ました、ぜひ聞きにきてください、ご意見をくださいという説明会を、学校選択制を推進している側にしてみれば、やらないといけないのではないかなと思うのですけれども、その点についてどうですか。","respondent":"篠田学校計画担当課長","answer":"確かに説明会という手だてもあろうかと思いますけれども、現時点においては、パンフレット、リーフレット等によってわかりやすくご説明することで区民の皆様方にはご理解いただけるものというふうに考えているところです。","voiceIndex":57,"id":"exchange-023"},{"speaker":"南委員","kind":"意見","question":"そういう経験をたくさんされていらっしゃると思うのであえて言いませんけれども、やはりさっきも言いましたけれども、区がこれからも進めていく、私は反対だからやめてもらいたいと思うけれども、やっていくというのであれば、もっと堂々と区民に説明をするべきです。ぜひ説明会をやるべきだということを強調して終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":59,"id":"exchange-024"},{"speaker":"渡部委員","kind":"質問・要望","question":"全く違うと思います。説明会を求められたって何の説明もできない。さあどうぞで、何の説明会ですかという話になるので、そういう人を惑わすようなことは一切やらないほうがいいです。その中でやっていただければいいのですけれども、そこで委員の方々が集まって、最終答申が若干の変更となり、何らかの変更が加わることがあるかもしれないというのは、その確認だけ一つとらせていただければと思います。","respondent":"篠田学校計画担当課長","answer":"説明会の関係ですけれども、今委員からご指摘があったとおり、審議会の答申を受けるというのは事務局の立場として受けるものです。","voiceIndex":60,"id":"exchange-025"},{"speaker":"渡部委員","kind":"確認","question":"確認いたしました。町会の方々にもよく話しますが、要は選択制があるから町会行事に来ないのだとか、地域が割れるのだというのは全く別な話でありまして、それはやはりそこに住まわれる方々の意識の問題ですとか、そこに大きく起因するものがあるということだけあえてこの場で申し上げさせていただいて、また町会の総務部長としても、そういう話は毎回していますので、そこはしっかりと申し伝えします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-026"}]},{"id":"topic-03","title":"平成２９年度全国学力・学習状況調査の結果","agenda":"平成２９年度全国学力・学習状況調査の結果","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"全国学力テストの結果ですけれども、私が懸念しているところでは、やはり過度な競争教育につながるのではないかという懸念があるのですけれども、その点、どうされているのか。そして、この調査が実際どのように活かされていくのかというのがなかなか見えにくいのですけれども、今後の活用について伺いたいと思います。","respondent":"熊谷指導課長","answer":"学校独自にどのように改善していくのか、授業はどうするのか、またどんなところが苦手なのか、そういったことも確認しながら授業改善を行っていると同時に、現在品川区立学校教育要領を策定していますが、その中で、評価部会、国語、算数、数学部会等でこれらを活用して。","voiceIndex":67,"id":"exchange-027"},{"speaker":"のだて委員","kind":"質問","question":"それぞれの学習状況というのは判断できると思うのですけれども、その上で全国学力テストをやっていくという意味がよく見えないので、そのところを伺いたいと思います。学び合いの教育によって教育効果があるというところでやっていくことが私はいいと思っているのですけれども、その点の考え方も伺いたいと思います。","respondent":"熊谷指導課長","answer":"だからこそ、それをやることによって子どもたちの学力が高まっていくということで、この調査を用いて話し合い活動、学び合い活動はどういうふうに取り入れられているのか、そういったことも確認することができますし、改善につなげていけるということで。","voiceIndex":69,"id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"その辺の数字の評価と、何て言ったらいいのか、こういう数字に甘んじていていいのかということと、そもそも数字のレベルが全然わからないので、全く無責任に言っているのかもしれないのですけれども、その辺について専門家から見たところの状況というのはどういうことなのかを改めて伺いたいと思います。","respondent":"熊谷指導課長","answer":"算数・数学の結果ですけれども、国語や算数のＡに比べると半分ぐらいで、その中でも品川区は東京都や全国と比較していいほうなのですけれども、これは難しい問題が出ているのかというと、決してそうではなくて。","voiceIndex":71,"id":"exchange-029"},{"speaker":"南委員","kind":"質問・要望","question":"４月１８日にテストをして、９月に入ってこういう結果が来ているわけですね。そういう点で、どういうふうに指導というのを、何て言えばいいのか、全体的な教育のレベルと、このテスト時のレベルと、今の状況というところをどういうふうに学校として、先生方としてつかんで、具体的に指導に活かすということはどういうことなのかなというのがちょっとわからないので教えていただきたいと思います。","respondent":"熊谷指導課長","answer":"ということは、やはりこの６年間、また中学校の場合は９年間、小学校の問題も出ているのですけれども、とすると、どこまでできているのか、昨日の問題、１週間前の問題ではなくて、これまでの経験、しっかり学力。","voiceIndex":73,"id":"exchange-030"},{"speaker":"南委員","kind":"質問・要望","question":"たしか何年か前の文教委員会でも富山県とか石川県とか福井県に教育の文教委員会で視察に行って、かなり学力が高い地域の教育行政について視察したことがあったのですけれども、ここにも出ているように、秋田県も含めて、やはり北陸地域がかなり学力が高く出ているというところなのですが、この間も報告していただいた子どもたちの家庭学習の時間が。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-031"},{"speaker":"渡部委員","kind":"質問","question":"だって、１００点をとれる問題を出しても、それが５０点しかとれないのだったら困ったになるぐらいだけど、ですから、表の見方としては、こうやって平均と比べてどうなのかとか、そういうことしか見ようがないと思うので、これはこれでいいし、あまり数字がどうこうというのではなくて、今後の品川区の教育にどう活かしていくかだと思うのです。","respondent":"熊谷指導課長","answer":"国の調査ですと、なかなか母体も変わってしまいますので難しい部分もあるのですが、区の調査なども活用しながら子どもたちの変容、それからどのように改善したのか、また課題は残ったのか、見取っていきたいと思います。","voiceIndex":76,"id":"exchange-032"},{"speaker":"こんの委員","kind":"質問・要望","question":"一緒に質問してしまうのですが、８番の考察のところで、先ほど口頭でご説明があった共通の解答率が高い子どもの中に、読書が好き、新聞を読んでいたということがありましたけれども、参考までに数字がわかれば教えていただきたいのですけれども、読書が何人ぐらいの子どもがしていて、１人何冊ぐらい読んでいるのか、新聞も同じように何人ぐらいの子どもで。","respondent":"熊谷指導課長","answer":"ですので、各学校には個人面談の際ですとか、また保護者会では個別に説明はしないのですけれども、全体で説明した上で、一人ひとりに封筒に入れてお返ししたりというようなことをとっている学校が多くあります。","voiceIndex":78,"id":"exchange-033"},{"speaker":"こんの委員","kind":"質問・要望","question":"読書についてですが、朝読、たしか朝１０分の読書時間というのは、今この活動はどうなっているのでしょうか。特に小学校で朝の１０分間の読書活動を何でもいいから１０分間読もうと。その何でもいいのは、たしか漫画系も含まれて、図書に触れる朝読という活動をたしかやっていたかと思うのですが、今どのような状況でしょうか。","respondent":"大関教育総合支援センター長、熊谷指導課長","answer":"帯で朝に読書、本に親しむという時間を各学校は工夫を重ねて続けているところです。ボランティアの協力を得て、読み聞かせの会を月に１回から２回設けている小学校も多くなっております。最初の保護者への働きかけということですけれども、例えば個人面談等で丁寧に説明していくということもありますし、またコミュニティスクールの校区教育協働委員会で。","voiceIndex":80,"id":"exchange-034"},{"speaker":"松永委員","kind":"質問・要望","question":"私からは、学校質問紙調査の結果概要についてちょっと伺いたいと思うのですけれども、１番の「よく行った」とか、２番、３番、４番とありますけれども、この差というのをちょっと教えていただきたいというのがあります。４番の「全く行っていない」という回答はあったのか伺いたいと思います。","respondent":"熊谷指導課長","answer":"こちらの学校質問紙調査は、校長先生が回答しているものですが、そういう中で、どうやって回答しているかと、その根拠となるのは日々の授業観察であったり、例えば、週ごとの指導計画、いわゆる週案と言われているものですが。","voiceIndex":83,"id":"exchange-035"},{"speaker":"高橋（し）委員","kind":"質問","question":"そこを改善するためになかなか特に小・中学校の同僚が少ないことがあるので、そういった点、つまり算数だったらここが教えにくい、数学だったらこうだというところをピックアップして、教員の研究会ではないですけれども、そういう指導のやり方を、ここはこういうふうにしたほうがいいという指導はどのような形で先生方にしているのでしょうか。","respondent":"大関教育総合支援センター長","answer":"月１回教科ごとに全教員が所属しております教育会の部会のほうでも今回の結果の分析は進めております。","voiceIndex":87,"id":"exchange-036"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、それが整理されたものというか、よく市販されている教え方を独自で研究しているようないろいろなものがありますけれども、区独自でそのようにやられているのでしたら、算数のこの分野はこういうのがあると例えば単元ごとにリスト化したものがあればいいと思うのですが、そういう積み重ねがきっとあると思うので、そういうものをリストアップしていく考えはあるのでしょうか。","respondent":"熊谷指導課長、大関教育総合支援センター長","answer":"また教材等についても今教科と専門部会の中で検討して、ちょうど教育要領が変わる時期でありますので、そこと重ねて今後お示ししていきたいというふうに考えております。その他、学習指導は毎月の研究会で行ったものにつきまして、教育総合支援センターのほうで集めて、教員が教育総合支援センターで閲覧をできるようになっております。","voiceIndex":89,"id":"exchange-037"}]},{"id":"topic-04","title":"平成２８年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"平成２８年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"ぷりすくーるのほうで、裏面の最後の評価結果のところで、幼保連携型認定こども園への移行に向けと書いてあるのですけれども、私はこのぷりすくーるが移行するということを認識していなかったのですけれども、これは今回新たにそうなったのか、またこれがもし移行された場合、変更される部分というのはどういったものがあるのか伺いたいと思います。","respondent":"横山品川図書館長、廣田子ども家庭支援課長、吉田保育施設調整担当課長","answer":"経験と申しましても図書館だけで働く経験だけではなく、そこの地域に合った状況というのを把握するために一定の時間数、昔専門職がいた時代は１０年。家庭あんしんセンターにつきましては、先ほどのご説明でも若干盛り込ませていただいたのですが。そちらにつきましては、管理運営費が上がったところで説明を申し上げたところですが、委託費用の増額と保育従事者家賃補助、キャリアアップ補助金。","voiceIndex":105,"id":"exchange-038"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろ昨年改善点として示された部分についてやられているということですので、しっかり改善できるようにしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-039"},{"speaker":"南委員","kind":"質問・要望","question":"ぷりすくーるのほうはわかりました。それと、その関係でですけれども、指定管理者制度ということで、いわゆる民間の方に図書業務をやっていただいているわけですけれども、そういう方々に当然福祉施設がつくられた作品、製品の販売を担っていただいていると思っているのですけれども、販売についてどういう位置づけであるのかということを伺いたいと思います。","respondent":"廣田子ども家庭支援課長、横山品川図書館長","answer":"スーパーバイザーにつきましては、イメージとしては臨床心理士であるとか、いろいろな状況で入所する子どもなどがおりますので、子どもの登校しぶりなどへの対応であるとか、お母さんたちもＤＶの経験をしていたりとか。指定管理者の方が販売というのを中心にしていないということで、図書館はもちろん無料でご利用いただくのですが、ブックカバーにつきましては実費をいただいているという形ですので、販売目的の利益業務ではありませんので。","voiceIndex":110,"id":"exchange-040"},{"speaker":"南委員","kind":"確認","question":"臨床心理士についてですけれども、指定管理が福栄会ということなので、当然福栄会のほうからそういう業務に携わる方を派遣するという形になるのだろうと思っているのですけれども、ちょっとそこだけ確認して終わりたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"今現在、福栄会が任用した臨床心理士が来ているのですけれども、非常勤で毎日いないというところで、そのあたりをもう少し手厚くしたらいいというようなご意見をいただいておりますので、福栄会にはそのあたりについて派遣してもらうように申し入れをしています。","voiceIndex":113,"id":"exchange-041"},{"speaker":"こんの委員","kind":"確認","question":"南委員の質問と少し重なる点もありますが、確認を含めてお聞きしたいと思います。家庭あんしんセンターについてですけれども、この中のファミリー・サポートに携わる方々の業務と、業務の中で利用者をサポートしながらいろいろな場面に携わると思うのですが、その中で利用者が本来の業務とは違うところでお困りだなと見えるような、相談を受けるような場面というのはあると思うのです。","respondent":"廣田子ども家庭支援課長","answer":"スーパーバイザーにつきましては、ひまわり荘のほうの改善点というところですけれども、臨床心理士そのものは今は非常勤で、福栄会の職員となっておりますので、相談に乗ってもらう。福栄会の中のことですので、相談に乗ることはできると認識しております。","voiceIndex":115,"id":"exchange-042"},{"speaker":"こんの委員","kind":"質問","question":"そうしたときにキャッチした情報を、見てどうすることもできない、そのサポートの提供会員がそこをどこかにつなげるのか、あるいは相談して、そこの家庭をその場で何か手当てができるようなところまでは、今この業務の中における指定管理の業務内容にはたぶん入っていないと思うのですが、その辺というのは、いろいろな状況があると思うのですけれども。","respondent":"廣田子ども家庭支援課長","answer":"具体的にそういうケースが上がってきたかどうかというところは把握していないところなのですけれども、提供会員が困る、実際に１対１でやることなので、困るようなことがあるということで、提供会員の研修会と懇談会ということを年に数回設けておりまして。","voiceIndex":117,"id":"exchange-043"},{"speaker":"こんの委員","kind":"質問","question":"提供会員と利用者とも人間関係というか対応はどうですかとアドバイザーから聞かれることはあっても、その利用者のリスクを背負いそうだというところの手当てをしたいという相談の窓口はないので、そうしたものがあるともっとよりいいサポートができるのではないかというご意見もありました。","respondent":"廣田子ども家庭支援課長","answer":"私のほうも、そういう研修会、懇親会にとどまらず、せっかくそういう機会を設けているので、一歩踏み込んでどんなことがありますかということが聞けるような場面ができないかというところを２カ所ファミリー・サポート・センターの拠点がありますので。","voiceIndex":119,"id":"exchange-044"},{"speaker":"松永委員","kind":"質問","question":"理由についてお知らせください。他にはそういったことを受けられているのかということもお伺いいたします。大井図書館に関しては、１年目はトラブルが多いということで、今は安定しているということなのですが、トラブルが減ったということなのか、現状普通どおりに営業されているということなのかについても伺いたいと思います。","respondent":"横山品川図書館長","answer":"防火訓練、避難訓練につきましても、たまたま会社が全部１階ですので、その計画に基づきまして一定の水準に基づいて各館で動いているものです。","voiceIndex":122,"id":"exchange-045"},{"speaker":"松永委員","kind":"意見","question":"その防火訓練というのはどういうものなのかということを聞いたのですが、例えば家庭あんしんセンターにつきましては、独自のマニュアルがあるということが書いてあったのですけれども、図書館に関しても各館によって多分独自のマニュアルが必要ではないかと思うのですが、そういうものはあるのかどうか。","respondent":"横山品川図書館長","answer":"各館でやり方自体は違うのですけれども、それぞれで行っているということで、またマニュアルにつきましても、簡易なものから詳細なものまでレベルは違うのですけれども、各館でそろえて運営をしているような状況です。","voiceIndex":124,"id":"exchange-046"},{"speaker":"のだて委員","kind":"質問","question":"やはり指定管理者制度というのが、こういった施設になじまないのではないかなというふうな印象を受けましたけれども、そういった点で指定管理者制度を変えていくという検討も必要なのではないかと思いますが、いかがでしょうか。","respondent":"横山品川図書館長、廣田子ども家庭支援課長","answer":"指定管理者制度で図書の業務を担っていただくことにつきましては、仮に職員全部でやった場合には、今の状況のように司書の資格を持った方がほとんどという状況はとても望めない状況でございましたし。家庭あんしんセンターにつきましては、母子生活支援施設であるひまわり荘を抱えておりますので、生活している施設で夜に何かあるかもということなどわからないような状況であったり、ショートステイ。","voiceIndex":126,"id":"exchange-047"}]},{"id":"topic-05","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"本会議の場で待機児ゼロに向けて、平成３０年度４月の待機児ゼロの見通しがつきそうだという話がありまして、その具体的な数字、需要見込みですとか、認可保育園が何園何人分など、また施設についても、それでゼロになるという具体的なところを教えていただきたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"平成３０年４月の申込み予測ですが、０歳から２歳児の人数でご説明します。予測といたしまして申込者数は２,９４４人、認可、地域型入園者数が２,３０１人、認証保育所の入園者等が６４１人で、この計算ですと待機児童は２人となりますので、０人の見通しがたちつつあるです。","voiceIndex":131,"id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"数字の関係はわかりました。しかし、２人の待機児童が出る可能性があるということで、そこはゼロにしていっていただきたいと思います。その姿勢を伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"今の数字はあくまでも予測ですので、想定外の人数の増加とまた申込者数の偏り等がある可能性もありますので、今現在だけの計画ではなく、他の対応を含めて今後も検討して、平成３０年４月にはゼロを目指していきたいと考えています。","voiceIndex":135,"id":"exchange-049"},{"speaker":"南委員","kind":"確認","question":"確認なのですけれども、来年の４月には認可保育園が１６園できるということ、認証保育園が１園で、それぞれトータルして１,４０４人という説明だったと思いますけれども、それを確認したいのと、それから、入所申請数が来年４月にかけて２,９４４人という数字でよろしいでしょうか。数字の確認を先にお願いします。","respondent":"大澤待機児童対策担当課長","answer":"今委員がおっしゃったとおりの数字です。","voiceIndex":137,"id":"exchange-050"},{"speaker":"南委員","kind":"質問・要望","question":"そうしますと、私も全部自分で計算したわけではないので、認識をちょっとできていないのですけれども、来年４月にかけて入所申請数が２,９４４人というのは、この間の状況と比較して、過去の、今年度も含めて、申請数が増えているというふうに認識していいのか、減っていると認識していいのか、ちょっとそのあたりを教えていただきたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"最新の申込者数の増加率が４.４％ですので、その４.４％を受けまして平成２９年度の申込者数に４.４％を足した数で出しております。","voiceIndex":139,"id":"exchange-051"},{"speaker":"南委員","kind":"確認","question":"１,４０４人の新しいキャパシティができるということなのですけれども、それはそれとして努力については受けとめていきたいと思っているのですけれども、入所申請の数を見て、１,４０４人という数が見込まれるので、定員をそれだけ確保できるのでオーケーだということなのだと思うのですけれども、この２,９４４人に４.４％を掛けるのだけれども。","respondent":"大澤待機児童対策担当課長","answer":"マンション開設についても、人口の中には加味しておりますけれども、それによって地域ごとに多少のばらつきが出ると思いますので、そこは最終的に地域別、年齢別の詳細な分析を今している最中ですので、それが出た時点で足りないところがあれば。","voiceIndex":141,"id":"exchange-052"},{"speaker":"南委員","kind":"質問・要望","question":"それで、４月時点で認可保育園１６園というところの中には、昨日の委員会で議題として、陳情にあったキッズガーデン小山も入って想定しているということなのか、ちょっと確認したいのと、それから今最後に課長がご答弁された２,９４４人の申請を受けとめきれない部分が出たら、それはそのときに考えるという話なのだけれども、それはぜひそういう方向でしっかり準備をしていただきたいと思っているのですが。","respondent":"大澤待機児童対策担当課長","answer":"昨日の話の続きとして、引き続き住民の方とは調整を図って、何とか４月にはご納得いただければというふうに考えております。そして、この他対応ですけれども、もちろん４月に間に合うように何らかの対策を講じてまいります。","voiceIndex":143,"id":"exchange-053"},{"speaker":"南委員","kind":"質問・要望","question":"何らかの対応をしていくということで、心強いなというふうに思っているのですけれども、来年度こそは待機児童で悲しい思いをさせることがないようにしていただきたいというふうに思っています。その点についての決意、それを伺って終わりにしたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"平成３０年４月にゼロを目指して今後とも努力をしてまいります。","voiceIndex":145,"id":"exchange-054"},{"speaker":"南委員","kind":"質問・要望","question":"認証保育園が閉園ということの件なのですけれども、同社の近隣園に編入という対応は当然だというふうに思うのですけれども、勤務時間だとか、そういった保育時間に直接的にかかわることなので、どのくらいの距離のところにあるのかとか、また何人ぐらいの方がそういう状況に該当されるのかとか、その辺がわかったら教えていただきたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"その方たちには、できれば認可保育園等への編入を進めているということで、ご希望があればアートチャイルドの認証に優先的にですけれども、近くでは大田区の馬込に１園あります。","voiceIndex":158,"id":"exchange-055"},{"speaker":"南委員","kind":"確認","question":"わかりました。保育園というのは継続性があって、入っている期間には少なくともこういう形で途中で途切れるようなことがないことが大前提だと思うのですけれども、当初から平成３１年３月で終わりですよと言っていたわけではないのではと思っているので、その辺の確認をしたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"建物の賃借期間につきまして期間の延長を打診したけれども、オーナーから延長できないとの返事があったということで、近隣に代替地を探したけれども、どうしても見つからなくて、閉園せざるを得なくなったという事情です。","voiceIndex":160,"id":"exchange-056"},{"speaker":"南委員","kind":"質問・要望","question":"オーナーのいろいろなご事情もあると思うのだけれども、できるだけこういう保育事業において、継続性が必要なので、そういうことを理由に閉園していくのは、やはりできるだけ避けるべきだというふうに思っております。こういうオーナーの許可がいただけないということで閉園に追い込まれてしまう今回のケースについては、区はどういうふうに思っているのですか、そこを伺って終わりにしたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"区として気を配らなければいけないのは、やはり今入っている方がどこにも行き場がなくなることだと思いますので、それについては東京都とともにきちんと転園先を確保できるように事業者のほうにも働きかけていきたいと考えています。","voiceIndex":162,"id":"exchange-057"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4924#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":75674,"voices":169}}]);
